  id: string;
  title: string;
  author: { id: string; name: string };
  tags: string[];
  body: string;
  createdAt: string;
}
```

You can start here and evolve toward the fuller model as requirements grow. For runtime validation (e.g. API input), consider defining these with **Zod** and inferring the types via `z.infer<typeof schema>`.

Here's a well-structured TypeScript data model for a blog post, with explanations of the design decisions.

## Core Types

```typescript
// ============================================
// Branded ID types (prevent mixing up IDs)
// ============================================
type Brand<T, B extends string> = T & { readonly __brand: B };

export type PostId = Brand<string, "PostId">;
export type AuthorId = Brand<string, "AuthorId">;
export type TagId = Brand<string, "TagId">;

// ISO 8601 timestamp string, e.g. "2024-05-01T12:00:00Z"
export type ISODateString = Brand<string, "ISODateString">;

// ============================================
// Author
// ============================================
export interface Author {
  id: AuthorId;
  name: string;
  slug: string;              // URL-friendly, e.g. "jane-doe"
  email?: string;            // Often private; omit from public payloads
  avatarUrl?: string;
  bio?: string;
}

// Lightweight version embedded in a post response
export type AuthorSummary = Pick<Author, "id" | "name" | "slug" | "avatarUrl">;

// ============================================
// Tag
// ============================================
export interface Tag {
  id: TagId;
  name: string;              // Display name: "TypeScript"
  slug: string;              // URL-friendly: "typescript"
}

// ============================================
// Body (discriminated union for content format)
// ============================================
export type PostBody =
  | { format: "markdown"; content: string }
  | { format: "html"; content: string }
  | { format: "blocks"; blocks: ContentBlock[] };

export type ContentBlock =
  | { type: "paragraph"; text: string }
  | { type: "heading"; level: 1 | 2 | 3 | 4 | 5 | 6; text: string }
  | { type: "image"; url: string; alt: string; caption?: string }
  | { type: "code"; language?: string; code: string }
  | { type: "quote"; text: string; attribution?: string }
  | { type: "list"; style: "ordered" | "unordered"; items: string[] };

// ============================================
// Post status (discriminated union for lifecycle)
// ============================================
export type PostStatus =
  | { state: "draft" }
  | { state: "scheduled"; publishAt: ISODateString }
  | { state: "published"; publishedAt: ISODateString }
  | { state: "archived"; archivedAt: ISODateString };

// ============================================
// Blog Post
// ============================================
export interface BlogPost {
  id: PostId;
  title: string;
  slug: string;              // e.g. "designing-typescript-models"
  excerpt?: string;          // Short summary for listings/SEO
  authorId: AuthorId;        // Normalized reference
  tagIds: TagId[];
  body: PostBody;
  status: PostStatus;
  createdAt: ISODateString;
  updatedAt: ISODateString;
}
```

## Derived Types for Common Use Cases

```typescript
// API response with relations resolved (denormalized)
export interface BlogPostView extends Omit<BlogPost, "authorId" | "tagIds"> {
  author: AuthorSummary;
  tags: Tag[];
  readingTimeMinutes?: number;
}

// Payload for creating a post (server generates id, timestamps)
export type CreateBlogPostInput = Omit<
  BlogPost,
  "id" | "createdAt" | "updatedAt" | "status"
> & {
  status?: PostStatus;       // Defaults to draft
};

// Payload for updating (everything optional except identity)
export type UpdateBlogPostInput = Partial<
  Omit<BlogPost, "id" | "authorId" | "createdAt" | "updatedAt">
>;

// Card/listing view without the heavy body
export type BlogPostSummary = Omit<BlogPostView, "body">;
```

## Usage Example

```typescript
const post: BlogPostView = {
  id: "post_123" as PostId,
  title: "Designing Data Models in TypeScript",
  slug: "designing-data-models-in-typescript",
  excerpt: "How to use the type system to make invalid states unrepresentable.",
  author: {
    id: "auth_42" as AuthorId,
    name: "Jane Doe",
    slug: "jane-doe",
  },
  tags: [
    { id: "tag_1" as TagId, name: "TypeScript", slug: "typescript" },
  ],
  body: {
    format: "markdown",
    content: "# Hello\n\nThis is the post body.",
  },
  status: { state: "published", publishedAt: "2024-05-01T12:00:00Z" as ISODateString },
  createdAt: "2024-04-28T09:00:00Z" as ISODateString,
  updatedAt: "2024-05-01T12:00:00Z" as ISODateString,
};

// Type narrowing works naturally
function renderBody(body: PostBody): string {
  switch (body.format) {
    case "markdown": return markdownToHtml(body.content);
    case "html":     return body.content;
    case "blocks":   return body.blocks.map(renderBlock).join("");
  }
}

declare function markdownToHtml(md: string): string;
declare function renderBlock(block: ContentBlock): string;
```

## Key Design Decisions

| Decision | Rationale |
|---|---|
| **Branded IDs** | Prevents passing an `AuthorId` where a `PostId` is expected; zero runtime cost. |
| **Author/Tags as separate entities** | Avoids duplicating author data across posts; renaming a tag updates everywhere. |
| **Normalized (`BlogPost`) vs. resolved (`BlogPostView`)** | Storage shape differs from what the UI needs; both are explicit. |
| **`PostStatus` as a discriminated union** | Makes invalid states unrepresentable, e.g. a draft can't have a `publishedAt`. |
| **`PostBody` as a discriminated union** | Supports Markdown, HTML, or structured blocks, and is easy to extend. |
| **Slugs on posts, authors, tags** | Enables clean URLs independent of IDs. |
| **ISO strings for dates** | JSON-serializable; convert to `Date` at the edges if needed. |
| **Derived input types via `Omit`/`Partial`** | Single source of truth; changes to `BlogPost` propagate automatically. |

## Simpler Alternative

If you don't need all that flexibility, a minimal version is perfectly fine:

```typescript
