## Helpers

```typescript
// Type guard for narrowing on status
export function isPublished(
  post: BlogPost
): post is BlogPost & { status: Extract<PostStatus, { kind: "published" }> } {
  return post.status.kind === "published";
}

// Smart constructor — the only way to create a Slug
export function toSlug(input: string): Slug {
  return input
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9\s-]/g, "")
    .replace(/\s+/g, "-")
    .replace(/-+/g, "-") as Slug;
}

// Exhaustive handling — compiler errors if a new status is added
export function statusLabel(status: PostStatus): string {
  switch (status.kind) {
    case "draft":     return "Draft";
    case "scheduled": return `Scheduled for ${status.publishAt}`;
    case "published": return `Published ${status.publishedAt}`;
    case "archived":  return "Archived";
    default: {
      const _exhaustive: never = status;
      return _exhaustive;
    }
  }
}
```

