// ---------- Blog Post ----------
export interface BlogPost {
  id: PostId;
  slug: string;                  // "designing-data-models-in-ts"
  title: string;
  excerpt?: string;              // short summary for listings / SEO
  body: PostBody;

  authorId: AuthorId;            // normalized reference
  tagIds: TagId[];

  status: PostStatus;
  createdAt: ISODateString;
  updatedAt: ISODateString;
  publishedAt?: ISODateString;   // set when status becomes "published"
}
```

## Derived Types for Common Use Cases

```typescript
// A post with relations resolved, for rendering a page.
export interface BlogPostWithRelations extends Omit<BlogPost, "authorId" | "tagIds"> {
  author: Author;
  tags: Tag[];
}

// Input for creating a post: server generates id and timestamps.
export type CreateBlogPostInput = {
  title: string;
  body: PostBody;
  authorId: AuthorId;
  tagIds?: TagId[];
  slug?: string;        // auto-generated from title if omitted
  excerpt?: string;
  status?: Extract<PostStatus, "draft" | "published">;
};

// Input for updating: everything optional except identity.
export type UpdateBlogPostInput = Partial<
  Omit<BlogPost, "id" | "createdAt" | "updatedAt">
> & { id: PostId };

// Lightweight shape for list views (no body).
export type BlogPostSummary = Pick<
  BlogPost,
  "id" | "slug" | "title" | "excerpt" | "publishedAt"
> & {
  author: Pick<Author, "id" | "name" | "slug" | "avatarUrl">;
  tags: Tag[];
