  id: string;
  title: string;
  author: { id: string; name: string };
  tags: string[];
  body: string;
  createdAt: string;
}
```

Here's a TypeScript data model for a blog post. It separates the core entities, uses branded IDs for type safety, and distinguishes between stored data and input data.

```typescript
// ============================================================
// Branded ID types — prevent accidentally mixing up IDs
// ============================================================
type Brand<T, B extends string> = T & { readonly __brand: B };

export type PostId = Brand<string, "PostId">;
export type AuthorId = Brand<string, "AuthorId">;
export type TagId = Brand<string, "TagId">;

/** ISO 8601 timestamp string, e.g. "2024-05-01T12:00:00Z" */
export type ISODateString = Brand<string, "ISODateString">;

/** URL-safe identifier, e.g. "my-first-post" */
export type Slug = Brand<string, "Slug">;

// ============================================================
// Author
// ============================================================
export interface Author {
  readonly id: AuthorId;
  name: string;
  email: string;
  bio?: string;
  avatarUrl?: string;
}

/** Lightweight author info embedded in a post (avoids over-fetching) */
export type AuthorSummary = Pick<Author, "id" | "name" | "avatarUrl">;

// ============================================================
// Tag
// ============================================================
export interface Tag {
  readonly id: TagId;
  name: string;   // Display name: "TypeScript"
  slug: Slug;     // URL form: "typescript"
}

// ============================================================
// Body
// ============================================================
/** Discriminated union so the body format is explicit and extensible */
export type PostBody =
  | { format: "markdown"; content: string }
  | { format: "html"; content: string }
  | { format: "plaintext"; content: string };

// ============================================================
// Post status — models the publishing lifecycle
// ============================================================
export type PostStatus =
  | { state: "draft" }
  | { state: "scheduled"; publishAt: ISODateString }
  | { state: "published"; publishedAt: ISODateString }
  | { state: "archived"; archivedAt: ISODateString };

// ============================================================
// Blog Post
// ============================================================
export interface BlogPost {
  readonly id: PostId;
  title: string;
  slug: Slug;
  excerpt?: string;
  author: AuthorSummary;
  tags: readonly Tag[];
  body: PostBody;
  status: PostStatus;
  readonly createdAt: ISODateString;
  updatedAt: ISODateString;
}

// ============================================================
// Input types — what clients send (server assigns IDs/timestamps)
// ============================================================
export interface CreatePostInput {
  title: string;
  slug?: string;          // Optional: derive from title if omitted
  excerpt?: string;
  authorId: AuthorId;     // Reference by ID, not embedded object
  tagIds: TagId[];
  body: PostBody;
  status?: PostStatus;    // Defaults to draft
}

export type UpdatePostInput = Partial<Omit<CreatePostInput, "authorId">>;
```

## Example usage

```typescript
const post: BlogPost = {
  id: "post_123" as PostId,
  title: "Designing Type-Safe Data Models",
  slug: "designing-type-safe-data-models" as Slug,
  author: {
    id: "author_42" as AuthorId,
    name: "Ada Lovelace",
  },
  tags: [
    { id: "tag_1" as TagId, name: "TypeScript", slug: "typescript" as Slug },
  ],
  body: {
    format: "markdown",
    content: "# Hello\n\nThis is my post.",
  },
  status: { state: "published", publishedAt: "2024-05-01T12:00:00Z" as ISODateString },
  createdAt: "2024-04-28T09:00:00Z" as ISODateString,
  updatedAt: "2024-05-01T12:00:00Z" as ISODateString,
};

// Discriminated unions enable exhaustive, type-safe handling:
function describeStatus(status: PostStatus): string {
  switch (status.state) {
    case "draft":     return "Draft";
    case "scheduled": return `Scheduled for ${status.publishAt}`;
    case "published": return `Published ${status.publishedAt}`;
    case "archived":  return `Archived ${status.archivedAt}`;
  }
}
```

## Key design decisions

| Decision | Rationale |
|---|---|
| **Branded IDs** | Prevents passing an `AuthorId` where a `PostId` is expected. Zero runtime cost. |
| **`Tag` as an object, not `string[]`** | Separates display name from URL slug and supports renaming without breaking links. Use `string[]` if you want something simpler. |
| **`AuthorSummary` embedded** | Posts usually only need name/avatar, not the author's email or full bio. |
| **Discriminated union for `body`** | Renderers know exactly how to handle content, and new formats can be added safely. |
| **Discriminated union for `status`** | Makes illegal states unrepresentable: a draft can't have a `publishedAt`, and a scheduled post must have a `publishAt`. |
| **Separate input types** | Clients shouldn't supply `id`, `createdAt`, etc. Inputs reference related entities by ID. |
| **`readonly` on immutable fields** | Signals that `id` and `createdAt` never change after creation. |

