```typescript
// ============================================
// Branded ID types (prevent mixing up IDs)
// ============================================

type Brand<T, B extends string> = T & { readonly __brand: B };

export type PostId = Brand<string, "PostId">;
export type AuthorId = Brand<string, "AuthorId">;
export type TagId = Brand<string, "TagId">;

/** ISO 8601 timestamp string, e.g. "2024-05-01T12:00:00.000Z" */
export type ISODateString = Brand<string, "ISODateString">;

// ============================================
// Author
// ============================================

export interface Author {
  readonly id: AuthorId;
  name: string;
  /** URL-safe unique handle, e.g. "jane-doe" */
  slug: string;
  email?: string;
  bio?: string;
  avatarUrl?: string;
}

/** Lightweight author reference embedded in posts (avoids over-fetching). */
export type AuthorSummary = Pick<Author, "id" | "name" | "slug" | "avatarUrl">;

// ============================================
// Tag
// ============================================

export interface Tag {
  readonly id: TagId;
  /** Display name, e.g. "TypeScript" */
  name: string;
  /** Normalized URL-safe form, e.g. "typescript" */
  slug: string;
}

// ============================================
// Body
// ============================================

/**
 * Discriminated union so the renderer knows how to interpret the content.
 * Easy to extend later (e.g. a structured block-editor format).
 */
export type PostBody =
  | { format: "markdown"; content: string }
  | { format: "html"; content: string }
  | { format: "plaintext"; content: string };

// ============================================
// Status (discriminated union)
// ============================================

/**
 * Encodes status-dependent fields in the type system:
 * a published post always has a publishedAt; a draft never does.
 */
export type PostStatus =
  | { kind: "draft" }
  | { kind: "scheduled"; publishAt: ISODateString }
  | { kind: "published"; publishedAt: ISODateString }
  | { kind: "archived"; publishedAt: ISODateString; archivedAt: ISODateString };

// ============================================
// Blog Post
// ============================================

export interface BlogPost {
  readonly id: PostId;
  title: string;
  /** URL-safe identifier derived from the title, e.g. "my-first-post" */
  slug: string;
  /** Short summary for previews, cards, and SEO descriptions. */
  excerpt?: string;
  author: AuthorSummary;
  tags: Tag[];
  body: PostBody;
  status: PostStatus;
  readonly createdAt: ISODateString;
  updatedAt: ISODateString;
}

// ============================================
// Input types (for API / form operations)
// ============================================

/** Payload for creating a post. Server generates id, slug, and timestamps. */
export interface CreateBlogPostInput {
  title: string;
  authorId: AuthorId;
  /** Tag names; the server resolves or creates matching Tag records. */
  tags: string[];
  body: PostBody;
  excerpt?: string;
  /** Optional custom slug; defaults to one derived from the title. */
  slug?: string;
}

/** Payload for updating a post. All fields optional; id is required. */
export type UpdateBlogPostInput = { id: PostId } & Partial<
  Omit<CreateBlogPostInput, "authorId">
>;

/** Compact representation for list views (no body). */
export type BlogPostSummary = Omit<BlogPost, "body">;
```

