  | { state: "draft" }
  | { state: "scheduled"; publishAt: ISODateString }
  | { state: "published"; publishedAt: ISODateString }
  | { state: "archived"; archivedAt: ISODateString };

// ---------- Blog Post ----------
export interface BlogPost {
  readonly id: PostId;
  title: string;
  slug: string;              // e.g. "designing-typescript-models"
  excerpt?: string;          // Short summary for listings / SEO
  author: AuthorSummary;
  tags: readonly Tag[];
  body: PostBody;
  status: PostStatus;
  readonly createdAt: ISODateString;
  updatedAt: ISODateString;
}

// ---------- Input / DTO types ----------
// What a client sends to create a post: server assigns id, timestamps, and resolves relations.
export interface CreateBlogPostInput {
  title: string;
  slug?: string;             // Optional: server can derive from title
  excerpt?: string;
  authorId: AuthorId;
  tagIds: TagId[];
  body: PostBody;
}

// Partial update; id is passed separately (e.g. in the URL).
export type UpdateBlogPostInput = Partial<CreateBlogPostInput>;

// Compact shape for list/index pages (no body).
export type BlogPostSummary = Pick<
  BlogPost,
  "id" | "title" | "slug" | "excerpt" | "author" | "tags" | "status"
>;
```

### Example usage

```typescript
const post: BlogPost = {
  id: "post_123" as PostId,
  title: "Designing TypeScript Data Models",
  slug: "designing-typescript-data-models",
  excerpt: "How to model domain data safely with TypeScript.",
  author: {
    id: "auth_1" as AuthorId,
    name: "Jane Doe",
    slug: "jane-doe",
  },
  tags: [{ id: "tag_ts" as TagId, name: "TypeScript", slug: "typescript" }],
  body: { format: "markdown", content: "# Hello\n\nThis is the post body." },
  status: { state: "published", publishedAt: "2024-05-01T12:00:00Z" as ISODateString },
  createdAt: "2024-04-28T09:00:00Z" as ISODateString,
  updatedAt: "2024-05-01T12:00:00Z" as ISODateString,
};

// Exhaustive handling thanks to discriminated unions:
function renderBody(body: PostBody): string {
  switch (body.format) {
    case "markdown": return markdownToHtml(body.content);
    case "html":     return body.content;
    case "blocks":   return body.content.map(renderBlock).join("");
  }
}
```

### Key design decisions

| Decision | Why |
|---|---|
| **Branded IDs** | Catches mix-ups like passing an `AuthorId` as a `PostId` at compile time. |
| **Author as a separate entity** | Authors write many posts; the post embeds a lightweight `AuthorSummary` rather than the full profile. |
| **Tags as objects, not strings** | Gives each tag a stable ID and slug for URLs, and allows renaming without breaking references. (Use `string[]` if you want maximum simplicity.) |
| **Body as a discriminated union** | Makes the content format explicit and supports exhaustive `switch` handling. |
| **Status as a union with data** | Makes invalid states unrepresentable: a `published` post *must* have `publishedAt`, a draft can't. |
| **ISO strings for dates** | Serializes cleanly to/from JSON; convert to `Date` at the edges if needed. |
| **Separate input types** | Clients shouldn't supply `id`, `createdAt`, etc. Distinct DTOs make the API contract clear. |

If you want a simpler version, you could collapse it to `tags: string[]`, `body: string` (markdown), and `author: { id: string; name: string }`. The structure above scales better as the blog grows.

Here's a well-structured TypeScript data model for a blog post, with explanations of the design decisions.

## Core Types

```typescript
// ============================================
// Branded ID types (prevent mixing up IDs)
// ============================================
type Brand<T, B extends string> = T & { readonly __brand: B };

export type PostId = Brand<string, "PostId">;
export type AuthorId = Brand<string, "AuthorId">;
export type TagId = Brand<string, "TagId">;

// ISO 8601 timestamp string, e.g. "2024-05-01T12:00:00Z"
export type ISODateString = Brand<string, "ISODateString">;

// URL-safe identifier, e.g. "my-first-post"
export type Slug = Brand<string, "Slug">;

// ============================================
// Author
// ============================================
export interface Author {
  readonly id: AuthorId;
  name: string;
  slug: Slug;
  email?: string;
  bio?: string;
  avatarUrl?: string;
  socialLinks?: Partial<Record<"twitter" | "github" | "linkedin" | "website", string>>;
}

// Lightweight version embedded in posts (avoids over-fetching)
export type AuthorSummary = Pick<Author, "id" | "name" | "slug" | "avatarUrl">;

// ============================================
// Tag
// ============================================
export interface Tag {
  readonly id: TagId;
  name: string;   // Display name: "TypeScript"
  slug: Slug;     // URL form: "typescript"
  description?: string;
}

// ============================================
// Body (content)
// ============================================
// Discriminated union lets you support multiple formats safely.
export type PostBody =
  | { format: "markdown"; content: string }
  | { format: "html"; content: string }
  | { format: "blocks"; blocks: ContentBlock[] };

export type ContentBlock =
  | { type: "paragraph"; text: string }
  | { type: "heading"; level: 1 | 2 | 3 | 4 | 5 | 6; text: string }
  | { type: "image"; src: string; alt: string; caption?: string }
  | { type: "code"; language?: string; code: string }
  | { type: "quote"; text: string; attribution?: string }
  | { type: "list"; ordered: boolean; items: string[] };

// ============================================
// Post status (discriminated union)
// ============================================
// Ensures publishedAt exists *only* when the post is published.
export type PostStatus =
  | { state: "draft" }
  | { state: "scheduled"; scheduledFor: ISODateString }
  | { state: "published"; publishedAt: ISODateString }
  | { state: "archived"; archivedAt: ISODateString; publishedAt?: ISODateString };

// ============================================
// Blog Post
// ============================================
export interface BlogPost {
  readonly id: PostId;
  title: string;
  slug: Slug;
  excerpt?: string;
  body: PostBody;
  author: AuthorSummary;
  tags: Tag[];
  status: PostStatus;
  coverImage?: { url: string; alt: string };
  readonly createdAt: ISODateString;
  updatedAt: ISODateString;
}
```

## Input / DTO Types

Separating "what the client sends" from "what the server stores" prevents clients from setting IDs or timestamps.

```typescript
// Creating a post: server generates id, timestamps, and resolves author
export interface CreatePostInput {
  title: string;
  slug?: string;          // optional, server can derive from title
  excerpt?: string;
  body: PostBody;
  authorId: AuthorId;
  tagIds: TagId[];
  coverImage?: { url: string; alt: string };
}

// Updating: everything optional except the id
export type UpdatePostInput = { id: PostId } & Partial<Omit<CreatePostInput, "authorId">>;

// Normalized storage shape (e.g., for a database row), with references, not embedded objects
export interface BlogPostRecord extends Omit<BlogPost, "author" | "tags"> {
  authorId: AuthorId;
  tagIds: TagId[];
}
```

## Helpers & Type Guards

```typescript
export const isPublished = (
  post: BlogPost
): post is BlogPost & { status: Extract<PostStatus, { state: "published" }> } =>
  post.status.state === "published";

export const toSlug = (input: string): Slug =>
  input
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9\s-]/g, "")
    .replace(/\s+/g, "-")
    .replace(/-+/g, "-") as Slug;
```

## Example Usage

```typescript
const post: BlogPost = {
  id: "post_123" as PostId,
  title: "Designing Type-Safe Data Models",
  slug: toSlug("Designing Type-Safe Data Models"),
  excerpt: "How to use TypeScript to make invalid states unrepresentable.",
  body: {
    format: "markdown",
    content: "# Intro\n\nTypes are documentation that never lies...",
  },
  author: {
    id: "auth_1" as AuthorId,
    name: "Jane Doe",
    slug: "jane-doe" as Slug,
  },
