Here's a well-structured set of TypeScript types for a product page. The long description is modeled as structured rich text (rather than raw HTML) so it's safe to render and easy to work with.

```typescript
// ============================================
// Money / Price
// ============================================

/** ISO 4217 currency code */
export type CurrencyCode = "USD" | "EUR" | "GBP" | "JPY" | "CAD" | "AUD" | (string & {});

export interface Money {
  /** Amount in the smallest currency unit (e.g. cents) to avoid floating-point errors */
  amount: number;
  currency: CurrencyCode;
}

export interface Price {
  current: Money;
  /** Original price, if the product is on sale */
  compareAt?: Money;
}

// ============================================
// Images
// ============================================

export interface ProductImage {
  id: string;
  url: string;
  /** Required for accessibility */
  alt: string;
  width: number;
  height: number;
  /** Optional responsive variants */
  srcSet?: ReadonlyArray<{ url: string; width: number }>;
}

/** Guarantees at least one image exists */
export type NonEmptyArray<T> = readonly [T, ...T[]];

// ============================================
// Rich Text (Formatted Description)
// ============================================

/** Inline text formatting marks */
export type TextMark =
  | { type: "bold" }
  | { type: "italic" }
  | { type: "underline" }
  | { type: "strikethrough" }
  | { type: "code" }
  | { type: "link"; href: string; openInNewTab?: boolean };

/** A run of text with optional formatting */
export interface TextNode {
  type: "text";
  text: string;
  marks?: readonly TextMark[];
}

export interface LineBreakNode {
  type: "lineBreak";
}

export type InlineNode = TextNode | LineBreakNode;

export interface ParagraphBlock {
  type: "paragraph";
  children: readonly InlineNode[];
}

export interface HeadingBlock {
  type: "heading";
  level: 2 | 3 | 4 | 5 | 6; // h1 reserved for the product name
  children: readonly InlineNode[];
}

export interface ListItem {
  children: readonly InlineNode[];
  /** Nested lists */
  sublist?: ListBlock;
}

export interface ListBlock {
  type: "list";
  style: "bulleted" | "numbered";
  items: readonly ListItem[];
}

export interface QuoteBlock {
  type: "quote";
  children: readonly InlineNode[];
  attribution?: string;
}

export interface ImageBlock {
  type: "image";
  image: ProductImage;
  caption?: string;
}

export interface DividerBlock {
  type: "divider";
}

export type DescriptionBlock =
  | ParagraphBlock
  | HeadingBlock
  | ListBlock
  | QuoteBlock
  | ImageBlock
  | DividerBlock;

export interface RichText {
  blocks: readonly DescriptionBlock[];
}

// ============================================
// Product
// ============================================

export interface Product {
  id: string;
  slug: string;
  name: string;
  price: Price;
  images: NonEmptyArray<ProductImage>;
  /** Optional short plain-text summary (useful for SEO / cards) */
  summary?: string;
  description: RichText;
}

// ============================================
// Product Page
// ============================================

export interface ProductPageProps {
  product: Product;
}
```

