### Example renderer with exhaustiveness checking

```typescript
function assertNever(x: never): never {
  throw new Error(`Unhandled block: ${JSON.stringify(x)}`);
}

function renderBlock(block: DescriptionBlock) {
  switch (block.type) {
    case "paragraph": /* ... */ break;
    case "heading":   /* block.level is 2 | 3 | 4 */ break;
    case "list":      /* block.items */ break;
    case "quote":     /* ... */ break;
    case "image":     /* block.image.alt */ break;
    case "divider":   /* ... */ break;
    default:
      assertNever(block); // compile error if a new block type is added but not handled
  }
}
```

