```typescript
// ---------- Primitives & Branded Types ----------

/** Branded types prevent accidentally mixing up IDs, URLs, etc. */
type Brand<T, B extends string> = T & { readonly __brand: B };

export type ProductId = Brand<string, "ProductId">;
export type ImageId = Brand<string, "ImageId">;
export type Url = Brand<string, "Url">;

/** ISO 4217 currency codes (extend as needed) */
export type CurrencyCode = "USD" | "EUR" | "GBP" | "JPY" | "CAD" | "AUD";

// ---------- Price ----------

export interface Money {
  /** Amount in minor units (e.g. cents) to avoid floating-point errors */
  amountMinor: number;
  currency: CurrencyCode;
}

export type Price =
  | { kind: "regular"; current: Money }
  | {
      kind: "sale";
      current: Money;
      original: Money;
      /** Optional ISO 8601 timestamp when the sale ends */
      endsAt?: string;
    };

// ---------- Images ----------

export interface ImageSource {
  url: Url;
  width: number;
  height: number;
  format?: "jpeg" | "png" | "webp" | "avif";
}

export interface ProductImage {
  id: ImageId;
  /** Required for accessibility */
  alt: string;
  /** Primary source plus optional responsive variants */
  src: ImageSource;
  variants?: readonly ImageSource[];
  caption?: string;
}

/** Guarantees at least one image exists */
export type NonEmptyArray<T> = readonly [T, ...T[]];

// ---------- Rich Text Description ----------

/** Inline formatting marks that can be combined */
export type TextMark =
  | { type: "bold" }
  | { type: "italic" }
  | { type: "underline" }
  | { type: "strikethrough" }
  | { type: "code" }
  | { type: "link"; href: Url; openInNewTab?: boolean };

/** Leaf text node */
export interface TextNode {
  type: "text";
  text: string;
  marks?: readonly TextMark[];
}

export interface LineBreakNode {
  type: "lineBreak";
}

export type InlineNode = TextNode | LineBreakNode;

// Block-level nodes

export interface ParagraphNode {
  type: "paragraph";
  children: readonly InlineNode[];
}

export interface HeadingNode {
  type: "heading";
  level: 2 | 3 | 4 | 5 | 6; // h1 reserved for the product name
  children: readonly InlineNode[];
}

export interface ListItemNode {
  type: "listItem";
  /** List items may contain paragraphs or nested lists */
  children: readonly (ParagraphNode | ListNode)[];
}

export interface ListNode {
  type: "list";
  ordered: boolean;
  children: readonly ListItemNode[];
}

export interface BlockquoteNode {
  type: "blockquote";
  children: readonly ParagraphNode[];
}

export interface CodeBlockNode {
  type: "codeBlock";
  language?: string;
  code: string;
}

export interface ImageBlockNode {
  type: "image";
  image: ProductImage;
}

export interface DividerNode {
  type: "divider";
}

export type BlockNode =
  | ParagraphNode
  | HeadingNode
  | ListNode
  | BlockquoteNode
  | CodeBlockNode
  | ImageBlockNode
  | DividerNode;

export interface RichTextDocument {
  type: "document";
  /** Schema version for future migrations */
  version: 1;
  children: readonly BlockNode[];
}

// ---------- Product Page ----------

export interface Product {
  id: ProductId;
  name: string;
  /** URL-friendly identifier */
  slug: string;
  price: Price;
  images: NonEmptyArray<ProductImage>;
  /** Optional plain-text summary for cards/SEO */
  shortDescription?: string;
  description: RichTextDocument;
}

export interface ProductPageSeo {
  title: string;
  metaDescription: string;
  canonicalUrl?: Url;
