### Rendering with exhaustive checks

The discriminated `type` field lets TypeScript verify that a renderer handles every node kind:

```ts
function assertNever(x: never): never {
  throw new Error(`Unhandled node: ${JSON.stringify(x)}`);
}

function blockToPlainText(node: BlockNode): string {
  switch (node.type) {
    case "paragraph":
    case "heading":
      return node.children.map(inlineToPlainText).join("");
    case "list":
      return node.children
        .map((li) =>
          li.children
            .map((c) => (c.type === "list" ? blockToPlainText(c) : inlineToPlainText(c)))
            .join("")
        )
        .join("\n");
    case "quote":
      return node.children.map(blockToPlainText).join("\n");
    case "image":
      return node.caption ?? "";
    case "divider":
      return "";
    default:
      return assertNever(node); // compile error if a new block type is added but not handled
  }
}

function inlineToPlainText(node: InlineNode): string {
  return node.type === "text" ? node.text : node.children.map((t) => t.text).join("");
}

function formatMoney({ amount, currency }: Money, locale = "en-US"): string {
  const digits = new Intl.NumberFormat(locale, { style: "currency", currency })
    .resolvedOptions().maximumFractionDigits ?? 2;
  return new Intl.NumberFormat(locale, { style: "currency", currency })
    .format(amount / 10 ** digits);
}
```

### Design notes

- **Integer minor units for money.** This avoids `0.1 + 0.2` style bugs. `formatMoney` handles currencies like JPY that have no decimal places.
- **`NonEmptyArray` for images.** A product page with no images is usually a data error, so the type rules it out.
- **Required `alt` text.** This enforces accessibility at the type level.
- **AST instead of an HTML string.** The structure is compatible in spirit with Portable Text, Slate, and Tiptap/ProseMirror JSON. If your CMS already outputs one of those formats, use its official types instead.
- **Simpler alternative:** if you control the content and want less structure, `description: { format: "markdown"; source: string }` works too. You would then render it with a sanitizing Markdown library.

