/** Branded string types prevent mixing up IDs and URLs accidentally. */
type Brand<T, B extends string> = T & { readonly __brand: B };

export type ProductId = Brand<string, "ProductId">;
export type ImageUrl = Brand<string, "ImageUrl">;

/** ISO 4217 currency codes (extend as needed). */
export type CurrencyCode = "USD" | "EUR" | "GBP" | "JPY" | "CAD" | "AUD";

// ---------- Price ----------

/**
 * Money is stored in the smallest currency unit (e.g. cents)
 * to avoid floating-point rounding errors.
 */
export interface Money {
  readonly amount: number; // integer, minor units (1999 = $19.99)
  readonly currency: CurrencyCode;
}

export type Price =
  | { readonly kind: "regular"; readonly current: Money }
  | {
      readonly kind: "sale";
      readonly current: Money;
      readonly original: Money; // shown struck-through
      readonly endsAt?: string; // ISO 8601 date
    };

// ---------- Images ----------

export interface ProductImage {
  readonly url: ImageUrl;
  readonly alt: string; // required for accessibility
  readonly width: number;
  readonly height: number;
  /** Optional responsive variants, e.g. for srcset. */
  readonly variants?: ReadonlyArray<{
    readonly url: ImageUrl;
    readonly width: number;
  }>;
}

/** Guarantees at least one image exists at the type level. */
export type NonEmptyArray<T> = readonly [T, ...T[]];

// ---------- Rich Text Description ----------

/** Inline formatting marks that can be combined. */
export type TextMark = "bold" | "italic" | "underline" | "strikethrough" | "code";

export interface TextNode {
  readonly type: "text";
  readonly text: string;
  readonly marks?: readonly TextMark[];
}

export interface LinkNode {
  readonly type: "link";
  readonly href: string;
  readonly children: readonly TextNode[];
}

export type InlineNode = TextNode | LinkNode;

export interface ParagraphBlock {
  readonly type: "paragraph";
  readonly children: readonly InlineNode[];
}

export interface HeadingBlock {
  readonly type: "heading";
  readonly level: 2 | 3 | 4; // h1 reserved for the product name
  readonly children: readonly InlineNode[];
}

export interface ListItem {
  readonly children: readonly InlineNode[];
  readonly nested?: ListBlock;
}

export interface ListBlock {
  readonly type: "list";
  readonly style: "bulleted" | "numbered";
  readonly items: readonly ListItem[];
}

export interface QuoteBlock {
  readonly type: "quote";
  readonly children: readonly InlineNode[];
}

export interface ImageBlock {
  readonly type: "image";
  readonly image: ProductImage;
  readonly caption?: string;
}

export type DescriptionBlock =
  | ParagraphBlock
  | HeadingBlock
  | ListBlock
  | QuoteBlock
  | ImageBlock;

export interface RichText {
  readonly blocks: readonly DescriptionBlock[];
}

// ---------- Product Page ----------

