          { type: "text", text: " every morning." },
        ],
      },
      { type: "heading", level: 2, children: [{ type: "text", text: "What's included" }] },
      {
        type: "list",
        style: "bulleted",
        items: [
          { children: [{ type: "text", text: "Ceramic dripper" }] },
          { children: [{ type: "text", text: "600ml glass carafe" }] },
        ],
      },
    ],
  },
};

// Exhaustive rendering with a discriminated union:
function renderBlock(block: DescriptionBlock): string {
  switch (block.type) {
    case "paragraph": return "<p>…</p>";
    case "heading":   return `<h${block.level}>…</h${block.level}>`;
    case "list":      return block.style === "numbered" ? "<ol>…</ol>" : "<ul>…</ul>";
    case "quote":     return "<blockquote>…</blockquote>";
    case "image":     return `<figure>…</figure>`;
    default: {
      const _exhaustive: never = block; // compile error if a block type is unhandled
      return _exhaustive;
    }
  }
}

function formatPrice({ amount, currency }: Money): string {
  const digits = currency === "JPY" ? 0 : 2;
  return new Intl.NumberFormat("en-US", { style: "currency", currency })
    .format(amount / 10 ** digits);
}
```

### Key design decisions

- **Structured rich text instead of an HTML string:** It avoids XSS risks from `dangerouslySetInnerHTML`, can render to web, native, or email, and lets TypeScript check that every block type is handled. If your CMS already returns Markdown or HTML, use `{ format: "markdown"; content: string }` instead.
- **Integer minor units for money:** `0.1 + 0.2 !== 0.3` makes floats unsafe for prices.
- **Discriminated `Price` union:** A sale price can't exist without an original price, and a regular price can't accidentally carry one.
- **`NonEmptyArray` for images:** The page always has a hero image, so you never need to handle `images[0]` being undefined.
- **Required `alt` text:** Accessibility is enforced by the compiler.
- **Heading levels 2–4 only:** The product name owns the page's `<h1>`.

