## Usage Examples

### Exhaustive rendering with type narrowing

Discriminated unions let TypeScript verify you handle every block type:

```typescript
function assertNever(x: never): never {
  throw new Error(`Unhandled block type: ${JSON.stringify(x)}`);
}

function renderBlock(block: DescriptionBlock): string {
  switch (block.type) {
    case "paragraph":
      return `<p>${block.children.map(renderInline).join("")}</p>`;
    case "heading":
      return `<h${block.level}>${block.children.map(renderInline).join("")}</h${block.level}>`;
    case "list": {
      const tag = block.style === "numbered" ? "ol" : "ul";
      return `<${tag}>${block.items.map(renderListItem).join("")}</${tag}>`;
    }
    case "quote":
      return `<blockquote>${block.children.map(renderInline).join("")}</blockquote>`;
    case "image":
      return `<img src="${block.image.src.url}" alt="${block.image.alt}" />`;
    case "table":
      return renderTable(block);
    case "divider":
      return "<hr />";
    default:
      return assertNever(block); // compile error if a case is missing
  }
}
```

