### Helper: formatting the price

```typescript
const MINOR_UNIT_DIGITS: Record<CurrencyCode, number> = {
  USD: 2, EUR: 2, GBP: 2, JPY: 0, CAD: 2, AUD: 2,
};

export function formatMoney(money: Money, locale = "en-US"): string {
  const digits = MINOR_UNIT_DIGITS[money.currency];
  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency: money.currency,
  }).format(money.amount / 10 ** digits);
}
```

### Design choices

- **Prices use integer minor units.** This avoids `0.1 + 0.2` floating-point bugs.
- **`Price` is a discriminated union.** A sale price must include the original price, so a "sale" with nothing to compare against can't be represented.
- **Images use non-empty tuples.** `[T, ...T[]]` guarantees at least one image (and at least one source per image) at compile time.
- **The description is a structured tree, not an HTML string.** It's XSS-safe, renderable on web or native, and exhaustively checkable with `switch (node.type)`. If your CMS outputs Markdown or HTML, convert it to this shape at the boundary.
- **Headings start at h2,** since the page's h1 is the product name. This keeps the document outline accessible.
- **Everything is `readonly`,** which suits data passed down as props.
- **The schema is versioned.** `version: 1` lets you migrate stored descriptions if the format changes.

If your descriptions come from a specific CMS (Contentful, Sanity, Shopify, etc.), I can adapt the rich-text types to match its format.

Here's a set of TypeScript types for a product page. The long description uses a structured rich-text model instead of raw HTML, which makes it safer to render and easier to validate.

```typescript
// ============================================================
// Primitives & Utilities
// ============================================================

/** ISO 4217 currency code, e.g. "USD", "EUR" */
export type CurrencyCode = "USD" | "EUR" | "GBP" | "JPY" | "CAD" | "AUD" | (string & {});

/** Branded types prevent mixing up plain strings/numbers */
export type ProductId = string & { readonly __brand: "ProductId" };
export type ImageId = string & { readonly __brand: "ImageId" };
export type Url = string & { readonly __brand: "Url" };

// ============================================================
// Price
// ============================================================

/**
 * Amounts are stored in the smallest currency unit (e.g. cents)
 * to avoid floating-point rounding errors.
 */
export interface Money {
  amount: number;
  currency: CurrencyCode;
}

export interface Price {
  current: Money;
  /** Original price, present when the product is on sale */
  compareAt?: Money;
}

// ============================================================
// Images
// ============================================================

export interface ImageSource {
  url: Url;
  width: number;
  height: number;
  format?: "jpeg" | "png" | "webp" | "avif";
}

export interface ProductImage {
  id: ImageId;
  /** Required for accessibility */
  alt: string;
  /** Primary/full-resolution source */
  src: ImageSource;
  /** Optional responsive variants for srcset */
  variants?: ImageSource[];
  /** Display order in the gallery */
  position: number;
  isPrimary?: boolean;
}

// ============================================================
// Rich Text (Formatted Description)
// ============================================================

/** Inline formatting marks that can be combined */
export type TextMark =
  | { type: "bold" }
  | { type: "italic" }
  | { type: "underline" }
  | { type: "strikethrough" }
  | { type: "code" }
  | { type: "link"; href: Url; openInNewTab?: boolean };

/** Inline content: text with optional marks, or a line break */
export type InlineNode =
  | { type: "text"; text: string; marks?: TextMark[] }
  | { type: "lineBreak" };

export type HeadingLevel = 2 | 3 | 4 | 5 | 6; // h1 reserved for product name

export interface ListItem {
  content: InlineNode[];
  /** Allows nested lists */
  children?: ListBlock;
}

export type ListBlock =
  | { type: "bulletList"; items: ListItem[] }
  | { type: "orderedList"; items: ListItem[]; start?: number };

/** Block-level content */
export type BlockNode =
  | { type: "paragraph"; content: InlineNode[] }
  | { type: "heading"; level: HeadingLevel; content: InlineNode[] }
  | ListBlock
  | { type: "blockquote"; content: BlockNode[] }
  | { type: "image"; imageId: ImageId; caption?: InlineNode[] }
  | { type: "divider" }
  | {
      type: "table";
      header?: InlineNode[][];
      rows: InlineNode[][][];
    };

export interface RichTextDocument {
  version: 1;
  blocks: BlockNode[];
}

// ============================================================
// Product Page
// ============================================================

export interface Product {
  id: ProductId;
  name: string;
  /** URL-friendly identifier */
  slug: string;
  price: Price;
  /** Ordered gallery; at least one image required */
  images: [ProductImage, ...ProductImage[]];
  /** Short plain-text summary for cards and meta tags */
  summary?: string;
  description: RichTextDocument;
}

export interface ProductPageProps {
  product: Product;
}
```

