export interface Author {
  id: AuthorId;
  name: string;
  email: string;
  bio?: string;
  avatarUrl?: string;
}

// ---------- Tag ----------

export interface Tag {
  id: TagId;
  /** Display name, e.g. "TypeScript" */
  name: string;
  /** URL-safe identifier, e.g. "typescript" */
  slug: string;
}

// ---------- Body ----------

/**
 * Body is a list of typed blocks rather than a raw string. This keeps
 * content structured, renderable on any platform, and easy to validate.
 */
export type BodyBlock =
  | { type: "paragraph"; text: string }
  | { type: "heading";   level: 1 | 2 | 3 | 4 | 5 | 6; text: string }
  | { type: "image";     url: string; alt: string; caption?: string }
  | { type: "code";      language?: string; code: string }
  | { type: "quote";     text: string; attribution?: string }
  | { type: "list";      ordered: boolean; items: string[] };

// ---------- Post ----------

export type PostStatus = "draft" | "published" | "archived";

interface PostBase {
  id: PostId;
  title: string;
  /** URL-safe identifier derived from the title */
  slug: string;
  /** Short summary for previews and SEO */
  excerpt?: string;
  body: BodyBlock[];
  tags: TagId[];
  createdAt: ISODateString;
  updatedAt: ISODateString;
}

/** Variant of the post that has not been published yet. */
export interface DraftPost extends PostBase {
  status: "draft" | "archived";
  authorId: AuthorId;
  publishedAt?: undefined;
}

/** Published posts must have a publish date. */
export interface PublishedPost extends PostBase {
  status: "published";
  authorId: AuthorId;
  publishedAt: ISODateString;
}

export type Post = DraftPost | PublishedPost;

// ---------- Hydrated view (for API responses / UI) ----------

/** Post with references resolved to full objects. */
export type PostWithRelations = Omit<Post, "authorId" | "tags"> & {
  author: Author;
  tags: Tag[];
};

// ---------- Input types ----------

export type CreatePostInput = Pick<PostBase, "title" | "body" | "excerpt"> & {
  authorId: AuthorId;
  tags?: TagId[];
};

export type UpdatePostInput = Partial<Omit<CreatePostInput, "authorId">>;
```

## Design decisions

- **Normalized references**: `Post` stores `authorId` and `tags: TagId[]` rather than embedding objects, avoiding duplication and stale data. `PostWithRelations` is the denormalized shape for display.
- **Structured body**: a discriminated union of blocks is safer and more portable than a raw HTML/Markdown string. If you prefer simplicity, replace it with `body: string` (Markdown).
- **Discriminated union on `status`**: guarantees `publishedAt` exists only when a post is published, so the compiler enforces it.
- **Branded IDs**: passing an `AuthorId` where a `PostId` is expected becomes a compile error.
- **Separate input types**: server-controlled fields (`id`, timestamps, `status`) can't be set by clients on creation.

