export type Brand<T, B extends string> = T & { readonly __brand: B };

export type PostId = Brand<string, "PostId">;
export type AuthorId = Brand<string, "AuthorId">;
export type TagId = Brand<string, "TagId">;

/** ISO 8601 timestamp, e.g. "2025-01-31T12:00:00Z" */
export type ISODateString = string;

// ---------- Author ----------

export interface Author {
  id: AuthorId;
  name: string;
  email: string;
  bio?: string;
  avatarUrl?: string;
}

/** Lightweight reference used when embedding an author in a post. */
export type AuthorSummary = Pick<Author, "id" | "name" | "avatarUrl">;

// ---------- Tag ----------

export interface Tag {
  id: TagId;
  /** Display name, e.g. "TypeScript" */
  name: string;
  /** URL-safe identifier, e.g. "typescript" */
  slug: string;
}

// ---------- Body ----------

/** Structured body, so content can be rendered on multiple platforms. */
export type BodyFormat = "markdown" | "html" | "plaintext";

export interface PostBody {
  format: BodyFormat;
  content: string;
}

// ---------- Post ----------

export type PostStatus = "draft" | "published" | "archived";

export interface BlogPost {
  id: PostId;
  /** URL-safe unique identifier, e.g. "my-first-post" */
  slug: string;
  title: string;
  authorId: AuthorId;
  tagIds: TagId[];
  body: PostBody;
  /** Short preview shown in listings */
  excerpt?: string;
  coverImageUrl?: string;
  status: PostStatus;
  createdAt: ISODateString;
  updatedAt: ISODateString;
  /** Only set once the post is published */
  publishedAt?: ISODateString;
}

// ---------- Hydrated view (for API responses / UI) ----------

export interface BlogPostWithRelations extends Omit<BlogPost, "authorId" | "tagIds"> {
  author: AuthorSummary;
  tags: Tag[];
}

// ---------- Input types ----------

export type CreateBlogPostInput = Pick<BlogPost, "title" | "authorId" | "body"> &
  Partial<Pick<BlogPost, "slug" | "excerpt" | "coverImageUrl" | "tagIds">>;

export type UpdateBlogPostInput = Partial<
  Omit<BlogPost, "id" | "authorId" | "createdAt" | "updatedAt">
>;
```

## Design notes

- **Normalized relations**: The post stores `authorId` and `tagIds` rather than embedding full objects. This avoids duplicated data and stale copies. `BlogPostWithRelations` is the denormalized shape for reads.
- **Branded IDs**: Prevent accidentally passing an `AuthorId` where a `PostId` is expected, at zero runtime cost.
- **Structured body**: `{ format, content }` makes it easy to switch from Markdown to another format later without a schema change.
- **Tags as entities**: Having `slug` and `id` supports tag pages, renaming, and deduplication. If you only need simple labels, `tags: string[]` is a reasonable simplification.
- **Status and timestamps**: `status` plus an optional `publishedAt` supports drafts and scheduling workflows.
- **Separate input types**: Server-managed fields (`id`, `createdAt`, `updatedAt`) are excluded from create and update payloads.

