Here's a set of TypeScript types for a product page. The long description with formatting is modeled as structured rich text (a block/inline tree) rather than raw HTML. This is safer to render, easier to validate, and works across web and native.

```ts
/* ---------- Primitives ---------- */

export type ID = string;
export type ISODateString = string; // e.g. "2025-01-31T12:00:00Z"
export type URLString = string;

/* ---------- Price ---------- */

export type CurrencyCode = "USD" | "EUR" | "GBP" | "JPY" | "CAD" | "AUD"; // extend as needed

export interface Money {
  /** Amount in the smallest currency unit (e.g. cents) to avoid float errors */
  amount: number;
  currency: CurrencyCode;
}

export interface Price {
  current: Money;
  /** Original price, shown struck-through when on sale */
  compareAt?: Money;
}

/* ---------- Images ---------- */

export interface ProductImage {
  id: ID;
  url: URLString;
  /** Required for accessibility; use "" only for purely decorative images */
  alt: string;
  width: number;
  height: number;
  /** Optional responsive variants */
  srcSet?: Array<{ url: URLString; width: number }>;
  /** Tiny placeholder for lazy loading */
  blurDataUrl?: string;
  isPrimary?: boolean;
}

/* ---------- Rich text description ---------- */

export type TextMark =
  | { type: "bold" }
  | { type: "italic" }
  | { type: "underline" }
  | { type: "strike" }
  | { type: "code" }
  | { type: "link"; href: URLString; openInNewTab?: boolean };

export interface TextNode {
  type: "text";
  text: string;
  marks?: TextMark[];
}

export interface LineBreakNode {
  type: "lineBreak";
}

export type InlineNode = TextNode | LineBreakNode;

export interface ParagraphBlock {
  type: "paragraph";
  children: InlineNode[];
}

export interface HeadingBlock {
  type: "heading";
  level: 2 | 3 | 4;
  children: InlineNode[];
}

export interface ListItemBlock {
  type: "listItem";
  children: Array<InlineNode | ParagraphBlock | ListBlock>;
}

export interface ListBlock {
  type: "list";
  ordered: boolean;
  items: ListItemBlock[];
}

export interface QuoteBlock {
  type: "quote";
  children: InlineNode[];
  citation?: string;
}

export interface ImageBlock {
  type: "image";
  image: ProductImage;
  caption?: string;
}

export interface DividerBlock {
  type: "divider";
}

export type DescriptionBlock =
  | ParagraphBlock
  | HeadingBlock
  | ListBlock
  | QuoteBlock
  | ImageBlock
  | DividerBlock;

export interface RichText {
  /** Schema version, useful for future migrations */
  version: 1;
  blocks: DescriptionBlock[];
}

/* ---------- Product ---------- */

export interface Product {
  id: ID;
  slug: string;
  name: string;
  price: Price;
  images: ProductImage[];
  description: RichText;

  /** Optional plain-text summary for SEO meta tags and listing cards */
  shortDescription?: string;

  createdAt: ISODateString;
  updatedAt: ISODateString;
}
```

