```typescript
/* ---------- Primitives ---------- */

export type ProductId = string;
export type ISODateString = string; // e.g. "2025-01-31T12:00:00Z"

export interface Money {
  /** Amount in the smallest currency unit (e.g. cents) to avoid float errors */
  amount: number;
  /** ISO 4217 currency code */
  currency: "USD" | "EUR" | "GBP" | (string & {});
}

/* ---------- Images ---------- */

export interface ProductImage {
  id: string;
  url: string;
  /** Required for accessibility */
  alt: string;
  width: number;
  height: number;
  /** Marks the primary/hero image */
  isPrimary?: boolean;
  /** Optional responsive variants */
  srcSet?: { url: string; width: number }[];
}

/* ---------- Rich text description ---------- */

export type TextMark =
  | { type: "bold" }
  | { type: "italic" }
  | { type: "underline" }
  | { type: "strike" }
  | { type: "code" }
  | { type: "link"; href: string; target?: "_blank" | "_self" };

export interface TextNode {
  type: "text";
  text: string;
  marks?: TextMark[];
}

export interface LineBreakNode {
  type: "lineBreak";
}

export type InlineNode = TextNode | LineBreakNode;

export interface ParagraphBlock {
  type: "paragraph";
  children: InlineNode[];
}

export interface HeadingBlock {
  type: "heading";
  level: 2 | 3 | 4;
  children: InlineNode[];
}

export interface ListItem {
  children: (InlineNode | ListBlock)[]; // allows nested lists
}

export interface ListBlock {
  type: "list";
  ordered: boolean;
  items: ListItem[];
}

export interface QuoteBlock {
  type: "quote";
  children: InlineNode[];
}

export interface ImageBlock {
  type: "image";
  image: ProductImage;
  caption?: string;
}

export interface DividerBlock {
  type: "divider";
}

export type DescriptionBlock =
  | ParagraphBlock
  | HeadingBlock
  | ListBlock
  | QuoteBlock
  | ImageBlock
  | DividerBlock;

export interface RichTextDescription {
  /** Schema version, useful for future migrations */
  version: 1;
  blocks: DescriptionBlock[];
}

/* ---------- Product ---------- */

export interface Product {
  id: ProductId;
  slug: string;
  name: string;
  price: Money;
  /** Original price, if currently discounted */
  compareAtPrice?: Money;
  images: ProductImage[];
  /** Short plain-text summary for cards and SEO */
  summary?: string;
  description: RichTextDescription;
  createdAt: ISODateString;
  updatedAt: ISODateString;
}

/* ---------- Page-level type ---------- */

export interface ProductPageProps {
  product: Product;
}
```

**Example usage:**

```typescript
const product: Product = {
  id: "p_123",
  slug: "trail-backpack",
  name: "Trail Backpack",
  price: { amount: 8999, currency: "USD" },
  images: [
    {
      id: "img_1",
      url: "/img/backpack.jpg",
      alt: "Green trail backpack, front view",
      width: 1200,
      height: 1200,
      isPrimary: true,
    },
  ],
  description: {
    version: 1,
    blocks: [
      { type: "heading", level: 2, children: [{ type: "text", text: "Built for the long haul" }] },
      {
        type: "paragraph",
        children: [
          { type: "text", text: "Made from " },
          { type: "text", text: "recycled nylon", marks: [{ type: "bold" }] },
          { type: "text", text: " with a waterproof coating." },
        ],
      },
    ],
  },
  createdAt: "2025-01-01T00:00:00Z",
  updatedAt: "2025-01-15T00:00:00Z",
};
```

**Design notes:**
- **Money in minor units** prevents floating-point rounding bugs.
- **Discriminated unions** (`type` field) let TypeScript narrow blocks in a `switch` when rendering.
- **Structured description** avoids `dangerouslySetInnerHTML` and XSS concerns. If you'd rather store HTML or Markdown, you could simplify to `description: string` plus `descriptionFormat: "html" | "markdown"`.

I can also add variants (size/color), inventory, reviews, or a renderer component for the description if useful.

