  /** Amount in the smallest currency unit (e.g., cents: 1999 = $19.99) to avoid floating-point issues */
  amount: number;
  /** ISO 4217 currency code (e.g., 'USD', 'EUR', 'GBP') */
  currency: string;
  /** Optional original price for displaying discounts */
  compareAtAmount?: number;
  /** Pre-formatted display string (e.g., "$19.99") */
  formatted?: string;
}

export interface ProductImage {
  id: string;
  url: string;
  alt: string;
  width?: number;
  height?: number;
  isPrimary?: boolean;
}

/**
 * Supports common ways formatted/rich text is stored and rendered.
 * Pick the variant that matches your CMS or backend.
 */
