  | {
      format: 'html' | 'markdown';
      content: string;
    }
  | {
      format: 'blocks';
      content: RichTextBlock[];
    };

export type RichTextBlock =
  | { type: 'paragraph'; children: RichTextSpan[] }
  | { type: 'heading'; level: 1 | 2 | 3 | 4; children: RichTextSpan[] }
  | { type: 'list'; style: 'ordered' | 'unordered'; items: RichTextSpan[][] };

export interface RichTextSpan {
  text: string;
  bold?: boolean;
  italic?: boolean;
  underline?: boolean;
  href?: string;
}
```

### Design Notes
* **`Price`**: Storing `amount` as an integer in minor units (cents) paired with a `currency` code is standard practice in e-commerce (like Stripe or Shopify) to prevent JavaScript floating-point rounding errors.
* **`ProductImage`**: Includes `alt` as a required field for accessibility, and optional `width`/`height` to help prevent Cumulative Layout Shift (CLS).
* **`FormattedDescription`**: Uses a discriminated union so it works whether your backend returns raw HTML/Markdown strings or structured rich-text blocks (like Sanity Portable Text or Contentful Rich Text). If you only use one format (e.g., HTML), you can simplify `description` to just `string`.

