```typescript
// Basic types
type AuthorId = string;
type TagId = string;

interface Author {
  id: AuthorId;
  name: string;
  email: string;
  bio?: string; // optional
}

interface Tag {
  id: TagId;
  name: string; // e.g. "typescript"
  slug: string; // e.g. "typescript" (URL-friendly)
}

type PostStatus = 'draft' | 'published' | 'archived';

interface BlogPost {
  id: string;
  title: string;
  slug: string; // URL-friendly version of title
  author: Author;
  tags: Tag[];
  body: string; // markdown or HTML content
  status: PostStatus;
  createdAt: Date;
