```ts
// ---- Primitives -------------------------------------------------------------

/** ISO 8601 UTC timestamp, e.g. "2025-01-15T09:30:00.000Z" */
export type IsoDateString = string;

/** URL-safe identifier, e.g. "hello-world" */
export type Slug = string;

/**
 * A tag. Kept as an alias so you can tighten it later to a closed union
 * (e.g. `"typescript" | "design"`) without touching every call site.
 */
export type Tag = string;

// ---- Author -----------------------------------------------------------------

export interface Author {
  id: string;
  name: string;
  slug: Slug;
  bio?: string;
  avatarUrl?: string;
}

// ---- Post -------------------------------------------------------------------

interface PostBase {
  id: string;
  slug: Slug;
  title: string;
  /** Reference, not a copy — see PostWithAuthor below. */
  authorId: Author["id"];
  tags: readonly Tag[];
  body: string;
  createdAt: IsoDateString;
  updatedAt: IsoDateString;
}

export interface DraftPost extends PostBase {
  status: "draft";
  publishedAt?: never;
}

export interface PublishedPost extends PostBase {
  status: "published";
  publishedAt: IsoDateString;
}

export interface ArchivedPost extends PostBase {
  status: "archived";
  publishedAt: IsoDateString;
  archivedAt: IsoDateString;
}

export type Post = DraftPost | PublishedPost | ArchivedPost;

// ---- Views & inputs ---------------------------------------------------------

/** A post with its author resolved, for rendering. */
export type PostWithAuthor = Post & { author: Author };

/** What a client sends to create a post; the server fills in the rest. */
export interface CreatePostInput {
  title: string;
  authorId: Author["id"];
  tags: Tag[];
  body: string;
  /** Derived from the title when omitted. */
  slug?: Slug;
}

export type UpdatePostInput = Partial<
  Pick<CreatePostInput, "title" | "tags" | "body">
>;
```

**Why these choices**

- **`status` as a discriminated union, not a boolean `isPublished`.** `publishedAt` only exists on published/archived posts, so the compiler enforces that you check `status` before reading it. `publishedAt?: never` makes the draft branch explicit rather than accidental.
- **`authorId`, not an embedded `Author`.** Author data is one entity with one source of truth; embedding it in every post means every bio edit rewrites every post. `PostWithAuthor` is the denormalized read model for rendering.
- **ISO strings, not `Date`.** `Date` doesn't survive `JSON.stringify` round-trips. Use `Date` only if this model never crosses a serialization boundary.
- **`readonly` on arrays.** Prevents accidental `post.tags.push(...)` mutations that bypass whatever persistence layer you're using.
- **`Tag` as an alias.** Start permissive; if your taxonomy becomes closed, swap the alias for a union and every consumer gets exhaustiveness checking for free.

**Where to extend**

If posts need rich content rather than raw markdown, widen `body` into a discriminated union — `{ type: "markdown"; markdown: string } | { type: "blocks"; blocks: Block[] }` — so renderers stay exhaustive and you can migrate formats per-post.

