export interface BlogPost {
  id: string;
  title: string;
  author: Author;
  tags: Tag[];
  body: string; // Markdown, HTML, or plain text
  createdAt: Date;
  updatedAt?: Date;
}
```

If tags need their own metadata, model them as objects instead:

```ts
