  slug: string;
  author: Author;
  tags: Tag[];
  excerpt?: string;
  status: PostStatus;
  publishedAt?: Date;
  updatedAt: Date;
}

// Optional: input types for create/update flows
export type CreateBlogPostInput = Omit<
  BlogPost,
  "id" | "createdAt" | "updatedAt" | "publishedAt"
> & {
  status?: PostStatus;
};

export type UpdateBlogPostInput = Partial<
  Omit<BlogPost, "id" | "createdAt" | "updatedAt">
>;
```

If your storage is normalized, you can store `authorId: UserId` instead of `author: Author`, and `tagIds: TagId[]` instead of `tags: Tag[]`, then hydrate them in API responses. For JSON APIs, you may also use ISO date strings (`string`) instead of `Date`.

```ts
/** ISO 8601 UTC timestamp, e.g. "2025-01-15T09:30:00.000Z" */
type IsoDateString = string;

/** Branded IDs prevent accidentally passing an AuthorId where a PostId is expected. */
type PostId = string & { readonly __brand: 'PostId' };
type AuthorId = string & { readonly __brand: 'AuthorId' };

/** Normalized, lowercase, kebab-case: "type-script", "web-dev" */
type Tag = string;

interface Author {
  id: AuthorId;
  name: string;
  avatarUrl?: string;
  bio?: string;
}

interface PostBase {
  id: PostId;
  /** URL-safe identifier, unique across the blog: "designing-a-data-model" */
  slug: string;
  title: string;
  authorId: AuthorId;
  tags: Tag[];
  /** Markdown source. Render to HTML at read time. */
  body: string;
  createdAt: IsoDateString;
  updatedAt: IsoDateString;
}

interface DraftPost extends PostBase {
  status: 'draft';
  publishedAt: null;
}

interface PublishedPost extends PostBase {
  status: 'published';
  publishedAt: IsoDateString;
}

interface ArchivedPost extends PostBase {
  status: 'archived';
  /** Archived posts were published at some point, so this is always set. */
  publishedAt: IsoDateString;
}

type Post = DraftPost | PublishedPost | ArchivedPost;

/** Post with the author record joined in — what the read API returns. */
type HydratedPost = Post & { author: Author };

/** What the client sends when creating a post. */
interface CreatePostInput {
  title: string;
  body: string;
  tags: Tag[];
  authorId: AuthorId;
}

/** All fields optional; `status` transitions are handled by the server. */
type UpdatePostInput = Partial<Omit<CreatePostInput, 'authorId'>>;
```

Design notes:

- **`authorId` instead of an embedded `Author`.** Authors are reused across posts and change independently (avatar, bio). Store the reference; join on read. If your read path is a static site build, denormalizing the author into the post document is a reasonable tradeoff — swap `authorId` for `author: Author`.
- **Discriminated union on `status`.** This is the main value here: it makes `publishedAt` non-nullable exactly when a post is published, so you never write `post.publishedAt!`. TypeScript narrows on `post.status` and the compiler enforces the invariant.
- **`body` as a Markdown string.** Simplest thing that works, and it keeps the model serialization-agnostic. If you need embeds, pull quotes, or per-block editing, replace it with `body: Block[]` where `Block` is its own union (`Paragraph | Heading | Image | Code`).
- **`Tag` as a bare string.** Fine when tags are just labels. Promote to `{ id, slug, label, color }` once tags get their own pages or metadata.
- **ISO strings over `Date`.** The type survives `JSON.stringify`/`parse` unchanged. Convert to `Date` at the edges if you need date math.
- **Branded IDs are optional.** They cost a cast at construction sites (`'abc' as PostId`) and buy you real safety in function signatures. Drop them if the friction isn't worth it.

Here’s a clean, extensible TypeScript model for a blog post:

```ts
export type PostStatus = "draft" | "published" | "archived";
export type BodyFormat = "markdown" | "html" | "plaintext";

export interface Author {
  id: string;
  name: string;
  email?: string;
  avatarUrl?: string;
  bio?: string;
}

export interface Tag {
  id: string;
  name: string;
  slug: string;
}

export interface BlogPost {
  id: string;
  slug: string;
  title: string;
  author: Author;
  tags: Tag[];
  body: string;
  bodyFormat: BodyFormat;
  excerpt?: string;
  status: PostStatus;
  publishedAt?: Date;
  createdAt: Date;
  updatedAt: Date;
}
```

If your app only needs the exact fields you mentioned, a simpler version works too:

```ts
export interface SimpleBlogPost {
  title: string;
  author: string;
  tags: string[];
  body: string;
}
```

A few design notes:

- `author` can be a full `Author` object if you need profile data, or just `string` if it’s only a display name.
- `tags` can be `Tag[]` for normalized data, or `string[]` for simple labels.
- `bodyFormat` is useful if `body` may contain Markdown, HTML, or plain text.
- If this is coming from an API as JSON, you may want to type dates as `string` ISO timestamps instead of `Date`.

Here’s a clean TypeScript data model for a blog post. I’ll show a minimal version first, then a more production-ready version.

### Minimal

```ts
export type Author = {
  id: string;
  name: string;
};

export type BlogPost = {
  title: string;
  author: Author;
  tags: string[];
  body: string;
};
```

### Recommended / production-ready

```ts
export type Author = {
  id: string;
  name: string;
  avatarUrl?: string;
  bio?: string;
};

export type Tag = {
  id: string;
  name: string;
  slug: string;
};

export type PostStatus = "draft" | "published" | "archived";

export type BlogPost = {
  id: string;
  slug: string;
  title: string;
  author: Author;

  // If your database stores a relation instead of embedding the author:
  // authorId: Author["id"];

  tags: Tag[];
  body: string; // e.g. Markdown, HTML, or plain text

  status: PostStatus;
  createdAt: Date;
  updatedAt: Date;
  publishedAt?: Date;
};
```

If you want `body` to support structured content instead of a raw string:

```ts
export type BlogBody =
  | { type: "paragraph"; text: string }
  | { type: "heading"; level: 1 | 2 | 3; text: string }
  | { type: "image"; src: string; alt: string; caption?: string }
  | { type: "code"; language: string; code: string };

export type BlogPost = {
  id: string;
  title: string;
  author: Author;
  tags: Tag[];
  body: BlogBody[];
};
```

For a simple blog, `body: string` with Markdown is usually the easiest. For a CMS-style editor, the structured `BlogBody[]` approach is more flexible.

Minimal version:

```ts
export interface Author {
  id: string;
  name: string;
  email?: string;
  avatarUrl?: string;
}

export interface BlogPost {
  title: string;
  author: Author;
  tags: string[];
  body: string;
}
```

A more production-ready version might include IDs, timestamps, and a slug:

```ts
export interface Author {
  id: string;
  name: string;
  email?: string;
  avatarUrl?: string;
}

export interface BlogPost {
  id: string;
  slug: string;
  title: string;
  author: Author;
  tags: string[];
  body: string;

  excerpt?: string;
  coverImageUrl?: string;

  status: "draft" | "published" | "archived";

  createdAt: string; // ISO 8601
  updatedAt: string; // ISO 8601
  publishedAt?: string; // ISO 8601
}
```

If `author` is just a display name, you can simplify it to:

```ts
export interface BlogPost {
  title: string;
  author: string;
  tags: string[];
  body: string;
}
```

If the body can be structured content instead of Markdown/HTML, model it as a discriminated union:

```ts
export type BlogPostBody =
  | { format: "markdown"; content: string }
  | { format: "html"; content: string }
  | { format: "plaintext"; content: string };

export interface BlogPost {
  title: string;
  author: Author;
  tags: string[];
  body: BlogPostBody;
}
```

For most blogs, the recommended shape is:

```ts
export interface BlogPost {
  id: string;
  slug: string;
  title: string;
  author: Author;
  tags: string[];
  body: string; // Markdown or HTML
  createdAt: string;
  updatedAt: string;
  publishedAt?: string;
}
```

