  | { type: "italic"; children: InlineNode[] }
  | { type: "code"; value: string }
  | { type: "link"; href: string; children: InlineNode[] };

export type BlockNode =
  | { type: "paragraph"; children: InlineNode[] }
  | { type: "heading"; level: 2 | 3 | 4; children: InlineNode[] }
  | { type: "list"; ordered: boolean; items: InlineNode[][] }
  | { type: "quote"; children: InlineNode[] }
  | { type: "codeBlock"; language?: string; value: string }
  | { type: "image"; image: ProductImage }
  | { type: "divider" };

export interface RichText {
  /** Plain-text fallback for SEO, search, and accessibility. */
  plainText: string;
  blocks: BlockNode[];
}

// ---------- Product ----------

export interface Product {
  id: string;
  slug: string;
  name: string;
  /** Short tagline shown under the name. */
  tagline?: string;
  price: Money;
  /** Optional original price for showing a discount. */
  compareAtPrice?: Money;
  images: ProductImage[];
  description: RichText;
  /** ISO 8601 timestamp. */
  createdAt: string;
  updatedAt: string;
}
```

## Why this shape?

**`Money` as `{ amount, currency }`** — storing cents as an integer avoids floating-point rounding bugs (`0.1 + 0.2 !== 0.3`), and keeping the currency alongside the amount prevents the classic "which currency is this?" bug when you localize.

**Discriminated union for blocks** — each block has a literal `type` field, so TypeScript narrows exhaustively:

```ts
function renderBlock(block: BlockNode) {
  switch (block.type) {
    case "paragraph":
      return <p>{renderInline(block.children)}</p>;
    case "heading":
      return React.createElement(`h${block.level}`, null, renderInline(block.children));
    case "list":
      return block.ordered
        ? <ol>{block.items.map(renderItem)}</ol>
        : <ul>{block.items.map(renderItem)}</ul>;
    case "image":
      return <img src={block.image.url} alt={block.image.alt} />;
    // ...
  }
}
```

If you add a new block type later, the compiler flags every `switch` that needs updating.

**`plainText` alongside `blocks`** — you almost always need a plain-text version for `<meta description>`, search indexing, and screen readers. Deriving it at render time is wasteful; storing it once is cheap.

## Alternative: if you're rendering Markdown

If your CMS already emits Markdown and you trust the source, you can simplify:

```ts
export interface Product {
  // ...
  description: {
    markdown: string;
    plainText: string;
  };
}
```

But you lose the ability to render the same content natively on mobile or in emails without a Markdown parser, and you can't easily attach structured data (like image dimensions) to embedded media. The block-based approach is worth the extra ceremony for anything beyond a simple blog post.

```ts
// ---------- Money ----------

export type CurrencyCode = 'USD' | 'EUR' | 'GBP' | 'JPY';

export interface Money {
  /** Amount in the smallest currency unit (e.g. cents). Never a float. */
  amount: number;
  currency: CurrencyCode;
}

// ---------- Images ----------

export interface ImageAsset {
  url: string;
  width: number;
  height: number;
  /** Required for a11y. Use "" only for purely decorative images. */
  alt: string;
  /** Tiny base64 preview for next/image placeholders. */
  blurDataUrl?: string;
}

export interface ProductImage extends ImageAsset {
  id: string;
  /** Set when the image belongs to a specific variant/colorway. */
  variantId?: string;
}

// ---------- Rich text ----------

export type TextMark = 'bold' | 'italic' | 'underline' | 'strikethrough' | 'code';

export interface TextSpan {
  type: 'span';
  text: string;
  marks?: TextMark[];
}

export interface LinkSpan {
  type: 'link';
  href: string;
  text: string;
  external?: boolean;
}

export type InlineNode = TextSpan | LinkSpan;

export interface ParagraphBlock {
  type: 'paragraph';
  children: InlineNode[];
}

export interface HeadingBlock {
  type: 'heading';
  level: 2 | 3 | 4;
  children: InlineNode[];
}

export interface ListBlock {
  type: 'list';
  style: 'bullet' | 'number';
  items: InlineNode[][];
}

export interface ImageBlock {
  type: 'image';
  image: ImageAsset;
  caption?: string;
}

export interface QuoteBlock {
  type: 'quote';
  children: InlineNode[];
  attribution?: string;
}

export type RichTextBlock =
  | ParagraphBlock
  | HeadingBlock
  | ListBlock
  | ImageBlock
  | QuoteBlock;

export type RichText = RichTextBlock[];

// ---------- Product ----------

export type Availability = 'in_stock' | 'low_stock' | 'out_of_stock' | 'preorder';

export interface Product {
  id: string;
  slug: string;
  name: string;
  /** Short marketing line rendered under the name. */
  tagline?: string;

  price: Money;
  /** Set only when the item is discounted; must be > price. */
  compareAtPrice?: Money;

  images: ProductImage[];
  /** The long-form description, stored as structured blocks. */
  description: RichText;

  availability: Availability;
  /** ISO 8601. */
  updatedAt: string;
}

// ---------- Page-level wrapper ----------

export interface Breadcrumb {
  label: string;
  href: string;
}

export interface ProductPage {
  product: Product;
  breadcrumbs: Breadcrumb[];
  /** Pre-rendered "you might also like" cards. */
  related?: Array<Pick<Product, 'id' | 'slug' | 'name' | 'price' | 'images'>>;
}
```

A few decisions worth calling out:

- **`Money.amount` is an integer in minor units.** `19.99` as a float will eventually bite you in a cart total. Format at the edge with `Intl.NumberFormat`.
- **`description` is a discriminated union, not an HTML string.** You get exhaustive `switch` handling in the renderer, no `dangerouslySetInnerHTML`, and the editor can't emit markup you don't support. If your CMS only gives you HTML, keep the same shape but swap `RichText` for `{ html: string }` so the boundary is explicit.
- **`alt` is required on `ImageAsset`.** Making it optional means it gets forgotten; making it required with an explicit `""` escape hatch forces a decision.
- **`compareAtPrice` is optional rather than a `discount` field.** The UI derives the badge, so there's one source of truth for the numbers.

# Product Page Types

Here's a set of TypeScript types for a product page. I've modeled the long description as **structured rich-text blocks** (rather than raw HTML/Markdown) so it's type-safe, renderable, and safe from XSS.

```ts
