  | QuoteBlock
  | DividerBlock;

/** A rich-text document is just an ordered list of blocks. */
export type RichText = RichTextBlock[];

// ---------- Product ----------

export interface ProductVariant {
  id: string;
  /** e.g. "Large / Blue". */
  name: string;
  sku: string;
  price: Money;
  /** Optional compare-at price for showing a strikethrough. */
  compareAtPrice?: Money;
  inStock: boolean;
}

export interface Product {
