    { id: "img_2", url: "/tee-back.jpg", alt: "Back view" },
  ],
  description: {
    plainText: "Soft, breathable cotton. Pre-shrunk. Machine washable.",
    blocks: [
      { type: "paragraph", children: [
        { type: "text", text: "Soft, breathable " },
        { type: "text", text: "100% cotton", bold: true },
        { type: "text", text: "." },
      ]},
      { type: "list", ordered: false, items: [
        [{ type: "text", text: "Pre-shrunk" }],
        [{ type: "text", text: "Machine washable" }],
      ]},
    ],
  },
  inStock: true,
