```

If you'd rather keep the description as **Markdown** or **sanitized HTML** instead of structured blocks, I can swap `RichDescription` for a simpler `{ format: "markdown" | "html"; content: string }` — just say the word.

# Product Page Types

Here's a type-safe design. The key decision is how to model the **formatted description** — I'd recommend structured blocks over raw HTML/Markdown strings, since it's renderer-agnostic, safe (no `dangerouslySetInnerHTML`), and lets you control which formatting is allowed.

```ts
// ---------- Primitives ----------

export type CurrencyCode = "USD" | "EUR" | "GBP" | "JPY";

export interface Money {
  amount: number;      // minor units (cents) — avoids float issues
  currency: CurrencyCode;
}

export interface ImageAsset {
  url: string;
  alt: string;         // required for a11y
  width: number;
  height: number;      // enables aspect-ratio / CLS prevention
  blurHash?: string;   // for progressive loading
}

export interface ProductImage extends ImageAsset {
  id: string;
  isPrimary: boolean;
}
```

### The formatted description

A discriminated union of blocks and spans. This is the same shape Sanity Portable Text uses, and it's easy to render.

```ts
// ---------- Inline formatting ----------

export type TextSpan = {
  type: "text";
  text: string;
  marks?: Array<"bold" | "italic" | "underline" | "code" | "strikethrough">;
};

export type LinkSpan = {
  type: "link";
  href: string;
  text: string;
};

export type InlineNode = TextSpan | LinkSpan;

// ---------- Block-level formatting ----------

export interface ParagraphBlock {
  type: "paragraph";
  children: InlineNode[];
}

export interface HeadingBlock {
  type: "heading";
  level: 2 | 3 | 4;    // h1 is reserved for the product name
  children: InlineNode[];
}

export interface ListBlock {
  type: "list";
  style: "bullet" | "number";
  items: InlineNode[][];
}

export interface ImageBlock {
  type: "image";
  asset: ImageAsset;
  caption?: string;
}

export interface QuoteBlock {
  type: "quote";
  children: InlineNode[];
  attribution?: string;
}

export interface SpecTableBlock {
  type: "specTable";
  rows: Array<{ label: string; value: string }>;
}

export type DescriptionBlock =
  | ParagraphBlock
  | HeadingBlock
  | ListBlock
  | ImageBlock
  | QuoteBlock
  | SpecTableBlock;
```

### The product itself

```ts
// ---------- Product ----------

export type ProductAvailability =
  | { status: "in_stock" }
  | { status: "low_stock"; remaining: number }
  | { status: "out_of_stock"; restockDate?: string }  // ISO 8601
  | { status: "preorder"; releaseDate: string };

export interface ProductVariant {
  id: string;
  sku: string;
  label: string;          // e.g. "Large / Navy"
  price: Money;
  compareAtPrice?: Money; // for showing strikethrough original price
  availability: ProductAvailability;
  imageId?: ProductImage["id"];
}

export interface Product {
  id: string;
  slug: string;
  name: string;
  brand?: string;

  price: Money;
  compareAtPrice?: Money;

  images: ProductImage[];   // at least one should have isPrimary: true
  description: DescriptionBlock[];

  availability: ProductAvailability;
  variants?: ProductVariant[];

  tags?: string[];
  rating?: { average: number; count: number };
}
```

### Rendering example

```tsx
function renderInline(nodes: InlineNode[]): React.ReactNode {
  return nodes.map((node, i) =>
    node.type === "link" ? (
      <a key={i} href={node.href}>{node.text}</a>
    ) : (
      <span key={i} className={node.marks?.join(" ")}>{node.text}</span>
    )
  );
}

function renderBlock(block: DescriptionBlock, i: number): React.ReactNode {
  switch (block.type) {
    case "paragraph": return <p key={i}>{renderInline(block.children)}</p>;
    case "heading":   return React.createElement(`h${block.level}`, { key: i }, renderInline(block.children));
    case "list":      return block.style === "bullet"
                        ? <ul key={i}>{block.items.map((it, j) => <li key={j}>{renderInline(it)}</li>)}</ul>
                        : <ol key={i}>{block.items.map((it, j) => <li key={j}>{renderInline(it)}</li>)}</ol>;
    case "image":     return <figure key={i}><img src={block.asset.url} alt={block.asset.alt} />{block.caption && <figcaption>{block.caption}</figcaption>}</figure>;
    case "quote":     return <blockquote key={i}>{renderInline(block.children)}</blockquote>;
    case "specTable": return <table key={i}>{/* ... */}</table>;
  }
}
```

### Why this shape

- **`Money` in minor units** — `19.99` as a float breaks arithmetic. Storing `1999` + currency keeps it exact.
- **Discriminated union for blocks** — the `switch` is exhaustive; adding a new block type is a compile error until you handle it.
- **`alt` required on images** — forces accessibility at the type level.
- **`width`/`height` on assets** — lets you reserve layout space and avoid CLS.
- **`availability` as a union** — `low_stock` carries `remaining`; you can't accidentally read it when out of stock.
- **`h1` excluded from `HeadingBlock`** — the product name is the page's `h1`; description headings start at `h2`.

If you'd rather not hand-roll this, the same shape is what [Portable Text](https://portabletext.org/) and [Contentful Rich Text](https://www.contentful.com/developers/docs/concepts/rich-text/) produce — you can swap `DescriptionBlock` for their types and keep the rest.

# TypeScript types for a product page

Below is a type-safe design. The two decisions worth calling out up front:

- **Price** is stored as an integer in minor units (cents) plus a currency code — never as a float, and never as a pre-formatted string.
- **Description** is modeled as a structured rich-text AST rather than an HTML string. That keeps rendering under your control (no `dangerouslySetInnerHTML`) while still supporting headings, bold/italic, links, lists, quotes, code, and inline images.

```ts
// ---------------------------------------------------------------------------
// Shared primitives
// ---------------------------------------------------------------------------

/** ISO 4217 code, e.g. "USD", "EUR", "JPY". */
type CurrencyCode = string;

/** Monetary value in minor units (e.g. 1999 === $19.99). */
interface Money {
  amount: number;
  currency: CurrencyCode;
}

// ---------------------------------------------------------------------------
// Images
// ---------------------------------------------------------------------------

interface ImageAsset {
  id: string;
  url: string;
  /** Required — empty alt text is a conscious a11y decision, not a default. */
  alt: string;
  width: number;
  height: number;
  /** Optional placeholder (e.g. BlurHash / base64 LQIP). */
  blurhash?: string;
}

interface ProductImage extends ImageAsset {
  /** Small variant for grids and thumbnails. */
  thumbnailUrl?: string;
  /** Marks the hero image in a gallery. */
  isPrimary?: boolean;
}

// ---------------------------------------------------------------------------
// Rich text description
// ---------------------------------------------------------------------------

type RichTextMark =
  | 'bold'
  | 'italic'
  | 'underline'
  | 'strikethrough'
  | 'code'
  | 'link';

interface RichTextSpan {
  text: string;
  marks?: RichTextMark[];
  /** Required when `marks` contains `'link'`. */
  href?: string;
}

type ListStyle = 'bullet' | 'numbered';

type RichTextBlock =
  | { type: 'heading'; level: 2 | 3 | 4; spans: RichTextSpan[] }
  | { type: 'paragraph'; spans: RichTextSpan[] }
  | { type: 'list'; style: ListStyle; items: RichTextSpan[][] }
  | { type: 'quote'; spans: RichTextSpan[] }
  | { type: 'code'; code: string; language?: string }
  | { type: 'image'; image: ImageAsset; caption?: string }
  | { type: 'divider' };

interface RichTextDocument {
  blocks: RichTextBlock[];
  /** Plain-text fallback for SEO, search, and previews. */
  plainText?: string;
}

// ---------------------------------------------------------------------------
// Product page
// ---------------------------------------------------------------------------

interface ProductPage {
  id: string;
  slug: string;
  name: string;
  /** Short marketing line shown under the name. */
  tagline?: string;

  price: Money;
  /** Original price when the item is discounted. */
  compareAtPrice?: Money;

  /** Ordered gallery; the first image is typically the hero. */
  images: ProductImage[];

  description: RichTextDocument;

  brand?: string;
  sku?: string;
  inStock?: boolean;
  rating?: { average: number; count: number };
  /** ISO 8601 timestamp. */
  updatedAt?: string;
}
```

