}

// ---------- Rich text description ----------

export type RichTextMark =
  | "bold"
  | "italic"
  | "underline"
  | "strikethrough"
  | "code"
  | { type: "link"; href: string }
  | { type: "color"; value: string };

export interface RichTextSpan {
  text: string;
  marks?: RichTextMark[];
}

export type RichTextNode =
  | { type: "paragraph"; children: RichTextSpan[] }
  | { type: "heading"; level: 2 | 3 | 4; children: RichTextSpan[] }
  | { type: "list"; ordered: boolean; items: RichTextSpan[][] }
  | { type: "quote"; children: RichTextSpan[] }
  | { type: "image"; image: ProductImage }
  | { type: "divider" }
  | { type: "code-block"; language?: string; code: string };

export interface RichTextDocument {
  /** Schema version for forward-compatible migrations. */
  version: 1;
  blocks: RichTextNode[];
}

// ---------- Product ----------

export interface ProductVariant {
  id: string;
  /** Human-readable label, e.g. "Large / Blue". */
  label: string;
  price: Money;
  /** Optional compare-at price for showing discounts. */
