  inStock: boolean;
  image?: ProductImage;
}

export interface Product {
  id: string;
  /** URL-safe identifier, e.g. "linen-shirt". */
  slug: string;
  name: string;
  /** Short marketing tagline shown near the title. */
  tagline?: string;
  price: Money;
  compareAtPrice?: Money;
  images: ProductImage[];
  /** At least one image is expected; the first is the primary. */
  description: RichTextDocument;
  variants?: ProductVariant[];
  tags?: string[];
  inStock: boolean;
  /** ISO 8601 timestamp. */
  updatedAt: string;
}

// ---------- Page wrapper ----------

