### Runtime validation pairing (e.g., with Zod)

```ts
import { z } from "zod";

export const BlogPostSchema = z.object({
  id: z.string(),
  title: z.string().min(1),
  author: z.object({
    id: z.string(),
    name: z.string().min(1),
  }),
  tags: z.array(z.object({
    id: z.string(),
    slug: z.string(),
