## Design Notes

| Field | Recommendation |
|---|---|
| `title` | `string`; consider a `NonEmptyString` brand if validation matters |
| `author` | Object if authors have profiles or are shared; `string` if it's just a display name |
| `tags` | `string[]` for simplicity; `Tag[]` if you need tag metadata (descriptions, counts, URLs) |
| `body` | `string` (Markdown/HTML) for most cases; a block union for structured editors |
| Dates | ISO 8601 strings (`string`) rather than `Date` for JSON-safe transport |
| IDs | `string` (UUID or prefixed like `post_001`) — avoids `number` precision issues in JS |

**Rule of thumb:** start with Option 1 and refactor to Option 2 when the domain demands it (multiple authors, tag pages, drafts, or post metadata).

```ts
// A tag attached to a post
export interface Tag {
  id: string;
  name: string;
  slug: string;
}

// An author of a post
export interface Author {
  id: string;
  name: string;
  email?: string;
  bio?: string;
  avatarUrl?: string;
}

// The blog post itself
export interface BlogPost {
  id: string;
  title: string;
  author: Author;
  tags: Tag[];
  body: string;
  publishedAt?: string; // ISO 8601 date; undefined for drafts
  createdAt: string;
  updatedAt: string;
}
```

**Notes:**

- `author` and `tags` are nested objects/arrays rather than plain IDs, so a post can be rendered without extra lookups. If you store posts separately from authors/tags, use `authorId: string` and `tagIds: string[]` instead.
- `body` is plain text/Markdown. If you need rich content, model it as a structured document (e.g., a block or AST type) instead of a string.
- `publishedAt` is optional to distinguish drafts from published posts.

Example usage:

```ts
const post: BlogPost = {
  id: "post_1",
  title: "Designing TypeScript Data Models",
  author: {
    id: "author_1",
    name: "Ada Lovelace",
  },
  tags: [
    { id: "tag_1", name: "TypeScript", slug: "typescript" },
    { id: "tag_2", name: "Web Dev", slug: "web-dev" },
  ],
  body: "# Designing TypeScript Data Models\n\n...",
  createdAt: "2024-01-15T09:00:00Z",
  updatedAt: "2024-01-15T09:00:00Z",
};
```

# Blog Post Data Model (TypeScript)

## 1. Core design decisions

Before the types, the choices that drive them:

| Concern | Decision | Why |
|---|---|---|
| Author | **Reference by ID** (`authorId`), with an optional denormalized snapshot | Keeps posts small; author name changes shouldn't rewrite every post. Snapshot fields let you render a post without a join (e.g. in an RSS feed). |
| Tags | **Normalized entities** referenced by ID, plus a `tags: string[]` convenience field | Tags need their own pages, counts, and slugs. Storing slugs inline is a pragmatic denormalization for querying. |
| Body | **Discriminated union**: `markdown` \| `blocks` | Markdown is the authoring format; blocks are the render format. Modeling both explicitly avoids a `body: any`. |
| Status | **Discriminated union** on `status` | `published` posts have `publishedAt`; `draft` posts don't. The type system enforces this. |
| Dates | ISO 8601 **strings**, not `Date` | `Date` doesn't survive JSON round-trips; strings are unambiguous and sortable. |

---

## 2. The types

```ts
// ─────────────────────────────────────────────────────────────
// Primitives
// ─────────────────────────────────────────────────────────────

/** ISO 8601 timestamp, e.g. "2024-03-11T09:30:00.000Z" */
export type ISODateString = string;

/** URL-safe identifier (nanoid, cuid, uuid — your choice) */
export type ID = string;

/** Lowercase, hyphenated slug: "typescript-best-practices" */
export type Slug = string;

// ─────────────────────────────────────────────────────────────
// Author
// ─────────────────────────────────────────────────────────────

export interface Author {
  id: ID;
  /** Display name, e.g. "Ada Lovelace" */
  name: string;
  /** URL-safe handle, e.g. "ada" — unique, used in /authors/ada */
  handle: Slug;
  /** Optional short bio, plain text or markdown */
  bio?: string;
  avatarUrl?: string;
  /** Links shown on the author page */
  links?: {
    website?: string;
    twitter?: string;
    github?: string;
    mastodon?: string;
  };
  createdAt: ISODateString;
  updatedAt: ISODateString;
}

// ─────────────────────────────────────────────────────────────
// Tag
// ─────────────────────────────────────────────────────────────

export interface Tag {
  id: ID;
  /** Canonical lowercase name, e.g. "TypeScript" */
  name: string;
  /** URL-safe form, e.g. "typescript" */
  slug: Slug;
  description?: string;
  /** Number of published posts carrying this tag (denormalized counter) */
  postCount?: number;
}

// ─────────────────────────────────────────────────────────────
// Body
// ─────────────────────────────────────────────────────────────

/** A single structured content block (for block-based editors) */
export type ContentBlock =
  | { type: 'paragraph'; text: string }
  | { type: 'heading'; level: 2 | 3 | 4; text: string }
  | { type: 'code'; language: string; code: string; filename?: string }
  | { type: 'quote'; text: string; attribution?: string }
  | { type: 'image'; url: string; alt: string; caption?: string }
  | { type: 'list'; ordered: boolean; items: string[] }
  | { type: 'callout'; tone: 'info' | 'warning' | 'tip'; title?: string; text: string }
  | { type: 'embed'; provider: 'youtube' | 'twitter' | 'codepen'; url: string };

export type PostBody =
  | { format: 'markdown'; content: string }
  | { format: 'blocks'; content: ContentBlock[] };

// ─────────────────────────────────────────────────────────────
// Post
// ─────────────────────────────────────────────────────────────

/** Fields shared by every post regardless of status */
interface PostBase {
  id: ID;
  title: string;
  /** URL segment: /blog/hello-world */
  slug: Slug;
  /** Reference to the author */
  authorId: ID;
  /** Denormalized snapshot so a post renders without a join */
  author?: Pick<Author, 'id' | 'name' | 'handle' | 'avatarUrl'>;
  /** Tag slugs — denormalized for fast filtering */
  tags: Slug[];
  body: PostBody;
  /** Short summary for listings, SEO, and social cards */
  excerpt?: string;
  coverImage?: { url: string; alt: string; width?: number; height?: number };
  /** SEO overrides */
  seo?: {
    title?: string;
    description?: string;
    canonicalUrl?: string;
    noIndex?: boolean;
  };
  createdAt: ISODateString;
  updatedAt: ISODateString;
}

export interface DraftPost extends PostBase {
  status: 'draft';
  /** Drafts have no publication date */
  publishedAt?: never;
}

export interface PublishedPost extends PostBase {
  status: 'published';
  publishedAt: ISODateString;
  /** Optional scheduled publication (still `status: 'published'` once live) */
  scheduledFor?: ISODateString;
}

export interface ArchivedPost extends PostBase {
  status: 'archived';
  publishedAt: ISODateString;
  archivedAt: ISODateString;
}

export type Post = DraftPost | PublishedPost | ArchivedPost;

// ─────────────────────────────────────────────────────────────
// Collections & queries
// ─────────────────────────────────────────────────────────────

/** A post without its body — for index pages, feeds, search results */
export type PostSummary = Omit<Post, 'body'> & {
  /** Reading time in minutes, precomputed */
  readingTimeMinutes?: number;
};

export interface Paginated<T> {
  items: T[];
  total: number;
  page: number;
  pageSize: number;
}

export interface PostQuery {
  authorId?: ID;
  tags?: Slug[];
  status?: Post['status'];
  /** Free-text search over title/excerpt/body */
  search?: string;
  sort?: 'newest' | 'oldest' | 'updated' | 'popular';
  page?: number;
  pageSize?: number;
}
```

---

## 3. Runtime validation

TypeScript types vanish at runtime. If data comes from an API, a webhook, or a CMS, validate at the boundary with Zod (or Valibot / TypeBox):

```ts
import { z } from 'zod';

const isoDate = z.string().datetime({ offset: true });

const slug = z.string().regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/);

const contentBlock = z.discriminatedUnion('type', [
  z.object({ type: z.literal('paragraph'), text: z.string() }),
  z.object({ type: z.literal('heading'), level: z.union([z.literal(2), z.literal(3), z.literal(4)]), text: z.string() }),
  z.object({ type: z.literal('code'), language: z.string(), code: z.string(), filename: z.string().optional() }),
  z.object({ type: z.literal('quote'), text: z.string(), attribution: z.string().optional() }),
  z.object({ type: z.literal('image'), url: z.string().url(), alt: z.string(), caption: z.string().optional() }),
  z.object({ type: z.literal('list'), ordered: z.boolean(), items: z.array(z.string()) }),
  z.object({ type: z.literal('callout'), tone: z.enum(['info', 'warning', 'tip']), title: z.string().optional(), text: z.string() }),
  z.object({ type: z.literal('embed'), provider: z.enum(['youtube', 'twitter', 'codepen']), url: z.string().url() }),
]);

const postBody = z.discriminatedUnion('format', [
  z.object({ format: z.literal('markdown'), content: z.string() }),
  z.object({ format: z.literal('blocks'), content: z.array(contentBlock) }),
]);

const postBase = z.object({
  id: z.string().min(1),
  title: z.string().min(1).max(200),
  slug,
  authorId: z.string().min(1),
  tags: z.array(slug).max(10),
  body: postBody,
  excerpt: z.string().max(500).optional(),
  coverImage: z.object({
    url: z.string().url(),
    alt: z.string(),
    width: z.number().int().positive().optional(),
    height: z.number().int().positive().optional(),
  }).optional(),
  seo: z.object({
    title: z.string().optional(),
    description: z.string().optional(),
    canonicalUrl: z.string().url().optional(),
    noIndex: z.boolean().optional(),
  }).optional(),
  createdAt: isoDate,
  updatedAt: isoDate,
});

export const postSchema = z.discriminatedUnion('status', [
  postBase.extend({ status: z.literal('draft') }),
  postBase.extend({ status: z.literal('published'), publishedAt: isoDate, scheduledFor: isoDate.optional() }),
  postBase.extend({ status: z.literal('archived'), publishedAt: isoDate, archivedAt: isoDate }),
]);

export type ValidatedPost = z.infer<typeof postSchema>;
```

---

## 4. Normalization rules

Invariants worth enforcing in one place rather than scattering across the codebase:

```ts
export function normalizeTagName(name: string): string {
  return name.trim().toLowerCase().replace(/\s+/g, '-');
}

export function normalizePost(input: ValidatedPost): ValidatedPost {
  const tags = [...new Set(input.tags.map(normalizeTagName))].slice(0, 10);

  return {
    ...input,
    slug: input.slug || slugify(input.title),
    tags,
    excerpt: input.excerpt ?? deriveExcerpt(input.body),
  };
}

function slugify(title: string): string {
  return title
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[^\w\s-]/g, '')
    .trim()
    .replace(/[\s_]+/g, '-')
    .slice(0, 80);
}
```

---

## 5. Storage mapping

A relational schema that mirrors the model:

```sql
CREATE TABLE posts (
  id            TEXT PRIMARY KEY,
  title         TEXT NOT NULL,
  slug          TEXT NOT NULL UNIQUE,
  author_id     TEXT NOT NULL REFERENCES authors(id),
  body_format   TEXT NOT NULL CHECK (body_format IN ('markdown', 'blocks')),
  body          TEXT NOT NULL,          -- JSON when format = 'blocks'
  excerpt       TEXT,
  cover_url     TEXT,
  cover_alt     TEXT,
  status        TEXT NOT NULL CHECK (status IN ('draft', 'published', 'archived')),
  published_at  TEXT,
  scheduled_for TEXT,
  archived_at   TEXT,
  seo           TEXT,                   -- JSON
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL
);

CREATE TABLE tags (
  id          TEXT PRIMARY KEY,
  name        TEXT NOT NULL,
  slug        TEXT NOT NULL UNIQUE,
  description TEXT,
  post_count  INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE post_tags (
  post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,
  tag_id  TEXT NOT NULL REFERENCES tags(id)  ON DELETE CASCADE,
  PRIMARY KEY (post_id, tag_id)
);

CREATE INDEX idx_posts_published ON posts (published_at DESC) WHERE status = 'published';
CREATE INDEX idx_post_tags_tag    ON post_tags (tag_id);
```

For a document store (MongoDB, DynamoDB, Firestore), the `Post` type maps 1:1 to a document; keep `tags` as an array of slugs and index it as a multikey field.

