export const BlogPostSchema = z.object({
  id: z.string().uuid(),
  title: z.string().min(1),
  author: z.object({
    id: z.string().uuid(),
    name: z.string().min(1),
    email: z.string().email().optional(),
    bio: z.string().optional(),
    avatarUrl: z.string().url().optional(),
  }),
