    z.object({
      id: z.string().uuid(),
      name: z.string().min(1),
      slug: z.string().min(1),
    })
  ),
  body: z.string(),
  createdAt: z.coerce.date(),
  updatedAt: z.coerce.date().optional(),
  published: z.boolean(),
});

export type BlogPost = z.infer<typeof BlogPostSchema>;
```

Using the schema as the source of truth keeps the runtime types and the static types in sync.

# Blog Post Data Model (TypeScript)

## Option 1: Simple / Flat Model

Best for small apps, prototypes, or when the API returns denormalized data.

```ts
export interface BlogPost {
  id: string;
  title: string;
  author: string;
  tags: string[];
  body: string;
}
```

**Example:**

```ts
const post: BlogPost = {
  id: "post_01",
  title: "Understanding TypeScript's Structural Typing",
  author: "Ada Lovelace",
  tags: ["typescript", "types"],
  body: "# Introduction\n\nTypeScript is structurally typed...",
};
```

---

## Option 2: Richer / Normalized Model

Better for real applications: authors and tags become first-class entities, and the body supports multiple formats.

```ts
export interface Author {
  id: string;
  name: string;
  email?: string;
  avatarUrl?: string;
  bio?: string;
}

export interface Tag {
  id: string;
  slug: string;
  name: string;
}

export type PostStatus = "draft" | "published" | "archived";

/** Body stored as Markdown source (render to HTML at the edge). */
export interface MarkdownBody {
  format: "markdown";
  content: string;
}

/** Body stored as pre-rendered HTML. */
export interface HtmlBody {
  format: "html";
  content: string;
}

export type PostBody = MarkdownBody | HtmlBody;

export interface BlogPost {
  id: string;
  title: string;
  slug: string;
  author: Author;
  tags: Tag[];
  body: PostBody;
  status: PostStatus;
  /** ISO 8601 date-time string, e.g. "2024-03-15T09:30:00Z" */
  publishedAt?: string;
  createdAt: string;
  updatedAt: string;
}
```

**Example:**

```ts
