  id: "post_01",
  title: "Understanding TypeScript's Structural Typing",
  slug: "understanding-typescript-structural-typing",
  author: {
    id: "usr_ada",
    name: "Ada Lovelace",
    email: "ada@example.com",
  },
  tags: [
    { id: "tag_ts", slug: "typescript", name: "TypeScript" },
    { id: "tag_types", slug: "types", name: "Types" },
