  | { type: "paragraph"; text: string }
  | { type: "heading"; level: 1 | 2 | 3; text: string }
  | { type: "image"; url: string; alt: string }
  | { type: "code"; language: string; code: string };

export interface BlogPost {
  id: string;
  title: string;
  author: Author;
  tags: Tag[];
  body: BodyBlock[];
  publishedAt?: string;
  createdAt: string;
  updatedAt: string;
}
```

