# Blog Post Data Model (TypeScript)

## 1. Design decisions up front

| Concern | Choice | Why |
|---|---|---|
| IDs | Branded strings | Prevents passing a `PostId` where an `AuthorId` is expected |
| Dates | ISO 8601 strings | JSON-safe; convert to `Date` at the edges |
| Author | Embedded snapshot **+** `authorId` | Renders without a join, but still queryable/indexable |
| Tags | Normalized objects with a `slug` | Stable URLs, display labels can change |
| Body | Discriminated union (markdown **or** blocks) | Supports both simple and rich content |
| Status | Discriminated union | `publishedAt` is only meaningful when published |

---

## 2. Primitives

```ts
declare const brand: unique symbol;
export type Brand<T, B extends string> = T & { readonly [brand]: B };

export type PostId = Brand<string, 'PostId'>;
export type AuthorId = Brand<string, 'AuthorId'>;
export type TagSlug = Brand<string, 'TagSlug'>;
export type ISODateString = Brand<string, 'ISODateString'>;
```

---

## 3. Core entities

```ts
export interface Author {
  id: AuthorId;
  name: string;
  slug: string;
  bio?: string;
  avatarUrl?: string;
  links?: {
    website?: string;
    twitter?: string;
    github?: string;
  };
  /** Never expose on public endpoints — keep in a separate private type. */
  email?: string;
}

export interface Tag {
  slug: TagSlug;      // e.g. "typescript" — lowercase, url-safe
  label: string;      // e.g. "TypeScript" — display name
  description?: string;
}

export interface ImageRef {
  url: string;
  alt: string;
  width?: number;
  height?: number;
  blurDataUrl?: string;
}
```

---

## 4. Body content

```ts
export type ContentBlock =
  | { type: 'paragraph'; text: string }
  | { type: 'heading'; level: 1 | 2 | 3 | 4; text: string; id?: string }
  | { type: 'code'; language?: string; code: string; filename?: string }
  | { type: 'image'; image: ImageRef; caption?: string }
  | { type: 'quote'; text: string; attribution?: string }
  | { type: 'list'; ordered: boolean; items: string[] }
  | { type: 'embed'; provider: 'youtube' | 'twitter' | 'codepen'; url: string };

export type PostBody =
  | { kind: 'markdown'; markdown: string }
  | { kind: 'blocks'; blocks: ContentBlock[] };
```

---

## 5. The `Post` entity

```ts
export type PostStatus =
  | { status: 'draft'; publishedAt?: never }
  | { status: 'scheduled'; publishedAt: ISODateString }
  | { status: 'published'; publishedAt: ISODateString }
  | { status: 'archived'; publishedAt: ISODateString };

export interface Post {
  id: PostId;
  title: string;
  slug: string;

  /** Denormalized snapshot for rendering. */
  author: Author;
  /** Canonical reference for queries/joins. */
  authorId: AuthorId;

  tags: Tag[];
  body: PostBody;

  excerpt?: string;
  coverImage?: ImageRef;
  canonicalUrl?: string;

  status: PostStatus['status'];
  publishedAt?: ISODateString;
  createdAt: ISODateString;
  updatedAt: ISODateString;

  seo?: {
    title?: string;
    description?: string;
    noIndex?: boolean;
  };

  /** Derived — compute on write, don't trust the client. */
  readingTimeMinutes?: number;
}
```

### Lightweight variant for list/index pages

```ts
export type PostSummary = Pick<
  Post,
  'id' | 'title' | 'slug' | 'excerpt' | 'coverImage' | 'publishedAt' | 'status'
> & {
  author: Pick<Author, 'name' | 'slug' | 'avatarUrl'>;
  tags: Pick<Tag, 'slug' | 'label'>[];
};
```

---

## 6. Runtime validation (don't trust `unknown` input)

```ts
import { z } from 'zod';

const isoDate = z.string().datetime({ offset: true });

export const tagSchema = z.object({
  slug: z.string().regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/),
  label: z.string().min(1).max(50),
  description: z.string().max(300).optional(),
});

export const postSchema = z.object({
  title: z.string().min(1).max(200),
  slug: z.string().regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/),
  authorId: z.string().min(1),
  tags: z.array(tagSchema).max(10),
  body: z.discriminatedUnion('kind', [
    z.object({ kind: z.literal('markdown'), markdown: z.string().min(1) }),
    z.object({ kind: z.literal('blocks'), blocks: z.array(z.unknown()).min(1) }),
  ]),
  excerpt: z.string().max(300).optional(),
  status: z.enum(['draft', 'scheduled', 'published', 'archived']),
  publishedAt: isoDate.optional(),
  canonicalUrl: z.string().url().optional(),
}).superRefine((post, ctx) => {
  if (post.status === 'published' && !post.publishedAt) {
    ctx.addIssue({
      code: z.ZodIssueCode.custom,
      path: ['publishedAt'],
      message: 'publishedAt is required for published posts',
    });
  }
});

export type PostInput = z.input<typeof postSchema>;
export type PostOutput = z.output<typeof postSchema>;
```

---

## 7. Normalization rules (apply on write)

```ts
export function normalizeTags(input: string[]): Tag[] {
  const seen = new Map<string, Tag>();
  for (const raw of input) {
    const slug = raw.trim().toLowerCase().replace(/\s+/g, '-');
    if (!slug || seen.has(slug)) continue;
    seen.set(slug, { slug: slug as TagSlug, label: raw.trim() });
  }
  return [...seen.values()].slice(0, 10);
}

export function estimateReadingTime(body: PostBody): number {
  const text =
    body.kind === 'markdown'
      ? body.markdown
      : body.blocks.map((b) => JSON.stringify(b)).join(' ');
  const words = text.split(/\s+/).filter(Boolean).length;
  return Math.max(1, Math.round(words / 220));
}
```

---

## 8. Storage mapping (SQL)

```sql
CREATE TABLE posts (
  id            UUID PRIMARY KEY,
  title         TEXT NOT NULL,
  slug          TEXT NOT NULL UNIQUE,
  author_id     UUID NOT NULL REFERENCES authors(id),
  body_kind     TEXT NOT NULL CHECK (body_kind IN ('markdown','blocks')),
  body          JSONB NOT NULL,
  excerpt       TEXT,
  status        TEXT NOT NULL CHECK (status IN ('draft','scheduled','published','archived')),
  published_at  TIMESTAMPTZ,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE post_tags (
  post_id UUID NOT NULL REFERENCES posts(id) ON DELETE CASCADE,
  tag_id  UUID NOT NULL REFERENCES tags(id),
  PRIMARY KEY (post_id, tag_id)
);

CREATE INDEX posts_published_idx ON posts (published_at DESC) WHERE status = 'published';
CREATE INDEX posts_author_idx    ON posts (author_id);
```

---

## 9. Common pitfalls this model avoids

- **Tag drift** — storing both `slug` and `label` means URLs stay stable when a label is renamed.
- **Impossible states** — the `PostStatus` union makes `published` without `publishedAt` unrepresentable.
- **N+1 queries** — the embedded `author` snapshot means rendering a list needs one query.
- **Over-fetching** — `PostSummary` keeps index pages from loading full bodies.
- **Untrusted input** — `zod` schema is the single gate between the wire and the domain.

