  title: string;
  author: string;         // display name
  tags: string[];         // plain tag names
  body: string;
}
```

**3. Immutable + branded IDs** — prevents accidental mutation and ID mix-ups:

```ts
type Brand<T, B extends string> = T & { readonly __brand: B };

export type PostId = Brand<string, 'PostId'>;
export type AuthorId = Brand<string, 'AuthorId'>;
export type TagId = Brand<string, 'TagId'>;

export interface BlogPost {
  readonly id: PostId;
  readonly title: string;
  readonly author: AuthorId;
  readonly tags: readonly TagId[];
  readonly body: string;
  readonly status: PostStatus;
  readonly createdAt: string;
  readonly updatedAt: string;
}
```

## Design notes

| Concern | Recommendation |
|---|---|
| Dates | Use ISO 8601 strings (`"2025-01-30T09:00:00Z"`) — JSON-serializable and sortable; convert to `Date` at the boundary. |
| Body format | Store Markdown as a string and render to HTML at read time; keep a separate `bodyHtml` only if you need a rendered cache. |
| Tags | Prefer `Tag[]` over `string[]` if you need slugs, colors, or per-tag metadata; otherwise plain strings are fine. |
| Status | A discriminated union (`'draft' | 'published' | 'archived'`) lets the compiler narrow `publishedAt` presence if you model it as a union type instead of an optional field. |
| Validation | These types are compile-time only — validate at runtime (e.g. Zod) when data crosses a network or user-input boundary. |

A stricter version of `status` + `publishedAt` as a union:

```ts
export type BlogPost =
  | (BasePost & { status: 'draft' | 'archived'; publishedAt?: undefined })
  | (BasePost & { status: 'published'; publishedAt: string });
```

