## 3. Core entities

```ts
// ---------------------------------------------------------------------------
// Author
// ---------------------------------------------------------------------------

export type SocialPlatform =
  | "website"
  | "twitter"
  | "github"
  | "linkedin"
  | "mastodon"
  | "bluesky";

export interface Author {
  id: AuthorId;
  /** Display name, e.g. "Ada Lovelace" */
  name: string;
  /** URL-safe handle used in /authors/:slug */
  slug: Slug;
  /** Short bio shown on the post and author page */
  bio?: string;
  avatarUrl?: string;
  links?: Partial<Record<SocialPlatform, string>>;
  /** Roles/permissions if the blog has multiple contributors */
  roles?: ("admin" | "editor" | "author" | "contributor")[];
}

// ---------------------------------------------------------------------------
// Tag
// ---------------------------------------------------------------------------

export interface Tag {
  id: TagId;
  /** Human-readable label, e.g. "TypeScript" */
  name: string;
  /** URL-safe form, e.g. "typescript" */
  slug: Slug;
  description?: string;
  /** Optional accent color for UI chips */
  color?: `#${string}`;
}

// ---------------------------------------------------------------------------
// Body — structured rich text
// ---------------------------------------------------------------------------

export type Mark = "bold" | "italic" | "strike" | "code" | "underline";

export type InlineNode =
  | { type: "text"; value: string; marks?: Mark[] }
  | { type: "link"; href: string; title?: string; children: InlineNode[] }
  | { type: "inlineCode"; value: string };

export type Block =
  | { type: "paragraph"; children: InlineNode[] }
  | { type: "heading"; level: 1 | 2 | 3 | 4 | 5 | 6; children: InlineNode[] }
  | { type: "blockquote"; children: Block[]; attribution?: string }
  | { type: "codeBlock"; language?: string; value: string; filename?: string }
  | { type: "image"; src: string; alt: string; caption?: string; width?: number; height?: number }
  | { type: "list"; ordered: boolean; items: InlineNode[][] }
  | { type: "horizontalRule" }
  | { type: "callout"; tone: "info" | "warning" | "tip"; children: InlineNode[] };

export interface RichTextDocument {
  version: 1;
  blocks: Block[];
}

/**
 * If your blog is Markdown-only, swap the body type for:
 *   export type Body = { format: "markdown"; source: string };
 */
export type Body = RichTextDocument;
```

