### Narrowing works as expected

```ts
function sortDate(post: BlogPost): ISODateString {
  switch (post.status) {
    case "published":
    case "archived":
      return post.publishedAt; // ✅ known to exist
    case "draft":
      return post.createdAt;
  }
}
```

