## 5. Storage form vs. read model

Keep the database normalized (IDs only) and hydrate on read:

```ts
/** As stored in Postgres/JSON columns */
export interface StoredPost {
  id: PostId;
  title: string;
  slug: Slug;
  authorId: AuthorId;
  tagIds: TagId[];
  body: Body;
  excerpt?: string;
  heroImage?: ImageRef;
  status: PostStatus;
  createdAt: ISODateString;
  updatedAt: ISODateString;
  publishedAt?: ISODateString;
  archivedAt?: ISODateString;
  seo?: SeoMeta;
  canonicalUrl?: string;
  relatedPostIds?: PostId[];
}

/** Hydrated for the UI / API response */
export interface HydratedPost extends Omit<StoredPost, "authorId" | "tagIds"> {
  author: Author;
  tags: Tag[];
}

export function hydrate(stored: StoredPost, authors: Map<AuthorId, Author>, tags: Map<TagId, Tag>): HydratedPost {
  const { authorId, tagIds, ...rest } = stored;
  const author = authors.get(authorId);
  if (!author) throw new Error(`Missing author ${authorId}`);
  return {
    ...rest,
    author,
    tags: tagIds.map((id) => {
      const tag = tags.get(id);
      if (!tag) throw new Error(`Missing tag ${id}`);
      return tag;
    }),
  };
}
```

