## 6. Runtime validation (schemas are the source of truth)

Types vanish at runtime, so validate at the boundary with Zod and *derive* the TS types from the schemas to avoid drift:

```ts
import { z } from "zod";

const slugSchema = z.string().regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/);
const isoDateSchema = z.string().datetime({ offset: true });

export const authorSchema = z.object({
  id: z.string().min(1),
  name: z.string().min(1).max(120),
  slug: slugSchema,
  bio: z.string().max(500).optional(),
  avatarUrl: z.string().url().optional(),
  links: z.record(z.string().url()).optional(),
  roles: z.array(z.enum(["admin", "editor", "author", "contributor"])).optional(),
});

export const tagSchema = z.object({
  id: z.string().min(1),
  name: z.string().min(1).max(40),
  slug: slugSchema,
  description: z.string().max(200).optional(),
  color: z.string().regex(/^#[0-9a-fA-F]{6}$/).optional(),
});

export const inlineNodeSchema: z.ZodType<InlineNode> = z.lazy(() =>
  z.union([
    z.object({ type: z.literal("text"), value: z.string(), marks: z.array(z.enum(["bold", "italic", "strike", "code", "underline"])).optional() }),
    z.object({ type: z.literal("link"), href: z.string(), title: z.string().optional(), children: z.array(inlineNodeSchema) }),
    z.object({ type: z.literal("inlineCode"), value: z.string() }),
  ])
);

export const bodySchema: z.ZodType<Body> = z.object({
  version: z.literal(1),
  blocks: z.array(z.record(z.unknown())),
});

export const blogPostSchema = z.discriminatedUnion("status", [
  z.object({
    id: z.string().min(1),
    title: z.string().min(1).max(200),
    slug: slugSchema,
    author: authorSchema,
    tags: z.array(tagSchema).max(10),
    body: bodySchema,
    excerpt: z.string().max(300).optional(),
    heroImage: z.object({ src: z.string(), alt: z.string() }).partial().optional(),
    status: z.literal("draft"),
    createdAt: isoDateSchema,
    updatedAt: isoDateSchema,
    publishedAt: z.never().optional(),
    seo: z.record(z.unknown()).optional(),
  }),
  z.object({
    id: z.string().min(1),
    title: z.string().min(1).max(200),
    slug: slugSchema,
    author: authorSchema,
    tags: z.array(tagSchema).max(10),
    body: bodySchema,
    excerpt: z.string().max(300).optional(),
    heroImage: z.object({ src: z.string(), alt: z.string() }).partial().optional(),
    status: z.literal("published"),
    createdAt: isoDateSchema,
    updatedAt: isoDateSchema,
    publishedAt: isoDateSchema,
    seo: z.record(z.unknown()).optional(),
  }),
  z.object({
    /* ...same as published... */
    status: z.literal("archived"),
    publishedAt: isoDateSchema,
    archivedAt: isoDateSchema,
  }),
]);

export type BlogPostInput = z.infer<typeof blogPostSchema>;
```

