## 7. Common operations

```ts
export function generateSlug(title: string): Slug {
  return title
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "") as Slug;
}

export function publish(post: BlogPost, at: Date = new Date()): PublishedPost {
  if (post.status === "published") return post;
  const { status, ...rest } = post;
  return { ...rest, status: "published", publishedAt: asISODate(at) };
}

export function addTag(post: BlogPost, tag: Tag): BlogPost {
  if (post.tags.some((t) => t.id === tag.id)) return post;
  return { ...post, tags: [...post.tags, tag], updatedAt: asISODate(new Date()) };
}

/** Plain-text projection for excerpts, search indexing, and RSS */
export function bodyToPlainText(body: Body): string {
  const walk = (nodes: InlineNode[]): string =>
    nodes.map((n) =>
      n.type === "text" ? n.value
      : n.type === "inlineCode" ? n.value
      : walk(n.children)
    ).join("");
  return body.blocks
    .map((b) => {
      switch (b.type) {
        case "paragraph":
        case "heading":
          return walk(b.children);
        case "codeBlock":
          return b.value;
        case "image":
          return b.alt;
        case "blockquote":
          return b.children.map((c) => ("children" in c ? walk(c.children) : "")).join(" ");
        case "list":
          return b.items.map(walk).join(" ");
        default:
          return "";
      }
    })
    .filter(Boolean)
    .join("\n\n");
}
```

