Below is a framework-agnostic set of types. The main design decisions:

- **Money is integer minor units + currency** (never floats).
- **Images are structured objects** (alt text, dimensions, responsive sources), not bare strings.
- **The description is a discriminated union** of a structured rich-text document *or* a Markdown string, so you can support both without `any`.

```ts
/* ------------------------------------------------------------------ */
/* Primitives & branded types                                          */
/* ------------------------------------------------------------------ */

declare const brand: unique symbol;
type Brand<T, B extends string> = T & { readonly [brand]: B };

type ISODateString = Brand<string, 'ISODateString'>;
type CurrencyCode = Brand<string, 'CurrencyCode'>; // "USD", "EUR", …
type Url = Brand<string, 'Url'>;
type Slug = Brand<string, 'Slug'>;

/* ------------------------------------------------------------------ */
/* Money                                                               */
/* ------------------------------------------------------------------ */

/** Amount is in the currency's minor unit (cents), as an integer. */
export interface Money {
  readonly amount: number;
  readonly currency: CurrencyCode;
}

/** A price that may be a range, e.g. "from $10". */
export interface PriceRange {
  readonly min: Money;
  readonly max: Money;
}

/* ------------------------------------------------------------------ */
/* Images                                                              */
/* ------------------------------------------------------------------ */

export type ImageRole = 'thumbnail' | 'hero' | 'gallery' | 'zoom' | 'swatch';

export interface ImageSource {
  readonly url: Url;
  readonly width: number;
  readonly height?: number;
  /** e.g. "2x" */
  readonly descriptor?: string;
}

export interface ProductImage {
  readonly id: string;
  readonly url: Url;
  /** Required for accessibility; empty string only if decorative. */
  readonly alt: string;
  readonly width: number;
  readonly height: number;
  readonly role?: ImageRole;
  /** Responsive candidates for `srcset`. */
  readonly sources?: readonly ImageSource[];
  readonly blurDataUrl?: string;
}

/* ------------------------------------------------------------------ */
/* Rich text                                                           */
/* ------------------------------------------------------------------ */

export interface TextNode {
  readonly type: 'text';
  readonly value: string;
}

export interface BoldNode {
  readonly type: 'bold';
  readonly children: readonly InlineNode[];
}

export interface ItalicNode {
  readonly type: 'italic';
  readonly children: readonly InlineNode[];
}

export interface UnderlineNode {
  readonly type: 'underline';
  readonly children: readonly InlineNode[];
}

export interface StrikeNode {
  readonly type: 'strike';
  readonly children: readonly InlineNode[];
}

export interface InlineCodeNode {
  readonly type: 'code';
  readonly value: string;
}

export interface LinkNode {
  readonly type: 'link';
  readonly href: Url;
  readonly title?: string;
  readonly external?: boolean;
  readonly children: readonly InlineNode[];
}

export type InlineNode =
  | TextNode
  | BoldNode
  | ItalicNode
  | UnderlineNode
  | StrikeNode
  | InlineCodeNode
  | LinkNode;

export interface ParagraphNode {
  readonly type: 'paragraph';
  readonly children: readonly InlineNode[];
}

export interface HeadingNode {
  readonly type: 'heading';
  /** 1–6 */
  readonly level: 1 | 2 | 3 | 4 | 5 | 6;
  readonly children: readonly InlineNode[];
}

export interface ListItemNode {
  readonly type: 'listItem';
  readonly children: readonly InlineNode[];
}

export interface ListNode {
  readonly type: 'list';
  readonly ordered: boolean;
  readonly start?: number;
  readonly items: readonly ListItemNode[];
}

export interface BlockquoteNode {
  readonly type: 'blockquote';
  readonly children: readonly InlineNode[];
}

export interface CodeBlockNode {
  readonly type: 'codeBlock';
  readonly language?: string;
  readonly value: string;
}

export interface ImageBlockNode {
  readonly type: 'image';
  readonly image: ProductImage;
  readonly caption?: string;
}

export interface DividerNode {
  readonly type: 'divider';
}

export interface TableNode {
  readonly type: 'table';
  readonly head: readonly (readonly InlineNode[])[];
  readonly rows: readonly (readonly (readonly InlineNode[])[])[];
}

export type BlockNode =
  | ParagraphNode
  | HeadingNode
  | ListNode
  | BlockquoteNode
  | CodeBlockNode
  | ImageBlockNode
  | DividerNode
  | TableNode;

/* ------------------------------------------------------------------ */
/* Description                                                         */
/* ------------------------------------------------------------------ */

export interface RichTextDescription {
  readonly format: 'richtext';
  readonly blocks: readonly BlockNode[];
  /** Pre-computed plain text, useful for meta descriptions and search. */
  readonly plainText?: string;
}

export interface MarkdownDescription {
  readonly format: 'markdown';
  readonly markdown: string;
}

export type ProductDescription = RichTextDescription | MarkdownDescription;

/* ------------------------------------------------------------------ */
/* Product                                                             */
/* ------------------------------------------------------------------ */

export type Availability =
  | 'in_stock'
  | 'out_of_stock'
  | 'preorder'
  | 'backorder'
  | 'discontinued';

export interface Rating {
  /** 0–5 */
  readonly value: number;
  readonly count: number;
}

export interface ProductVariant {
  readonly id: string;
  readonly name: string;
  readonly sku?: string;
  readonly options: Readonly<Record<string, string>>; // { size: "M", color: "Black" }
  readonly price?: Money; // overrides the parent price
  readonly compareAtPrice?: Money;
  readonly images?: readonly ProductImage[];
  readonly availability: Availability;
  readonly inStockQuantity?: number;
}

export interface Product {
  readonly id: string;
  readonly slug: Slug;
  readonly name: string;
  readonly subtitle?: string;
  readonly brand?: string;
  readonly sku?: string;

  readonly price: Money;
  readonly compareAtPrice?: Money;
  readonly priceRange?: PriceRange;

  readonly images: readonly ProductImage[];
  readonly description: ProductDescription;

  readonly availability: Availability;
  readonly rating?: Rating;
  readonly categories: readonly string[];
  readonly tags?: readonly string[];
  readonly variants?: readonly ProductVariant[];

  readonly createdAt: ISODateString;
  readonly updatedAt: ISODateString;
}

/* ------------------------------------------------------------------ */
/* Page-level payload                                                  */
/* ------------------------------------------------------------------ */

export interface Breadcrumb {
  readonly label: string;
  readonly href?: Url;
}

export interface ProductPageSeo {
  readonly title: string;
  readonly description: string;
  readonly canonicalUrl?: Url;
  readonly ogImage?: ProductImage;
}

export interface ProductPageData {
  readonly product: Product;
  readonly breadcrumbs: readonly Breadcrumb[];
  readonly relatedProducts?: readonly Product[];
  readonly seo?: ProductPageSeo;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

export function formatMoney(money: Money, locale = 'en-US'): string {
  return new Intl.NumberFormat(locale, {
    style: 'currency',
    currency: money.currency,
  }).format(money.amount / 100);
}

export function getPrimaryImage(product: Product): ProductImage | undefined {
  return (
    product.images.find((i) => i.role === 'hero') ??
    product.images.find((i) => i.role === 'thumbnail') ??
    product.images[0]
  );
}

export function isRichText(
  description: ProductDescription,
): description is RichTextDescription {
  return description.format === 'richtext';
}
```

