### Exhaustive rendering

The discriminated union means the compiler enforces that you handle every block type:

```ts
function renderBlock(block: RichTextBlock): string {
  switch (block.type) {
    case "paragraph": return `<p>${block.content.map(renderInline).join("")}</p>`;
    case "heading":   return `<h${block.level}>${block.content.map(renderInline).join("")}</h${block.level}>`;
    case "list":      return renderList(block);
    case "quote":     return `<blockquote>${block.content.map(renderInline).join("")}</blockquote>`;
    case "code":      return `<pre><code>${escapeHtml(block.code)}</code></pre>`;
    case "image":     return `<img src="${imageUrl(block.imageId)}" alt="">`;
    case "divider":   return "<hr>";
    case "table":     return renderTable(block);
    default: {
      // Compile error if a new block type is added and not handled.
      const _exhaustive: never = block;
      return _exhaustive;
    }
  }
}
```

