## Runtime validation

Types vanish at runtime, so validate API payloads at the boundary. Zod can mirror the schema and infer the TS types from it:

```ts
import { z } from "zod";

const moneySchema = z.object({
  amountMinor: z.number().int().nonnegative(),
  currency: z.string().length(3),
});

const imageSchema = z.object({
  id: z.string(),
  src: z.string().url(),
  alt: z.string(),
  width: z.number().int().positive(),
  height: z.number().int().positive(),
  role: z.enum(["hero", "gallery", "thumbnail", "detail", "variant"]),
});

const inlineSchema: z.ZodType<InlineNode> = z.lazy(() =>
  z.union([
    z.object({ type: z.literal("text"), value: z.string(), marks: z.array(z.string()).optional() }),
    z.object({
      type: z.literal("link"),
      href: z.string(),
      title: z.string().optional(),
      children: z.array(inlineSchema),
    }),
    z.object({ type: z.literal("lineBreak") }),
  ]),
);

const descriptionSchema = z.discriminatedUnion("format", [
  z.object({
    format: z.literal("richtext"),
    version: z.literal(1),
    blocks: z.array(z.record(z.unknown())), // refine per block type as needed
  }),
  z.object({ format: z.literal("markdown"), source: z.string() }),
  z.object({ format: z.literal("plain"), source: z.string() }),
]);

export const productSchema = z.object({
  id: z.string(),
  slug: z.string(),
  name: z.string().min(1),
  price: z.object({ current: moneySchema, compareAt: moneySchema.optional() }),
  images: z.array(imageSchema).min(1),
  description: descriptionSchema,
  availability: z.discriminatedUnion("status", [
    z.object({ status: z.literal("in_stock"), quantity: z.number().int().optional() }),
    z.object({ status: z.literal("low_stock"), quantity: z.number(), threshold: z.number() }),
    z.object({ status: z.literal("out_of_stock") }),
    z.object({ status: z.literal("preorder"), shipsAt: z.string().optional() }),
    z.object({ status: z.literal("discontinued") }),
  ]),
});

export type ValidatedProduct = z.infer<typeof productSchema>;
```

