## A few notes

- **`exactOptionalPropertyTypes`**: if you enable it in `tsconfig`, `subtitle?: string` will *not* accept `subtitle: undefined`. Either use `subtitle?: string | undefined` or keep the flag off.
- **Don't use `Date`** in these types — it doesn't survive `JSON.parse`/`JSON.stringify` round-trips without custom revivers.
- **Money formatting** belongs in a helper, not the type:

  ```ts
  export function formatMoney(m: Money, locale = "en-US"): string {
    return new Intl.NumberFormat(locale, {
      style: "currency",
      currency: m.currency,
    }).format(m.amountMinor / 100);
  }
  ```
  (Note: JPY and other zero-decimal currencies need a currency-specific exponent — use `Intl` with a lookup table rather than a hardcoded `/100` if you support them.)
- **If your CMS only stores Markdown**, drop the `RichTextDocument` variant entirely and keep `Description` as `{ format: "markdown"; source: string }` — the discriminated union still gives you a clean place to add a structured format later.

Below is a complete, production-oriented type module. The main design decisions:

- **Money is stored in minor units** (integer cents) as a `{ amount, currency }` pair — never a float.
- **The description is a discriminated union** (`format: 'richtext' | 'markdown' | 'html'`) so the renderer can branch exhaustively.
- **Rich text is split into blocks + inline nodes**, with marks modeled as a separate array rather than nested wrappers.
- **IDs and URLs are branded** so a `ProductId` can't be passed where a `Sku` is expected.

```ts
// ============================================================================
// Primitives
// ============================================================================

/** Nominal typing helper: `Brand<string, 'ProductId'>` is not assignable to `string`. */
export type Brand<T, B extends string> = T & { readonly __brand: B };

export type ProductId = Brand<string, 'ProductId'>;
export type VariantId = Brand<string, 'VariantId'>;
export type ImageId = Brand<string, 'ImageId'>;
export type UrlString = Brand<string, 'UrlString'>;
export type ISODateString = Brand<string, 'ISODateString'>;
export type CurrencyCode =
  | 'USD' | 'EUR' | 'GBP' | 'CAD' | 'AUD' | 'JPY'
  | 'CHF' | 'SEK' | 'NOK' | 'DKK' | 'PLN' | 'CZK'
  | 'INR' | 'BRL' | 'MXN' | 'ZAR' | 'SGD' | 'HKD' | 'AED';

// ============================================================================
// Money & pricing
// ============================================================================

export interface Money {
  /** Minor units (e.g. cents). 1999 === $19.99. Always an integer. */
  readonly amount: number;
  readonly currency: CurrencyCode;
}

export interface Price {
  /** The price actually charged. */
  readonly current: Money;
  /** Original/list price, when the item is discounted. */
  readonly compareAt?: Money;
  /** Precomputed 0–100, for display only. Derive if you prefer. */
  readonly discountPercent?: number;
  /** Tax-inclusive vs. tax-exclusive, for display. */
  readonly taxMode?: 'inclusive' | 'exclusive';
  /** Optional price range for variable products (e.g. "from $10"). */
  readonly range?: { readonly min: Money; readonly max: Money };
}

// ============================================================================
// Images
// ============================================================================

export type ImageRole = 'primary' | 'gallery' | 'thumbnail' | 'swatch' | 'hero';

export interface ProductImage {
  readonly id: ImageId;
  readonly url: UrlString;
  /** Required for accessibility. Empty string only if decorative. */
  readonly alt: string;
  readonly width: number;
  readonly height: number;
  readonly role: ImageRole;
  /** Tiny base64 LQIP for blur-up placeholders. */
  readonly blurDataUrl?: string;
  /** CDN transform hints, e.g. { width: 800, format: 'webp' }. */
  readonly transforms?: Readonly<Record<string, string | number>>;
  /** Optional per-image caption shown in the gallery. */
  readonly caption?: string;
}

// ============================================================================
// Rich text: inline nodes
// ============================================================================

export type TextMark =
  | 'bold'
  | 'italic'
  | 'underline'
  | 'strike'
  | 'code'
  | 'highlight'
  | 'superscript'
  | 'subscript';

export type InlineNode =
  | {
      readonly type: 'text';
      readonly value: string;
      readonly marks?: readonly TextMark[];
    }
  | {
      readonly type: 'link';
      readonly href: UrlString;
      readonly children: readonly InlineNode[];
      /** Open in a new tab (implies rel="noopener noreferrer"). */
      readonly newTab?: boolean;
      readonly title?: string;
    }
  | {
      readonly type: 'lineBreak';
    };

// ============================================================================
// Rich text: block nodes
// ============================================================================

export interface ParagraphBlock {
  readonly type: 'paragraph';
  readonly children: readonly InlineNode[];
}

export interface HeadingBlock {
  readonly type: 'heading';
  /** 1–6, mapped to <h1>–<h6>. */
  readonly level: 1 | 2 | 3 | 4 | 5 | 6;
  readonly children: readonly InlineNode[];
  readonly id?: string; // anchor slug
}

export interface ListBlock {
  readonly type: 'list';
  readonly style: 'ordered' | 'unordered';
  readonly items: readonly ListItem[];
  readonly start?: number; // for ordered lists
}

export interface ListItem {
  readonly children: readonly InlineNode[];
  /** Nested lists. */
  readonly childrenBlocks?: readonly RichTextBlock[];
  readonly checked?: boolean; // task-list items
}

export interface QuoteBlock {
  readonly type: 'quote';
  readonly children: readonly InlineNode[];
  readonly attribution?: string;
  readonly sourceUrl?: UrlString;
}

export interface CodeBlock {
  readonly type: 'code';
  readonly language?: string;
  readonly code: string;
  readonly filename?: string;
  readonly showLineNumbers?: boolean;
}

export interface ImageBlock {
  readonly type: 'image';
  readonly image: ProductImage;
  readonly caption?: string;
  /** Optional link target for the image. */
  readonly href?: UrlString;
}

export interface VideoBlock {
  readonly type: 'video';
  readonly url: UrlString;
  readonly poster?: ProductImage;
  readonly caption?: string;
  readonly transcript?: string;
}

export interface TableBlock {
  readonly type: 'table';
  readonly caption?: string;
  readonly columns: readonly TableColumn[];
  readonly rows: readonly TableRow[];
}

export interface TableColumn {
  readonly key: string;
  readonly header: string;
  readonly align?: 'left' | 'center' | 'right';
  readonly width?: number;
}

export interface TableRow {
  readonly cells: readonly (string | number | boolean | null)[];
  readonly isHeader?: boolean;
}

export interface CalloutBlock {
  readonly type: 'callout';
  readonly tone: 'info' | 'success' | 'warning' | 'danger' | 'note';
  readonly title?: string;
  readonly children: readonly InlineNode[];
}

export interface DividerBlock {
  readonly type: 'divider';
}

export type RichTextBlock =
  | ParagraphBlock
  | HeadingBlock
  | ListBlock
  | QuoteBlock
  | CodeBlock
  | ImageBlock
  | VideoBlock
  | TableBlock
  | CalloutBlock
  | DividerBlock;

// ============================================================================
// Description
// ============================================================================

/** Structured, renderer-friendly description. */
export interface RichTextDescription {
  readonly format: 'richtext';
  readonly blocks: readonly RichTextBlock[];
  /** Plain-text fallback for meta descriptions and search indexing. */
  readonly plainText?: string;
}

/** Markdown source, parsed at render time. */
export interface MarkdownDescription {
  readonly format: 'markdown';
  readonly source: string;
  readonly plainText?: string;
}

/**
 * Pre-rendered HTML. Only use with sanitized output — the string is
 * injected verbatim, so it must come from a trusted, sanitized pipeline.
 */
export interface HtmlDescription {
  readonly format: 'html';
  readonly html: string;
  readonly plainText?: string;
}

export type ProductDescription =
  | RichTextDescription
  | MarkdownDescription
  | HtmlDescription;

// ============================================================================
// Supporting product data
// ============================================================================

export interface BrandInfo {
  readonly name: string;
  readonly slug?: string;
  readonly logoUrl?: UrlString;
}

export interface Specification {
  readonly label: string;
  readonly value: string;
  readonly group?: string;
  readonly unit?: string;
}

export type Availability =
  | { readonly status: 'in_stock'; readonly quantity?: number }
  | { readonly status: 'low_stock'; readonly quantity: number; readonly threshold: number }
  | { readonly status: 'out_of_stock' }
  | { readonly status: 'preorder'; readonly shipsAt?: ISODateString }
  | { readonly status: 'discontinued' }
  | { readonly status: 'made_to_order'; readonly leadTimeDays?: number };

export interface Rating {
  readonly average: number; // 0–5
  readonly count: number;
  readonly histogram?: readonly [number, number, number, number, number];
}

export interface ProductVariant {
  readonly id: VariantId;
  readonly sku: string;
  readonly name: string;
  readonly price: Price;
  readonly images?: readonly ProductImage[];
  readonly options: Readonly<Record<string, string>>; // { size: 'M', color: 'Black' }
  readonly availability: Availability;
}

export interface SeoMeta {
  readonly title?: string;
  readonly description?: string;
  readonly canonicalUrl?: UrlString;
  readonly ogImage?: ProductImage;
  readonly noindex?: boolean;
}

// ============================================================================
// The product
// ============================================================================

export interface Product {
  readonly id: ProductId;
  readonly slug: string;
  readonly name: string;
  readonly subtitle?: string;
  readonly brand?: BrandInfo;

  readonly price: Price;
  readonly images: readonly ProductImage[];
  readonly description: ProductDescription;

  /** Short bullet points shown above the description. */
  readonly highlights?: readonly string[];
  readonly specifications?: readonly Specification[];
  readonly variants?: readonly ProductVariant[];
  readonly availability: Availability;
  readonly rating?: Rating;
  readonly tags?: readonly string[];
  readonly seo?: SeoMeta;

  readonly createdAt: ISODateString;
  readonly updatedAt: ISODateString;
}

// ============================================================================
// The page (product page payload)
// ============================================================================

export interface Breadcrumb {
  readonly label: string;
  readonly href?: UrlString;
}

export interface ProductPage {
  readonly product: Product;
  readonly breadcrumbs?: readonly Breadcrumb[];
  readonly relatedProducts?: readonly Product[];
  readonly reviews?: {
    readonly rating: Rating;
    readonly items: readonly Review[];
  };
  /** Server-rendered timestamp, useful for cache keys. */
  readonly generatedAt: ISODateString;
}

export interface Review {
  readonly id: string;
  readonly author: string;
  readonly rating: number; // 1–5
  readonly title?: string;
  readonly body: string;
  readonly createdAt: ISODateString;
  readonly verifiedPurchase?: boolean;
}

// ============================================================================
// Narrowing helpers
// ============================================================================

export function isRichText(
  description: ProductDescription,
): description is RichTextDescription {
  return description.format === 'richtext';
}

/** Flatten a rich-text description to plain text (for meta tags, previews). */
export function toPlainText(description: ProductDescription): string {
  if (description.plainText) return description.plainText;
  if (description.format !== 'richtext') return '';

  const inline = (nodes: readonly InlineNode[]): string =>
    nodes
      .map((node) => {
        switch (node.type) {
          case 'text':
            return node.value;
          case 'link':
            return inline(node.children);
          case 'lineBreak':
            return '\n';
        }
      })
      .join('');

  const block = (b: RichTextBlock): string => {
    switch (b.type) {
      case 'paragraph':
      case 'heading':
      case 'quote':
      case 'callout':
        return inline(b.children);
      case 'list':
        return b.items.map((i) => inline(i.children)).join('\n');
      case 'code':
        return b.code;
      case 'image':
        return b.caption ?? '';
      case 'video':
        return b.caption ?? '';
      case 'table':
        return b.rows.map((r) => r.cells.join(' ')).join('\n');
      case 'divider':
        return '';
    }
  };

  return description.blocks.map(block).join('\n\n');
}
```

