### Notes

- **Validate at the boundary.** These types are compile-time only; pair them with a runtime schema (Zod, Valibot, or JSON Schema) so API responses are checked before being cast to `Product`.
- **If the CMS gives you Markdown**, use the `markdown` variant and parse it server-side — don't ship a Markdown parser to the client unless you need it.
- **If you need HTML**, sanitize it (e.g. `DOMPurify` server-side) before storing it in the `html` variant; the type system can't protect you from XSS.
- **Consider `readonly` arrays** as shown — they prevent accidental mutation of shared cached objects. If you need mutability in local state, spread into a mutable copy.
- **For i18n**, wrap user-facing strings in a `LocalizedString` type (`string | Record<Locale, string>`) rather than adding a parallel field per locale.

Below is a self-contained, production-shaped set of types. The main design decisions:

- **Money is integer minor units + currency** (never floats).
- **Images are a list of objects**, not bare strings, so alt text and dimensions survive.
- **The description is a discriminated union** — either a structured rich-text document (blocks + inline marks) or plain Markdown — so the renderer can branch on `format`.

```ts
/* ------------------------------------------------------------------ *
 * Primitives & branded IDs
 * ------------------------------------------------------------------ */

type Brand<T, B extends string> = T & { readonly __brand: B };

export type ProductId = Brand<string, 'ProductId'>;
export type Sku = Brand<string, 'Sku'>;

export type CurrencyCode =
  | 'USD' | 'EUR' | 'GBP' | 'JPY' | 'CAD' | 'AUD' | 'CHF' | 'SEK' | 'NOK' | 'DKK';

/** ISO 4217 amount in the currency's minor unit (e.g. cents). Always an integer. */
export interface Money {
  readonly amountMinor: number;
  readonly currency: CurrencyCode;
}

/* ------------------------------------------------------------------ *
 * Pricing
 * ------------------------------------------------------------------ */

export interface Price {
  /** The price actually charged. */
  readonly current: Money;
  /** Original/list price, when the item is discounted. */
  readonly compareAt?: Money;
  /** True when `current` already includes tax. */
  readonly taxInclusive?: boolean;
  /** Optional per-unit price (e.g. "per 100 g"). */
  readonly unit?: PriceUnit;
}

export interface PriceUnit {
  readonly label: string;          // "per 100 g"
  readonly quantity: number;
  readonly unitCode: string;        // "g", "kg", "ml"
}

/* ------------------------------------------------------------------ *
 * Images
 * ------------------------------------------------------------------ */

export type ImageRole = 'primary' | 'gallery' | 'thumbnail' | 'swatch';

export interface ProductImage {
  readonly id: string;
  readonly url: string;
  /** Required for accessibility; empty string is not allowed. */
  readonly alt: string;
  readonly width: number;
  readonly height: number;
  readonly role: ImageRole;
  /** Optional responsive sources, largest last. */
  readonly sources?: readonly ImageSource[];
  /** Optional focal point, 0–1, for cropping. */
  readonly focalPoint?: { readonly x: number; readonly y: number };
}

export interface ImageSource {
  readonly url: string;
  readonly width: number;
  readonly height: number;
}

/* ------------------------------------------------------------------ *
 * Rich text description
 * ------------------------------------------------------------------ */

export type TextMark =
  | 'bold'
  | 'italic'
  | 'underline'
  | 'strike'
  | 'code'
  | 'superscript'
  | 'subscript'
  | 'highlight';

export interface TextNode {
  readonly type: 'text';
  readonly value: string;
  readonly marks?: readonly TextMark[];
}

export interface LinkNode {
  readonly type: 'link';
  readonly href: string;
  readonly title?: string;
  readonly target?: '_self' | '_blank';
  readonly rel?: string;
  readonly children: readonly InlineNode[];
}

export interface InlineImageNode {
  readonly type: 'inlineImage';
  readonly image: ProductImage;
}

export interface LineBreakNode {
  readonly type: 'lineBreak';
}

export type InlineNode = TextNode | LinkNode | InlineImageNode | LineBreakNode;

/* --- Block level --- */

export interface ParagraphBlock {
  readonly type: 'paragraph';
  readonly children: readonly InlineNode[];
}

export interface HeadingBlock {
  readonly type: 'heading';
  readonly level: 1 | 2 | 3 | 4 | 5 | 6;
  readonly children: readonly InlineNode[];
}

export interface ListItem {
  readonly children: readonly InlineNode[];
  readonly childrenBlocks?: readonly BlockNode[]; // nested lists
}

export interface ListBlock {
  readonly type: 'list';
  readonly style: 'ordered' | 'unordered';
  readonly start?: number;
  readonly items: readonly ListItem[];
}

export interface QuoteBlock {
  readonly type: 'quote';
  readonly children: readonly InlineNode[];
  readonly attribution?: string;
}

export interface CodeBlock {
  readonly type: 'code';
  readonly language?: string;
  readonly value: string;
}

export interface ImageBlock {
  readonly type: 'image';
  readonly image: ProductImage;
  readonly caption?: string;
}

export interface DividerBlock {
  readonly type: 'divider';
}

export interface TableBlock {
  readonly type: 'table';
  readonly header: readonly (readonly InlineNode[])[];
  readonly rows: readonly (readonly (readonly InlineNode[])[])[];
}

export type BlockNode =
  | ParagraphBlock
  | HeadingBlock
  | ListBlock
  | QuoteBlock
  | CodeBlock
  | ImageBlock
  | DividerBlock
  | TableBlock;

/** A structured, renderable document. */
export interface RichTextDocument {
  readonly type: 'doc';
  readonly version: 1;
  readonly content: readonly BlockNode[];
}

/* ------------------------------------------------------------------ *
 * Description (discriminated union)
 * ------------------------------------------------------------------ */

export interface RichTextDescription {
  readonly format: 'richText';
  readonly document: RichTextDocument;
  /** Optional plain-text fallback for SEO / meta descriptions. */
  readonly plainText?: string;
}

export interface MarkdownDescription {
  readonly format: 'markdown';
  readonly source: string;
  readonly plainText?: string;
}

export interface HtmlDescription {
  readonly format: 'html';
  readonly html: string;
  readonly plainText?: string;
}

export type ProductDescription =
  | RichTextDescription
  | MarkdownDescription
  | HtmlDescription;

/* ------------------------------------------------------------------ *
 * Product
 * ------------------------------------------------------------------ */

export type Availability =
  | { readonly status: 'inStock' }
  | { readonly status: 'outOfStock' }
  | { readonly status: 'preOrder'; readonly shipsOn: string }
  | { readonly status: 'backOrder'; readonly shipsOn?: string }
  | { readonly status: 'limited'; readonly remaining: number };

export interface ProductCategory {
  readonly id: string;
  readonly name: string;
  readonly slug: string;
  readonly parentId?: string;
}

export interface ProductBadge {
  readonly label: string;
  readonly tone: 'neutral' | 'positive' | 'warning' | 'critical';
}

export interface Product {
  readonly id: ProductId;
  readonly slug: string;
  readonly name: string;
  readonly subtitle?: string;
  readonly brand?: string;
  readonly sku?: Sku;

  readonly price: Price;
  readonly images: readonly ProductImage[];
  readonly description: ProductDescription;

  readonly availability: Availability;
  readonly categories?: readonly ProductCategory[];
  readonly badges?: readonly ProductBadge[];

  readonly attributes?: readonly ProductAttribute[];
  readonly rating?: Rating;
  readonly seo?: ProductSeo;

  readonly createdAt: string; // ISO 8601
  readonly updatedAt: string;
}

export interface ProductAttribute {
  readonly name: string;
  readonly value: string;
  readonly group?: string;
}

export interface Rating {
  readonly average: number;   // 0–5
  readonly count: number;
}

export interface ProductSeo {
  readonly title?: string;
  readonly metaDescription?: string;
  readonly ogImage?: ProductImage;
}

/* ------------------------------------------------------------------ *
 * The page itself
 * ------------------------------------------------------------------ */

export interface Breadcrumb {
  readonly label: string;
  readonly href: string;
}

export interface ProductPage {
  readonly product: Product;
  readonly breadcrumbs?: readonly Breadcrumb[];
  readonly relatedProducts?: readonly Product[];
  readonly variants?: readonly ProductVariant[];
  readonly locale: string;
  readonly currency: CurrencyCode;
}

/** A purchasable variant (size/colour) of a product. */
export interface ProductVariant {
  readonly id: string;
  readonly productId: ProductId;
  readonly sku: Sku;
  readonly name: string;              // "Midnight Blue / M"
  readonly options: Readonly<Record<string, string>>; // { color: 'Midnight Blue', size: 'M' }
  readonly price: Price;
  readonly image?: ProductImage;
  readonly availability: Availability;
}
