// ---------------------------------------------------------------------------
// Primitives
// ---------------------------------------------------------------------------

export type CurrencyCode =
  | "USD" | "EUR" | "GBP" | "JPY" | "CAD" | "AUD"
  | (string & {}); // allow other ISO-4217 codes without losing autocomplete

export interface Money {
  /** Amount in minor units (e.g. cents) to avoid floating-point rounding errors. */
  readonly amount: number;
  readonly currency: CurrencyCode;
}

// ---------------------------------------------------------------------------
// Images
// ---------------------------------------------------------------------------

export type ImageRole = "primary" | "gallery" | "thumbnail" | "detail";

export interface ProductImage {
  readonly id: string;
  readonly url: string;
  /** Required for accessibility — describe the image's content. */
  readonly altText: string;
  readonly width?: number;
  readonly height?: number;
  readonly role?: ImageRole;
  readonly srcSet?: Readonly<Record<string, string>>; // e.g. { "480w": "...", "960w": "..." }
}

// ---------------------------------------------------------------------------
// Rich text (the long, formatted description)
// ---------------------------------------------------------------------------

export type Mark =
  | "bold"
  | "italic"
  | "underline"
  | "strikethrough"
  | "code"
  | "highlight";

export interface TextSpan {
  readonly type: "text";
  readonly text: string;
  readonly marks?: readonly Mark[];
}

export interface LinkSpan {
  readonly type: "link";
  readonly text: string;
  readonly href: string;
  readonly marks?: readonly Mark[];
  readonly rel?: string; // e.g. "noopener noreferrer"
}

export type InlineSpan = TextSpan | LinkSpan;

export interface ParagraphBlock {
  readonly type: "paragraph";
  readonly spans: readonly InlineSpan[];
}

export interface HeadingBlock {
  readonly type: "heading";
  readonly level: 1 | 2 | 3 | 4 | 5 | 6;
  readonly spans: readonly InlineSpan[];
}

export interface ListItem {
  readonly spans: readonly InlineSpan[];
  readonly children?: readonly ListItem[]; // nested sub-items
}

export interface ListBlock {
  readonly type: "list";
  readonly style: "ordered" | "unordered";
  readonly items: readonly ListItem[];
}

export interface QuoteBlock {
  readonly type: "quote";
  readonly spans: readonly InlineSpan[];
  readonly attribution?: string;
}

export interface ImageBlock {
  readonly type: "image";
  readonly image: ProductImage;
  readonly caption?: readonly InlineSpan[];
}

export interface DividerBlock {
  readonly type: "divider";
}

export type RichTextBlock =
  | ParagraphBlock
  | HeadingBlock
  | ListBlock
  | QuoteBlock
