### Notes on the design

- **Money in minor units** avoids `0.1 + 0.2` style bugs; format at the edge with `Intl.NumberFormat`.
- **Discriminated unions** (`type: "paragraph" | "heading" | ...`) let you exhaustively `switch` on blocks with no `any` and no optional-field guessing.
- **Inline vs. block separation** mirrors how rich-text editors (TipTap, Lexical, ProseMirror) actually model content, so the data maps cleanly onto a WYSIWYG editor.
- **Images are a shared type** used both in the gallery and inside the description, so alt text and dimensions are enforced everywhere.

### Simpler alternative

If the description is stored as trusted HTML from a CMS, you can replace the rich-text model with:

```ts
export interface Product {
  readonly id: string;
  readonly name: string;
  readonly price: Money;
  readonly images: readonly ProductImage[];
  /** Sanitized HTML. */
  readonly descriptionHtml: string;
}
```

Use this only if you sanitize the HTML on write (e.g. DOMPurify) — otherwise you risk XSS.

Below is a self-contained domain model for a product detail page. The main design decisions:

- **Money is stored in minor units** (cents) as an integer to avoid floating-point drift.
- **Images are a structured list** with dimensions, alt text, and responsive sources — not just URLs.
- **The description is a discriminated union** so you can support rich text, Markdown, or raw HTML without changing the page type.
- **Rich text is a typed AST** (blocks + inline nodes + marks) rather than a string, so formatting is introspectable and safe to render.

```ts
// ===========================================================================
// product.types.ts
// ===========================================================================

// ---------------------------------------------------------------------------
// Money & pricing
// ---------------------------------------------------------------------------

/** ISO 4217 currency code, e.g. "USD", "EUR", "GBP". */
export type CurrencyCode = string;

export interface Money {
  /** Amount in the currency's *minor* unit (e.g. cents). Never a float. */
  readonly amount: number;
  readonly currency: CurrencyCode;
}

export interface Price {
  /** The price the customer actually pays. */
  readonly current: Money;
  /** Original/list price, present only when the item is discounted. */
  readonly compareAt?: Money;
  /** Precomputed discount, 0–100. Derive from `compareAt` if omitted. */
  readonly discountPercent?: number;
  /** Optional unit label, e.g. "per 100 g" or "/month". */
  readonly unitLabel?: string;
}

// ---------------------------------------------------------------------------
// Images
// ---------------------------------------------------------------------------

export type ImageRole = 'thumbnail' | 'hero' | 'gallery' | 'swatch';

/** A single responsive candidate for an image. */
export interface ImageSource {
  readonly src: string;
  readonly width: number;
  /** Optional `srcset` descriptor, e.g. "2x" or "640w". */
  readonly descriptor?: string;
}

export interface ProductImage {
  readonly id: string;
  /** Absolute or CDN-relative URL of the default (largest) rendition. */
  readonly src: string;
  /** Required for accessibility. Describe the product, not the file. */
  readonly alt: string;
  readonly width: number;
  readonly height: number;
  readonly role?: ImageRole;
  /** Responsive candidates for `srcset`. */
  readonly sources?: readonly ImageSource[];
  /** Tiny blurred placeholder (base64 data URL) for progressive loading. */
  readonly blurDataUrl?: string;
  /** Optional caption shown in the gallery lightbox. */
  readonly caption?: string;
}

// ---------------------------------------------------------------------------
// Rich text: inline nodes
// ---------------------------------------------------------------------------

/** A formatting mark applied to a run of text. */
export type TextMark =
  | { readonly type: 'bold' }
  | { readonly type: 'italic' }
  | { readonly type: 'underline' }
  | { readonly type: 'strikethrough' }
  | { readonly type: 'code' }
  | {
      readonly type: 'link';
      readonly href: string;
      readonly title?: string;
      readonly rel?: string;
      readonly target?: '_blank' | '_self';
    };

export interface TextNode {
  readonly type: 'text';
  readonly value: string;
  readonly marks?: readonly TextMark[];
}

export interface LineBreakNode {
  readonly type: 'lineBreak';
}

/** Anything that can appear inside a paragraph, heading, list item, etc. */
export type InlineNode = TextNode | LineBreakNode;

// ---------------------------------------------------------------------------
// Rich text: block nodes
// ---------------------------------------------------------------------------

export interface ParagraphBlock {
  readonly type: 'paragraph';
  readonly children: readonly InlineNode[];
}

export interface HeadingBlock {
  readonly type: 'heading';
  /** Heading level, 1–6. */
  readonly level: 1 | 2 | 3 | 4 | 5 | 6;
  readonly children: readonly InlineNode[];
  /** Anchor id for deep-linking / table of contents. */
  readonly id?: string;
}

export interface ListItemBlock {
  readonly type: 'listItem';
  readonly children: readonly RichTextBlock[];
  /** `true` when the item is checked in a task list. */
  readonly checked?: boolean;
}

export interface ListBlock {
  readonly type: 'list';
  readonly style: 'ordered' | 'unordered';
  /** First number of an ordered list. Defaults to 1. */
  readonly start?: number;
  readonly items: readonly ListItemBlock[];
}

export interface QuoteBlock {
  readonly type: 'quote';
  readonly children: readonly InlineNode[];
  readonly attribution?: string;
}

export interface CodeBlock {
  readonly type: 'code';
  readonly value: string;
  readonly language?: string;
  /** Show a copy-to-clipboard affordance. */
  readonly copyable?: boolean;
}

export interface ImageBlock {
  readonly type: 'image';
  readonly image: ProductImage;
  readonly caption?: string;
}

export interface DividerBlock {
  readonly type: 'divider';
}

export interface TableCell {
  readonly children: readonly InlineNode[];
  readonly header?: boolean;
  readonly colspan?: number;
  readonly rowspan?: number;
}

export interface TableBlock {
  readonly type: 'table';
  readonly rows: readonly (readonly TableCell[])[];
  readonly caption?: string;
}

/** Any top-level block in a rich-text document. */
export type RichTextBlock =
  | ParagraphBlock
  | HeadingBlock
  | ListBlock
  | QuoteBlock
  | CodeBlock
  | ImageBlock
  | DividerBlock
  | TableBlock;

// ---------------------------------------------------------------------------
// Description
// ---------------------------------------------------------------------------

/**
 * The long-form product description. Exactly one representation is used,
 * chosen by the `format` discriminant.
 */
export type ProductDescription =
  | {
      readonly format: 'richtext';
      readonly blocks: readonly RichTextBlock[];
    }
  | {
      readonly format: 'markdown';
      readonly source: string;
    }
  | {
      readonly format: 'html';
      /** Must be sanitized before rendering. */
      readonly html: string;
    };

// ---------------------------------------------------------------------------
// Supporting page data
// ---------------------------------------------------------------------------

export interface Brand {
  readonly id: string;
  readonly name: string;
  readonly logoUrl?: string;
  readonly href?: string;
}

export type AvailabilityStatus =
  | 'inStock'
  | 'outOfStock'
  | 'preOrder'
  | 'backOrder'
  | 'discontinued';

export interface Availability {
  readonly status: AvailabilityStatus;
  /** ISO 8601 timestamp. */
  readonly restockDate?: string;
  readonly quantity?: number;
}

export interface Rating {
  readonly average: number; // 0–5
  readonly count: number;
}

export interface Breadcrumb {
  readonly label: string;
  readonly href: string;
}

export interface SeoMeta {
  readonly title: string;
  readonly description: string;
  readonly canonicalUrl?: string;
  readonly ogImageUrl?: string;
}

// ---------------------------------------------------------------------------
// The page
// ---------------------------------------------------------------------------

export interface ProductPage {
  readonly id: string;
  readonly slug: string;
  readonly name: string;
  /** Short supporting line under the title. */
  readonly subtitle?: string;
  readonly brand?: Brand;
  readonly sku?: string;
  readonly price: Price;
  /** Ordered gallery; the first entry is treated as the hero image. */
  readonly images: readonly ProductImage[];
  readonly description: ProductDescription;
  readonly availability?: Availability;
  readonly rating?: Rating;
  readonly breadcrumbs?: readonly Breadcrumb[];
  readonly seo?: SeoMeta;
}

// ===========================================================================
// Helpers
// ===========================================================================

/** Narrow a description to its rich-text blocks. */
export function isRichText(
  description: ProductDescription,
): description is Extract<ProductDescription, { format: 'richtext' }> {
  return description.format === 'richtext';
}

/** Format minor units as a localized currency string. */
export function formatMoney(
  money: Money,
  locale = 'en-US',
): string {
  return new Intl.NumberFormat(locale, {
    style: 'currency',
    currency: money.currency,
  }).format(money.amount / 100);
}

/** Compute the discount percentage between two prices, if any. */
export function discountPercent(price: Price): number | undefined {
  if (!price.compareAt || price.compareAt.amount <= price.current.amount) {
    return undefined;
  }
  return Math.round(
    ((price.compareAt.amount - price.current.amount) / price.compareAt.amount) * 100,
  );
}
