### Notes

- If you prefer `exactOptionalPropertyTypes`, the optional fields above are already written so `undefined` must be passed explicitly rather than omitted — drop the `?` and use `| undefined` if you'd rather have the opposite behavior.
- For runtime validation at the API boundary, these types map cleanly onto a Zod schema (or Valibot) using `z.discriminatedUnion('format', ...)` for the description and `z.discriminatedUnion('type', ...)` for the rich-text blocks.
- If the description will only ever be authored in one format, you can collapse `ProductDescription` to a single interface and delete the union — the union is mainly there to let the CMS switch formats without a breaking change.

Below is a self-contained type module for a product page. The interesting parts are the **branded primitives** (so you can't pass a `number` where minor units belong), the **discriminated unions** for rich text, and the **`format` switch** on the description.

```ts
// ============================================================================
// Branded primitives — prevent accidental mixing of similar-looking values
// ============================================================================

type Brand<T, B extends string> = T & { readonly __brand: B };

/** ISO 4217 code, e.g. "USD", "EUR" */
export type CurrencyCode = Brand<string, "CurrencyCode">;

/** Integer amount in the currency's *minor* unit (cents, pence, …) */
export type MinorUnits = Brand<number, "MinorUnits">;

/** Absolute URL string */
export type Url = Brand<string, "Url">;

/** ISO-8601 timestamp, e.g. "2024-03-01T10:00:00Z" */
export type ISODateTime = Brand<string, "ISODateTime">;

/** Stable product identifier (UUID, SKU, …) */
export type ProductId = Brand<string, "ProductId">;

// ============================================================================
// Money
// ============================================================================

export interface Money {
  /** Integer minor units. 1999 === $19.99 for USD. */
  readonly amount: MinorUnits;
  readonly currency: CurrencyCode;
}

/** A price that may be a single value or a range ("from $10"). */
export type Price =
  | { readonly kind: "fixed"; readonly value: Money }
  | { readonly kind: "range"; readonly min: Money; readonly max?: Money }
  | { readonly kind: "unavailable" };

// ============================================================================
// Images
// ============================================================================

export type ImageRole = "thumbnail" | "hero" | "gallery" | "detail" | "swatch";

export interface ImageSource {
  readonly url: Url;
  readonly width: number;
  readonly height: number;
  /** e.g. "2x" */
  readonly descriptor?: string;
}

export interface ProductImage {
  readonly id: string;
  /** Primary, always-present source. */
  readonly url: Url;
  /** Required for a11y — describe the image, don't stuff keywords in. */
  readonly alt: string;
  readonly width: number;
  readonly height: number;
  readonly role: ImageRole;
  /** Responsive candidates, ascending by width. */
  readonly srcSet?: ReadonlyArray<ImageSource>;
  /** Tiny base64 placeholder for blur-up loading. */
  readonly blurDataUrl?: string;
  /** Dominant colour for the placeholder background. */
  readonly backgroundColor?: `#${string}`;
}

// ============================================================================
// Rich-text description
// ============================================================================

/** Inline formatting applied to a text run. */
export type TextMark =
  | "bold"
  | "italic"
  | "underline"
  | "strikethrough"
  | "code"
  | "superscript"
  | "subscript"
  | "highlight";

export interface TextNode {
  readonly type: "text";
  readonly value: string;
  readonly marks?: ReadonlyArray<TextMark>;
}

export interface LinkNode {
  readonly type: "link";
  readonly href: Url;
  /** Opens in a new tab? Set `rel` accordingly. */
  readonly external?: boolean;
  readonly title?: string;
  readonly children: ReadonlyArray<InlineNode>;
}

export interface LineBreakNode {
  readonly type: "lineBreak";
}

/** @mention of a user or entity (reviews, Q&A, …). */
export interface MentionNode {
  readonly type: "mention";
  readonly entityId: string;
  readonly label: string;
}

export interface EmojiNode {
  readonly type: "emoji";
  readonly shortcode: string;
}

export type InlineNode =
  | TextNode
  | LinkNode
  | LineBreakNode
  | MentionNode
  | EmojiNode;

export interface ListItem {
  readonly id?: string;
  readonly children: ReadonlyArray<InlineNode>;
  /** Nested blocks (sub-lists, code, …). */
  readonly blocks?: ReadonlyArray<BlockNode>;
}

export interface TableCell {
  readonly header?: boolean;
  readonly children: ReadonlyArray<InlineNode>;
}

export interface TableNode {
  readonly type: "table";
  readonly rows: ReadonlyArray<ReadonlyArray<TableCell>>;
  readonly caption?: ReadonlyArray<InlineNode>;
}

// --- Block nodes -----------------------------------------------------------

export interface ParagraphNode {
  readonly type: "paragraph";
  readonly children: ReadonlyArray<InlineNode>;
}

export interface HeadingNode {
  readonly type: "heading";
  /** 1–6 */
  readonly level: 1 | 2 | 3 | 4 | 5 | 6;
  readonly children: ReadonlyArray<InlineNode>;
  readonly anchorId?: string;
}

export interface ListNode {
  readonly type: "list";
  readonly ordered: boolean;
  readonly start?: number;
  readonly items: ReadonlyArray<ListItem>;
}

export interface QuoteNode {
  readonly type: "quote";
  readonly children: ReadonlyArray<BlockNode>;
  readonly attribution?: string;
}

export interface CodeBlockNode {
  readonly type: "codeBlock";
  readonly language?: string;
  readonly value: string;
}

export interface ImageBlockNode {
  readonly type: "image";
  readonly image: ProductImage;
  readonly caption?: ReadonlyArray<InlineNode>;
}

export interface DividerNode {
  readonly type: "divider";
}

export type CalloutVariant = "info" | "warning" | "success" | "danger" | "tip";

export interface CalloutNode {
  readonly type: "callout";
  readonly variant: CalloutVariant;
  readonly title?: string;
  readonly children: ReadonlyArray<BlockNode>;
}

export interface VideoNode {
  readonly type: "video";
  readonly url: Url;
  readonly poster?: Url;
  readonly caption?: ReadonlyArray<InlineNode>;
}

export type BlockNode =
  | ParagraphNode
  | HeadingNode
  | ListNode
  | QuoteNode
  | CodeBlockNode
  | ImageBlockNode
  | TableNode
  | DividerNode
  | CalloutNode
  | VideoNode;

/**
 * The description may arrive from the CMS in several shapes. Switch on
 * `format` to narrow to the right payload.
 */
export type Description =
  | { readonly format: "blocks"; readonly blocks: ReadonlyArray<BlockNode> }
  | { readonly format: "markdown"; readonly source: string }
  | { readonly format: "html"; readonly html: string }
  | { readonly format: "plain"; readonly text: string };

// ============================================================================
// Product
// ============================================================================

export interface BrandInfo {
  readonly name: string;
  readonly logoUrl?: Url;
  readonly href?: Url;
}

export interface ProductOptionValue {
  readonly id: string;
  readonly label: string;
  readonly swatchUrl?: Url;
  readonly swatchColor?: `#${string}`;
  /** Price delta applied when this option is selected. */
  readonly priceDelta?: Money;
  readonly available: boolean;
}

export interface ProductOption {
  readonly id: string;
  readonly name: string;
  readonly values: ReadonlyArray<ProductOptionValue>;
}

export interface ProductVariant {
  readonly id: string;
  readonly sku?: string;
  /** Map of option id → option value id. */
  readonly options: Readonly<Record<string, string>>;
  readonly price: Price;
  readonly stock: number;
  readonly imageId?: string;
}

export type Availability = "in_stock" | "low_stock" | "out_of_stock" | "preorder";

export interface RatingSummary {
  readonly average: number;
  readonly count: number;
  readonly histogram?: Readonly<Record<1 | 2 | 3 | 4 | 5, number>>;
}

export interface Product {
  readonly id: ProductId;
  readonly slug: string;
  readonly name: string;
  readonly subtitle?: string;
  readonly brand?: BrandInfo;
  readonly sku?: string;

  readonly price: Price;
  /** Original price, shown struck through. */
  readonly compareAtPrice?: Money;

  /** Hero first, then gallery. */
  readonly images: ReadonlyArray<ProductImage>;
  readonly description: Description;

  readonly options?: ReadonlyArray<ProductOption>;
  readonly variants?: ReadonlyArray<ProductVariant>;
  readonly availability: Availability;
  readonly rating?: RatingSummary;

  readonly tags?: ReadonlyArray<string>;
  readonly createdAt: ISODateTime;
  readonly updatedAt: ISODateTime;
}

// ============================================================================
// Page-level view model
// ============================================================================

export type ProductPageState =
  | { readonly status: "loading" }
  | { readonly status: "error"; readonly error: { readonly message: string; readonly code?: string } }
  | { readonly status: "ready"; readonly product: Product; readonly related?: ReadonlyArray<Product> };

export interface ProductPageProps {
  readonly productId: ProductId;
  readonly locale?: string;
  readonly currency?: CurrencyCode;
}
