### Notes

- **Money as minor units** avoids float drift (`19.99` → `19.989999…`). If your API only returns decimals, parse once at the boundary: `Math.round(parseFloat(x) * 100) as MinorUnits`.
- **The description is a structured AST**, not a string. That keeps rendering safe (no `dangerouslySetInnerHTML`) and lets you style marks, headings, and callouts per design system. If your CMS is Markdown-only, keep the `markdown` variant and parse it once server-side into `blocks`.
- **These types are compile-time only.** Validate at the API boundary with a runtime schema (Zod/Valibot) or a generated OpenAPI client — a `satisfies Product` check won't catch a malformed API response.

Below is a practical, self-contained type model. The description is modeled as **structured content blocks** (rather than an HTML string), so the UI can render it safely and style it however it likes.

```ts
// ---------------------------------------------------------------------------
// Primitives
// ---------------------------------------------------------------------------

/** ISO 4217 currency code. The `(string & {})` member keeps autocomplete while
 *  still allowing any valid currency. */
export type CurrencyCode =
  | 'USD' | 'EUR' | 'GBP' | 'JPY' | 'CAD' | 'AUD' | 'CHF' | 'SEK' | 'NOK' | 'DKK'
  | (string & {});

export interface Money {
  /** Decimal amount in major units, e.g. 19.99 for $19.99. */
  amount: number;
  currency: CurrencyCode;
  /** Optional pre-formatted string for display, e.g. "$19.99" or "19,99 €". */
  display?: string;
}

// ---------------------------------------------------------------------------
// Images
// ---------------------------------------------------------------------------

export type ImageRole = 'primary' | 'gallery' | 'thumbnail';

export interface ProductImage {
  id: string;
  /** Absolute or root-relative URL. */
  url: string;
  /** Alternative text — required for accessibility. */
  alt: string;
  /** Intrinsic dimensions, useful to avoid layout shift. */
  width?: number;
  height?: number;
  /** Optional responsive sources for the same image. */
  srcSet?: Array<{ url: string; width: number }>;
  role?: ImageRole;
}

// ---------------------------------------------------------------------------
// Rich text (long description with formatting)
// ---------------------------------------------------------------------------

export type TextMark =
  | 'bold'
  | 'italic'
  | 'underline'
  | 'strikethrough'
  | 'code'
  | 'superscript'
  | 'subscript';

/** Inline content inside a block. */
export type InlineNode =
  | { type: 'text'; value: string; marks?: TextMark[] }
  | { type: 'link'; href: string; children: InlineNode[]; marks?: TextMark[] }
  | { type: 'break' };

export interface ParagraphBlock {
  type: 'paragraph';
  content: InlineNode[];
}

export interface HeadingBlock {
  type: 'heading';
  /** 1–6 */
  level: 1 | 2 | 3 | 4 | 5 | 6;
  content: InlineNode[];
}

export interface ListItem {
  content: InlineNode[];
  /** Nested sub-list. */
  children?: ListItem[];
}

export interface ListBlock {
  type: 'list';
  style: 'ordered' | 'unordered';
  /** Starting number for ordered lists. */
  start?: number;
  items: ListItem[];
}

export interface QuoteBlock {
  type: 'quote';
  content: InlineNode[];
  /** Attribution / source. */
  cite?: string;
}

export interface ImageBlock {
  type: 'image';
  image: ProductImage;
  caption?: InlineNode[];
}

export interface CodeBlock {
  type: 'code';
  code: string;
  language?: string;
}

export interface DividerBlock {
  type: 'divider';
}

export interface TableBlock {
  type: 'table';
  head: string[];
  rows: string[][];
  caption?: string;
}

/** Discriminated union of every block the description can contain. */
export type DescriptionBlock =
  | ParagraphBlock
  | HeadingBlock
  | ListBlock
  | QuoteBlock
  | ImageBlock
  | CodeBlock
  | DividerBlock
  | TableBlock;

export interface RichText {
  /** Schema version, so the renderer can migrate old content. */
  version: 1;
  blocks: DescriptionBlock[];
  /** Plain-text projection, handy for SEO, previews, and search indexing. */
  plainText?: string;
}

// ---------------------------------------------------------------------------
// Product page
// ---------------------------------------------------------------------------

export type Availability = 'in_stock' | 'out_of_stock' | 'preorder' | 'backorder';

export interface ProductPage {
  id: string;
  slug: string;
  name: string;
  /** Short tagline shown under the name. */
  subtitle?: string;
  price: Money;
  /** Original price for showing a discount. */
  compareAtPrice?: Money;
  /** Ordered list; the first image is usually the primary one. */
  images: ProductImage[];
  description: RichText;
  availability?: Availability;
  sku?: string;
  brand?: string;
  rating?: { value: number; count: number };
}
