### Design notes

- **Price** is an object rather than a bare `number`, so currency and discount pricing can't be confused or lost. Use integer minor units (cents) instead of `amount` if you need exact arithmetic.
- **Images** carry `alt` text and optional intrinsic dimensions to avoid CLS and accessibility regressions.
- **Description** is a discriminated union (`block.type`), so a renderer can `switch` on `type` and get exhaustive checking — adding a new block type becomes a compile error everywhere it must be handled.
- **Inline formatting** uses a `marks` array, which maps cleanly to HTML (`<strong>`, `<em>`, …) or to React Native / native styling.
- If you must accept arbitrary HTML from a CMS, keep the block model for your own content and add a separate `html?: string` field with sanitization at render time — don't store untrusted HTML as the source of truth.

Below is a complete, practical set of types. The main ideas:

- **Money is stored in minor units** (cents) as an integer, with the currency alongside it — never a float.
- **Descriptions are a discriminated union** on `format`, so a plain-text description and a rich-text one can't be confused.
- **Rich text is a list of typed blocks**, which is easier to render safely than raw HTML.

```ts
/* ------------------------------------------------------------------ */
/* Primitives                                                          */
/* ------------------------------------------------------------------ */

/** ISO 4217 code. The `(string & {})` keeps autocomplete while allowing any code. */
export type CurrencyCode = "USD" | "EUR" | "GBP" | "JPY" | (string & {});

/**
 * A monetary amount in the currency's *minor* unit (e.g. 1999 = $19.99).
 * Integers avoid floating-point rounding errors.
 */
export interface Money {
  /** Minor units, e.g. cents. Non-negative integer. */
  readonly amount: number;
  readonly currency: CurrencyCode;
}

/** Price as shown to the user, including optional "was" price and discount. */
export interface Price {
  readonly current: Money;
  /** Original price before a discount, if any. */
  readonly compareAt?: Money;
  /** True when `compareAt` exists and is greater than `current`. */
  readonly onSale: boolean;
  /** Precomputed percentage off, 0–100, rounded. */
  readonly discountPercent?: number;
}

/* ------------------------------------------------------------------ */
/* Media                                                               */
/* ------------------------------------------------------------------ */

export interface ProductImage {
  readonly id: string;
  /** Absolute URL or a path resolvable by your image loader. */
  readonly url: string;
  /** Required for accessibility — don't leave it empty. */
  readonly alt: string;
  readonly width?: number;
  readonly height?: number;
  /** Marks the thumbnail used in listings, OG tags, and the gallery's first slide. */
  readonly isPrimary?: boolean;
}

/* ------------------------------------------------------------------ */
/* Rich-text description                                               */
/* ------------------------------------------------------------------ */

export interface ParagraphBlock {
  readonly type: "paragraph";
  readonly text: string;
}

export interface HeadingBlock {
  readonly type: "heading";
  /** H1 is reserved for the product name. */
  readonly level: 2 | 3 | 4;
  readonly text: string;
}

export interface ListBlock {
  readonly type: "list";
  readonly style: "ordered" | "unordered";
  readonly items: readonly string[];
}

export interface QuoteBlock {
  readonly type: "quote";
  readonly text: string;
  readonly attribution?: string;
}

export interface ImageBlock {
  readonly type: "image";
  readonly image: ProductImage;
  readonly caption?: string;
}

export interface CodeBlock {
  readonly type: "code";
  readonly code: string;
  readonly language?: string;
}

export interface LinkBlock {
  readonly type: "link";
  readonly text: string;
  readonly href: string;
  readonly external?: boolean;
}

export interface TableBlock {
  readonly type: "table";
  readonly headers: readonly string[];
  readonly rows: readonly (readonly string[])[];
}

/** Every block allowed inside a rich-text description. */
export type DescriptionBlock =
  | ParagraphBlock
  | HeadingBlock
  | ListBlock
  | QuoteBlock
  | ImageBlock
  | CodeBlock
  | LinkBlock
  | TableBlock;

/**
 * The description is one of three shapes:
 * - `plain`   → a single string
 * - `rich`    → structured blocks
 * - `markdown`→ a Markdown source string
 */
export type ProductDescription =
  | { readonly format: "plain"; readonly text: string }
  | { readonly format: "rich"; readonly blocks: readonly DescriptionBlock[] }
  | { readonly format: "markdown"; readonly markdown: string };

/* ------------------------------------------------------------------ */
/* Variants / inventory                                                */
/* ------------------------------------------------------------------ */

export interface ProductVariant {
  readonly id: string;
  readonly sku: string;
  /** Human-readable option values, e.g. `{ Size: "M", Color: "Black" }`. */
  readonly options: Readonly<Record<string, string>>;
  readonly price: Price;
  readonly image?: ProductImage;
  readonly inStock: boolean;
  /** Units available; omit if you don't track counts. */
  readonly quantityAvailable?: number;
}

/* ------------------------------------------------------------------ */
/* Social proof                                                        */
/* ------------------------------------------------------------------ */

export interface RatingSummary {
  readonly average: number; // 0–5
  readonly count: number;
  readonly histogram?: Readonly<Record<1 | 2 | 3 | 4 | 5, number>>;
}

/* ------------------------------------------------------------------ */
/* Product                                                             */
/* ------------------------------------------------------------------ */

export interface Product {
  readonly id: string;
  readonly slug: string;
  readonly name: string;
  /** Short marketing line shown under the title. */
  readonly subtitle?: string;
  readonly brand?: string;
  readonly sku?: string;

  readonly price: Price;
  /** Lowest and highest price across variants, when they differ. */
  readonly priceRange?: { readonly min: Money; readonly max: Money };

  readonly images: readonly ProductImage[];
  readonly description: ProductDescription;

  readonly variants?: readonly ProductVariant[];
  readonly rating?: RatingSummary;
  readonly tags?: readonly string[];
  readonly category?: { readonly id: string; readonly name: string; readonly slug: string };

  readonly createdAt: string; // ISO 8601
  readonly updatedAt: string; // ISO 8601
}

/* ------------------------------------------------------------------ */
/* The page payload                                                    */
/* ------------------------------------------------------------------ */

export interface Breadcrumb {
  readonly label: string;
  readonly href: string;
}

export interface ProductPage {
  readonly product: Product;
  readonly breadcrumbs: readonly Breadcrumb[];
  readonly relatedProducts?: readonly Product[];
  readonly availability?: {
    readonly status: "in_stock" | "out_of_stock" | "preorder" | "backorder";
    /** ISO 8601 date for preorder/backorder releases. */
    readonly releaseDate?: string;
    readonly message?: string;
  };
  readonly seo?: {
    readonly title?: string;
    readonly description?: string;
    readonly ogImage?: ProductImage;
    readonly canonicalUrl?: string;
