**Design notes**
- Prices are stored in **minor units** (`24900` = $249.00) to avoid float rounding.
- The rich-text model is a discriminated union (`type`), so `switch (block.type)` narrows correctly and each block type can carry its own fields.
- Images are referenced by `id` from variants and embedded blocks, so the gallery stays the single source of truth.

Below is a complete, production-shaped type module. It uses **branded IDs**, **integer minor units for money** (never floats), a **discriminated union for the rich-text description**, and an aggregate `ProductPage` type.

```ts
// ============================================================================
// product.types.ts
// ============================================================================

// ----------------------------------------------------------------------------
// 1. Branded primitives — prevents accidentally passing a ProductId where an
//    ImageId (or a plain string) is expected.
// ----------------------------------------------------------------------------

declare const brand: unique symbol;

type Brand<T, B extends string> = T & { readonly [brand]: B };

export type ProductId = Brand<string, "ProductId">;
export type ImageId = Brand<string, "ImageId">;
export type Sku = Brand<string, "Sku">;
export type VariantId = Brand<string, "VariantId">;

/** ISO 4217 code. Extend as needed. */
export type CurrencyCode =
  | "USD" | "EUR" | "GBP" | "JPY" | "CAD" | "AUD" | "CHF" | "SEK" | "NOK" | "DKK";

/** ISO 8601 timestamp, e.g. "2024-03-01T12:00:00.000Z". */
export type IsoDateTime = Brand<string, "IsoDateTime">;

// ----------------------------------------------------------------------------
// 2. Money & pricing
// ----------------------------------------------------------------------------

/**
 * Monetary amount stored in the currency's *minor units* (cents, pence, yen).
 * Avoids floating-point rounding errors entirely.
 */
export interface Money {
  readonly amount: number; // integer minor units, e.g. 1999 === $19.99
  readonly currency: CurrencyCode;
}

/** A price can be a single amount, a range, a "from" price, or unlisted. */
export type Price =
  | { readonly kind: "fixed"; readonly amount: Money }
  | { readonly kind: "from"; readonly amount: Money }
  | { readonly kind: "range"; readonly min: Money; readonly max: Money }
  | { readonly kind: "sale"; readonly amount: Money; readonly compareAt: Money }
  | { readonly kind: "unavailable" };

// ----------------------------------------------------------------------------
// 3. Images
// ----------------------------------------------------------------------------

export type ImageRole = "primary" | "gallery" | "thumbnail" | "swatch";

/** A responsive rendition of the same image (e.g. zoom, thumbnail, mobile). */
export interface ImageVariant {
  readonly label: string; // "thumbnail" | "zoom" | "mobile" ...
  readonly src: string;
  readonly width: number;
  readonly height: number;
}

export interface ProductImage {
  readonly id: ImageId;
  readonly src: string;
  /** Required for a11y — describe the image, don't stuff keywords in. */
  readonly alt: string;
  readonly width: number;
  readonly height: number;
  readonly role: ImageRole;
  readonly variants?: readonly ImageVariant[];
  /** Optional dominant color for placeholder skeletons. */
  readonly placeholderColor?: `#${string}`;
}

// ----------------------------------------------------------------------------
// 4. Rich-text description
// ----------------------------------------------------------------------------

/** Inline emphasis applied to a text run. */
export type Mark =
  | "bold"
  | "italic"
  | "underline"
  | "strikethrough"
  | "code"
  | "highlight"
  | "superscript"
  | "subscript";

/** Leaf node: a run of text with optional formatting marks. */
export interface TextNode {
  readonly type: "text";
  readonly value: string;
  readonly marks?: readonly Mark[];
}

/** Hyperlink. `href` may be relative or absolute. */
export interface LinkNode {
  readonly type: "link";
  readonly href: string;
  readonly title?: string;
  readonly children: readonly InlineNode[];
}

/** Inline image inside prose (not the gallery). */
export interface InlineImageNode {
  readonly type: "image";
  readonly image: ProductImage;
  readonly caption?: string;
}

export interface LineBreakNode {
  readonly type: "lineBreak";
}

export type InlineNode = TextNode | LinkNode | InlineImageNode | LineBreakNode;

// --- Block-level nodes ------------------------------------------------------

export interface ParagraphBlock {
  readonly type: "paragraph";
  readonly children: readonly InlineNode[];
}

export interface HeadingBlock {
  readonly type: "heading";
  readonly level: 1 | 2 | 3 | 4 | 5 | 6;
  readonly children: readonly InlineNode[];
}

export interface ListItem {
  readonly children: readonly InlineNode[];
  /** Nested blocks (sub-lists, paragraphs) rendered inside the item. */
  readonly blocks?: readonly DescriptionBlock[];
}

export interface BulletedListBlock {
  readonly type: "bulletedList";
  readonly items: readonly ListItem[];
}

export interface NumberedListBlock {
  readonly type: "numberedList";
  readonly items: readonly ListItem[];
  readonly start?: number;
}

export interface BlockquoteBlock {
  readonly type: "blockquote";
  readonly children: readonly InlineNode[];
  /** Attribution, e.g. a customer quote. */
  readonly cite?: string;
}

export interface CodeBlock {
  readonly type: "codeBlock";
  readonly code: string;
  readonly language?: string;
  readonly filename?: string;
}

export interface ImageBlock {
  readonly type: "image";
  readonly image: ProductImage;
  readonly caption?: string;
}

export interface TableCell {
  readonly children: readonly InlineNode[];
  readonly header?: boolean;
  readonly colSpan?: number;
  readonly rowSpan?: number;
}

export interface TableRow {
  readonly cells: readonly TableCell[];
}

export interface TableBlock {
  readonly type: "table";
  readonly rows: readonly TableRow[];
  readonly caption?: string;
}

export interface DividerBlock {
  readonly type: "divider";
}

export interface CalloutBlock {
  readonly type: "callout";
  readonly tone: "info" | "success" | "warning" | "danger";
  readonly children: readonly InlineNode[];
}

/** The full set of blocks allowed in a product description. */
export type DescriptionBlock =
  | ParagraphBlock
  | HeadingBlock
  | BulletedListBlock
  | NumberedListBlock
  | BlockquoteBlock
  | CodeBlock
  | ImageBlock
  | TableBlock
  | DividerBlock
  | CalloutBlock;

/** A document is just an ordered list of blocks. */
export interface RichText {
  readonly type: "doc";
  readonly blocks: readonly DescriptionBlock[];
}

// ----------------------------------------------------------------------------
// 5. Supporting product data
// ----------------------------------------------------------------------------

export type Availability =
  | { readonly status: "inStock"; readonly quantity?: number }
  | { readonly status: "outOfStock" }
  | { readonly status: "preorder"; readonly shipsAt?: IsoDateTime }
  | { readonly status: "backorder" }
  | { readonly status: "discontinued"; readonly replacedBy?: ProductId };

export interface Rating {
  readonly average: number; // 0–5
  readonly count: number;
  readonly histogram?: readonly number[]; // counts per star, 5 entries
}

/** A selectable option (size, color, ...) with its own price/stock. */
export interface ProductOption {
  readonly name: string; // "Size"
  readonly values: readonly ProductOptionValue[];
}

export interface ProductOptionValue {
  readonly label: string; // "Large"
  readonly value: string; // machine-readable
  readonly priceAdjustment?: Money;
  readonly inStock: boolean;
  readonly image?: ProductImage;
}

export interface ProductVariant {
  readonly id: VariantId;
  readonly sku: Sku;
  readonly options: Readonly<Record<string, string>>; // { Size: "Large", Color: "Black" }
  readonly price: Price;
  readonly availability: Availability;
  readonly image?: ProductImage;
}

/** Spec-sheet style attribute (e.g. "Material" -> "Organic cotton"). */
export interface ProductAttribute {
  readonly name: string;
  readonly value: string | readonly string[];
  readonly group?: string;
}

export interface Breadcrumb {
  readonly label: string;
  readonly href: string;
}

export interface SeoMeta {
  readonly title: string;
  readonly description: string;
  readonly canonicalUrl?: string;
  readonly ogImage?: ProductImage;
}

// ----------------------------------------------------------------------------
// 6. The aggregate
// ----------------------------------------------------------------------------

export interface ProductPage {
  readonly id: ProductId;
  readonly slug: string;
  readonly name: string;
  readonly subtitle?: string;
  readonly brand?: string;
  readonly price: Price;
  /** Gallery images. The one with role "primary" is the hero. */
  readonly images: readonly ProductImage[];
  /** Long-form, formatted description. */
  readonly description: RichText;
  readonly availability: Availability;
  readonly rating?: Rating;
  readonly sku?: Sku;
  readonly options?: readonly ProductOption[];
  readonly variants?: readonly ProductVariant[];
  readonly attributes?: readonly ProductAttribute[];
  readonly breadcrumbs?: readonly Breadcrumb[];
  readonly seo?: SeoMeta;
  readonly updatedAt: IsoDateTime;
}
