### Type guards and helpers

```ts
// guards.ts
import type {
  InlineNode, DescriptionBlock, Money, Price, ProductImage, RichText,
} from "./product.types";

export const isText = (n: InlineNode): n is Extract<InlineNode, { type: "text" }> =>
  n.type === "text";

export const isLink = (n: InlineNode): n is Extract<InlineNode, { type: "link" }> =>
  n.type === "link";

export const isBlock = (b: DescriptionBlock): b is ParagraphBlock => b.type === "paragraph";

export const isHeading = (b: DescriptionBlock): b is HeadingBlock => b.type === "heading";

/** Flatten a rich-text doc to plain text (for meta descriptions, search, etc.). */
export function toPlainText(doc: RichText): string {
  const inline = (nodes: readonly InlineNode[]): string =>
    nodes
      .map((n) =>
        n.type === "text" ? n.value
        : n.type === "link" ? inline(n.children)
        : n.type === "lineBreak" ? "\n"
        : "",
      )
      .join("");

  return doc.blocks
    .map((b) => {
      switch (b.type) {
        case "paragraph":
        case "heading":
        case "blockquote":
        case "callout":
          return inline(b.children);
        case "bulletedList":
        case "numberedList":
          return b.items.map((i) => inline(i.children)).join("\n");
        case "codeBlock":
          return b.code;
        case "image":
          return b.caption ?? "";
        case "table":
          return b.rows.map((r) => r.cells.map((c) => inline(c.children)).join(" ")).join("\n");
        case "divider":
          return "";
      }
    })
    .filter(Boolean)
    .join("\n\n");
}

/** Format minor units using the locale's own currency rules (JPY has 0 decimals). */
export function formatMoney(money: Money, locale = "en-US"): string {
  const digits = new Intl.NumberFormat(locale, {
    style: "currency",
    currency: money.currency,
  }).resolvedOptions().maximumFractionDigits;

  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency: money.currency,
  }).format(money.amount / 10 ** digits);
}

/** The hero image, falling back to the first gallery image. */
export function primaryImage(images: readonly ProductImage[]): ProductImage | undefined {
  return images.find((i) => i.role === "primary") ?? images[0];
}
