**Design notes**

- **Money as integers** — floats like `19.99` accumulate rounding error; `2499` + currency code is exact and trivially serializable.
- **Discriminated unions everywhere** — `switch (block.type)` gives exhaustive checking; adding a block type surfaces every unhandled site at compile time.
- **`readonly` + `readonly T[]`** — models immutability of fetched API data and prevents accidental mutation of cached state.
- **Branded IDs** — `ProductId` and `ImageId` are structurally `string`, so they still serialize as plain strings, but the compiler rejects cross-assignment.
- **Separate `RichText` from `ProductPage`** — the same description type can be reused for reviews, blog posts, or CMS content.

Below is a self-contained `types/product.ts` you can drop into a project. The four things you asked for are modeled carefully: **price** avoids floating‑point money bugs, **images** carry the metadata a UI needs (dimensions, alt text, responsive sources), and the **description** is a typed rich‑text tree rather than an HTML string.

```ts
// types/product.ts

/* ------------------------------------------------------------------ *
 * Primitives
 * ------------------------------------------------------------------ */

declare const brand: unique symbol;
export type Brand<T, B extends string> = T & { readonly [brand]: B };

export type ProductId = Brand<string, 'ProductId'>;
export type Sku = Brand<string, 'Sku'>;

/** ISO 4217. The `(string & {})` member keeps autocomplete while allowing any code. */
export type CurrencyCode =
  | 'USD' | 'EUR' | 'GBP' | 'JPY' | 'CAD' | 'AUD' | 'CHF' | 'SEK' | 'NOK' | 'DKK'
  | (string & {});

/* ------------------------------------------------------------------ *
 * Price
 * ------------------------------------------------------------------ */

/**
 * A monetary amount.
 * `amount` is expressed in the currency's *minor unit* (cents for USD,
 * yen for JPY) so that no floating point rounding is ever introduced.
 */
export interface Money {
  readonly amount: number;
  readonly currency: CurrencyCode;
}

export interface SinglePrice extends Money {
  readonly kind: 'single';
}

/** For "from $X" / "between $X and $Y" products. */
export interface PriceRange {
  readonly kind: 'range';
  readonly min: Money;
  readonly max?: Money;
}

export type Price = SinglePrice | PriceRange;

/* ------------------------------------------------------------------ *
 * Images
 * ------------------------------------------------------------------ */

export type ImageRole = 'thumbnail' | 'hero' | 'gallery' | 'detail' | 'icon';

export interface ImageSource {
  readonly src: string;
  readonly width: number;
}

export interface ProductImage {
  readonly src: string;
  /** Required: decorative images should use alt="" explicitly. */
  readonly alt: string;
  readonly width: number;
  readonly height: number;
  readonly role?: ImageRole;
  /** Optional responsive candidates for `srcset`. */
  readonly srcSet?: readonly ImageSource[];
  readonly blurDataUrl?: string;
}

/* ------------------------------------------------------------------ *
 * Description (rich text)
 * ------------------------------------------------------------------ */

export type Mark =
  | 'bold'
  | 'italic'
  | 'underline'
  | 'strikethrough'
  | 'code'
  | 'highlight';

export interface TextNode {
  readonly type: 'text';
  readonly value: string;
  readonly marks?: readonly Mark[];
}

export interface LinkNode {
  readonly type: 'link';
  readonly href: string;
  readonly title?: string;
  readonly children: readonly InlineNode[];
}

export type InlineNode = TextNode | LinkNode;

export interface ListItem {
  readonly children: readonly InlineNode[];
  /** Nested list items. */
  readonly items?: readonly ListItem[];
}

export interface TableCell {
  readonly children: readonly InlineNode[];
  readonly header?: boolean;
  readonly colSpan?: number;
  readonly rowSpan?: number;
}

export interface TableRow {
  readonly cells: readonly TableCell[];
}

/** Discriminated union: switch on `type` to render. */
export type RichTextBlock =
  | { readonly type: 'paragraph'; readonly children: readonly InlineNode[] }
  | { readonly type: 'heading'; readonly level: 1 | 2 | 3 | 4; readonly children: readonly InlineNode[] }
  | { readonly type: 'list'; readonly style: 'ordered' | 'unordered'; readonly items: readonly ListItem[] }
  | { readonly type: 'quote'; readonly children: readonly InlineNode[]; readonly attribution?: string }
  | { readonly type: 'image'; readonly image: ProductImage; readonly caption?: string }
  | { readonly type: 'code'; readonly code: string; readonly language?: string }
  | { readonly type: 'table'; readonly head: readonly TableRow[]; readonly rows: readonly TableRow[] }
  | { readonly type: 'divider' };

export interface ProductDescription {
  readonly blocks: readonly RichTextBlock[];
  /** Plain-text projection, useful for SEO meta tags and search indexing. */
  readonly plainText?: string;
}

/* ------------------------------------------------------------------ *
 * Supporting page data
 * ------------------------------------------------------------------ */

export type Availability =
  | { readonly status: 'in_stock' }
  | { readonly status: 'out_of_stock' }
  | { readonly status: 'preorder'; readonly shipsOn?: string }
  | { readonly status: 'backorder'; readonly shipsOn?: string }
  | { readonly status: 'made_to_order'; readonly leadTimeDays?: number };

export interface Rating {
  readonly average: number; // 0–5
  readonly count: number;
}

export interface Breadcrumb {
  readonly label: string;
  readonly href: string;
}

export interface Seo {
  readonly title?: string;
  readonly metaDescription?: string;
  readonly canonicalUrl?: string;
}

/* ------------------------------------------------------------------ *
 * The page
 * ------------------------------------------------------------------ */

export interface ProductPage {
  readonly id: ProductId;
  readonly name: string;
  readonly slug: string;
  readonly price: Price;
  /** Array order is the display order; the first entry is the hero image. */
  readonly images: readonly ProductImage[];
  readonly description: ProductDescription;
  readonly availability?: Availability;
  readonly rating?: Rating;
  readonly breadcrumbs?: readonly Breadcrumb[];
  readonly seo?: Seo;
}

/* ------------------------------------------------------------------ *
 * Helpers
 * ------------------------------------------------------------------ */

export function assertNever(value: never): never {
  throw new Error(`Unexpected value: ${JSON.stringify(value)}`);
}

/** Minor-unit exponent per currency (JPY/KRW have no subunit). */
const MINOR_UNITS: Record<string, number> = { JPY: 0, KRW: 0, CLP: 0, ISK: 0 };

export function formatMoney(money: Money, locale = 'en-US'): string {
  const digits = MINOR_UNITS[money.currency] ?? 2;
  return new Intl.NumberFormat(locale, {
    style: 'currency',
    currency: money.currency,
  }).format(money.amount / 10 ** digits);
}
