// ---------------------------------------------------------------------------
// 2. Money
//    Amounts are stored as integers in the currency's *minor unit* (cents).
//    Never use `number` for currency amounts — 19.99 * 100 !== 1999 in float.
// ---------------------------------------------------------------------------

export interface Money {
  /** Integer amount in minor units (1999 = $19.99). */
  readonly amount: number;
  readonly currency: CurrencyCode;
}

export interface PriceRange {
  readonly min: Money;
  readonly max: Money;
}

// ---------------------------------------------------------------------------
// 3. Images
// ---------------------------------------------------------------------------

export interface ImageSource {
  readonly url: string;
  readonly width: number;
  readonly height: number;
  readonly mimeType?: string;
  /** Present for AVIF/WebP variants. */
  readonly format?: 'jpeg' | 'png' | 'webp' | 'avif' | 'gif' | 'svg';
