// ---------------------------------------------------------------------------
// 4. Rich text description
//    A structured document AST rather than raw HTML/markdown strings:
//      - safe to render (no XSS from stored content)
//      - format-agnostic (render to HTML, React, PDF, native, email)
//      - type-narrowable via discriminated unions
// ---------------------------------------------------------------------------

export type Mark =
  | 'bold'
  | 'italic'
  | 'underline'
  | 'strike'
  | 'code'
  | 'highlight'
  | 'superscript'
  | 'subscript';

export type InlineNode =
  | { readonly type: 'text'; readonly value: string; readonly marks?: readonly Mark[] }
  | {
      readonly type: 'link';
      readonly href: string;
      readonly title?: string;
      readonly rel?: 'nofollow' | 'noopener' | 'sponsored';
      readonly children: readonly InlineNode[];
    }
  | { readonly type: 'image'; readonly image: ProductImage }
  | { readonly type: 'lineBreak' }
  | { readonly type: 'mention'; readonly label: string };

export interface ListItem {
  readonly children: readonly BlockNode[];
}

export interface TableRow {
  readonly header: boolean;
  readonly cells: readonly (readonly InlineNode[])[];
}

export type BlockNode =
  | { readonly type: 'paragraph'; readonly children: readonly InlineNode[] }
  | {
      readonly type: 'heading';
      readonly level: 1 | 2 | 3 | 4 | 5 | 6;
      readonly children: readonly InlineNode[];
    }
  | { readonly type: 'bulletList'; readonly items: readonly ListItem[] }
  | { readonly type: 'orderedList'; readonly start?: number; readonly items: readonly ListItem[] }
  | { readonly type: 'blockquote'; readonly children: readonly BlockNode[] }
  | { readonly type: 'callout'; readonly tone: 'info' | 'success' | 'warning' | 'danger'; readonly children: readonly BlockNode[] }
  | { readonly type: 'codeBlock'; readonly language?: string; readonly code: string }
  | { readonly type: 'image'; readonly image: ProductImage; readonly caption?: string }
  | { readonly type: 'video'; readonly url: string; readonly poster?: ProductImage; readonly caption?: string }
  | { readonly type: 'table'; readonly rows: readonly TableRow[] }
  | { readonly type: 'divider' };

export interface RichTextDocument {
  readonly type: 'doc';
  /** Schema version — bump when the node shape changes so old content still renders. */
  readonly version: 1;
  readonly content: readonly BlockNode[];
}

/**
 * The description may arrive as a structured doc or as markdown from a CMS
 * that only supports markdown. Narrow on `format` to handle both.
 */
