## Helper utilities

```ts
export function formatMoney(money: Money, locale = 'en-US'): string {
  return new Intl.NumberFormat(locale, {
    style: 'currency',
    currency: money.currency,
  }).format(money.amount / 100);
}

/** Discount percentage, or undefined if there is no comparison price. */
export function discountPercent(price: Money, compareAt?: Money): number | undefined {
  if (!compareAt || compareAt.amount <= price.amount) return undefined;
  return Math.round(((compareAt.amount - price.amount) / compareAt.amount) * 100);
}

export function isOnSale(product: Product): boolean {
  return (
    product.compareAtPrice !== undefined &&
    product.compareAtPrice.amount > product.price.amount
  );
}

/** Narrow a rich-text union to the structured document. */
export function asDocument(description: RichText): RichTextDocument | undefined {
  return description.format === 'richtext' ? description.document : undefined;
}

/** Exhaustive switch over block types — add a node type and this breaks loudly. */
export function blockType(block: BlockNode): string {
  switch (block.type) {
    case 'paragraph':
    case 'heading':
    case 'bulletList':
    case 'orderedList':
    case 'blockquote':
    case 'callout':
    case 'codeBlock':
    case 'image':
    case 'video':
    case 'table':
    case 'divider':
      return block.type;
    default:
      return assertNever(block, 'block type');
  }
}
```

## Design notes

**Money as integer minor units.** `19.99` cannot be represented exactly in binary floating point, so summing line items drifts. Storing `1999` + `"USD"` and dividing only at display time avoids the problem entirely. If your backend genuinely sends decimal strings (`"19.99"`), change `amount` to `string` and parse with a decimal library instead.

**Structured rich text over HTML.** Storing HTML in the database means you must sanitize on every render path, and you can't reformat content for email vs. web vs. PDF. A discriminated-union AST is JSON-serializable, safe by construction, and each node type maps cleanly to a React component. The `version` field lets you migrate old documents without a flag day. The `format` wrapper also lets you accept markdown from a simpler CMS and convert it to the AST at ingestion.

**Discriminated unions everywhere.** `BlockNode`, `InlineNode`, and `RichText` all narrow on `type`/`format`, so `switch` statements are exhaustively checked and `block.type === 'heading'` gives you `level` for free.

**Required `alt` on images.** Making it optional in the type means it will be optional in practice. Required at the type level, it's enforced at every call site.

**Branded IDs.** `ProductId` and `ImageId` are both `string` underneath, so there is zero runtime cost, but `product.images[0].id` can't be passed where a `ProductId` is expected.

**Two things to add before shipping:** runtime validation (Zod or Valibot schemas mirroring these types, since TypeScript erases at runtime — a `Product` from an API is really `unknown`), and a `readonly` array discipline so shared product objects can't be mutated by a component.

Below is a production‑oriented type model. It assumes the data comes from a CMS/API, so everything is **JSON‑serializable**, **readonly**, and uses **discriminated unions** for the rich description.

```ts
/* ============================================================================
 * 1. Primitives
 * ==========================================================================*/

/** ISO 4217 currency code. */
export type CurrencyCode =
  | 'USD' | 'EUR' | 'GBP' | 'JPY' | 'CAD' | 'AUD' | 'CHF' | 'SEK' | 'NOK' | 'DKK';

/**
 * Money is stored in *minor units* (cents, pence, …) as an integer to avoid
 * floating‑point rounding errors. `1234` + 'USD' === $12.34.
 */
export interface Money {
  readonly amountMinor: number;
  readonly currency: CurrencyCode;
}

/** An absolute, https URL. */
export type HttpsUrl = string;

/** RFC 3339 timestamp, e.g. "2024-03-01T12:00:00Z". */
export type IsoDateTime = string;

/* ============================================================================
 * 2. Images
 * ==========================================================================*/

/** The role an image plays on the product page. */
export type ImageRole = 'hero' | 'gallery' | 'thumbnail' | 'zoom' | 'lifestyle';

export interface ProductImage {
  readonly id: string;
  readonly url: HttpsUrl;
  /** Required for accessibility (WCAG). */
  readonly alt: string;
  readonly width: number;
  readonly height: number;
  readonly role: ImageRole;
  /** Optional CDN hints. */
  readonly blurDataUrl?: string;
  readonly focalPoint?: { readonly x: number; readonly y: number }; // 0..1
  readonly credit?: string;
}

/** A group of images that represent the same product. */
export interface ImageSet {
  readonly hero: ProductImage;
  readonly gallery: readonly ProductImage[];
  readonly thumbnails: readonly ProductImage[];
}

/* ============================================================================
 * 3. Rich description
 * ==========================================================================*/

/** Inline text decorations. */
export type TextMark =
  | 'bold'
  | 'italic'
  | 'underline'
  | 'strikethrough'
  | 'code'
  | 'superscript'
  | 'subscript'
  | 'highlight';

/** Inline (leaf‑level) nodes that may appear inside a block. */
export type InlineNode =
  | {
      readonly type: 'text';
      readonly value: string;
      readonly marks?: readonly TextMark[];
    }
  | {
      readonly type: 'link';
      readonly href: HttpsUrl;
      readonly children: readonly InlineNode[];
      readonly rel?: 'nofollow' | 'sponsored' | 'ugc';
      readonly title?: string;
    }
  | { readonly type: 'lineBreak' };

/** A single entry in a bulleted or numbered list. */
export interface ListItem {
  readonly id: string;
  readonly children: readonly InlineNode[];
  /** Nested lists. */
  readonly childrenBlocks?: readonly Block[];
  readonly checked?: boolean; // for task lists
}

/** A simple table with a header row. */
export interface RichTable {
  readonly caption?: string;
  readonly columns: readonly { readonly key: string; readonly label: string }[];
  readonly rows: readonly (readonly { readonly [key: string]: string })[];
}

/** Block‑level (paragraph‑level) nodes. */
export type Block =
  | { readonly type: 'paragraph'; readonly children: readonly InlineNode[] }
  | {
      readonly type: 'heading';
      readonly level: 1 | 2 | 3 | 4 | 5 | 6;
      readonly children: readonly InlineNode[];
      readonly id?: string; // anchor for in-page navigation
    }
  | {
      readonly type: 'list';
      readonly style: 'ordered' | 'unordered';
      readonly items: readonly ListItem[];
      readonly start?: number;
    }
  | {
      readonly type: 'quote';
      readonly children: readonly InlineNode[];
      readonly attribution?: string;
    }
  | {
      readonly type: 'callout';
      readonly tone: 'info' | 'success' | 'warning' | 'danger';
      readonly title?: string;
      readonly children: readonly InlineNode[];
    }
  | {
      readonly type: 'code';
      readonly language?: string; // e.g. "ts"
      readonly code: string;
    }
  | {
      readonly type: 'image';
      readonly image: ProductImage;
      readonly caption?: string;
    }
  | { readonly type: 'table'; readonly table: RichTable }
  | { readonly type: 'divider' }
  | { readonly type: 'embed'; readonly provider: 'youtube' | 'vimeo'; readonly url: HttpsUrl };

/** A portable rich‑text document (the recommended format). */
export interface RichTextDocument {
  readonly type: 'doc';
  readonly version: 1;
  readonly blocks: readonly Block[];
}

/* ============================================================================
 * 4. Description — a union of the supported authoring formats
 * ==========================================================================*/

export type ProductDescription =
  | { readonly format: 'richtext'; readonly document: RichTextDocument }
  | { readonly format: 'markdown'; readonly source: string }
  | { readonly format: 'html'; readonly html: string };

/* ============================================================================
 * 5. Commercials
 * ==========================================================================*/

export type Availability =
  | { readonly status: 'in_stock'; readonly quantity?: number }
