### Notes / design decisions

- **Money as integer minor units** — `0.1 + 0.2 !== 0.3` in IEEE‑754. Store `1234` + `'USD'`, format at the edge.
- **Discriminated unions everywhere** — `Block.type`, `InlineNode.type`, `Description.format`, `Availability.status`. Switching on them gives exhaustive narrowing (`never` checks) and lets you render safely.
- **Rich text instead of raw HTML** — a structured document is renderable to React, HTML, or plain text, and is far easier to sanitize and migrate. If you must accept CMS HTML, keep the `{ format: 'html' }` branch but sanitize on ingest, never at render.
- **`alt` is required on images** — accessibility is enforced by the type system rather than by review.
- **Server-computed `discountPercent`** — avoids the client and server disagreeing on rounding.

### Exhaustiveness helper

```ts
function assertNever(x: never): never {
  throw new Error(`Unexpected variant: ${JSON.stringify(x)}`);
}

// Example: exhaustive renderer
function renderBlock(block: Block): string {
  switch (block.type) {
    case 'paragraph': return block.children.map(renderInline).join('');
    case 'heading':  return `<h${block.level}>${block.children.map(renderInline).join('')}</h${block.level}>`;
    case 'list':     return `<${block.style === 'ordered' ? 'ol' : 'ul'}>…</${block.style === 'ordered' ? 'ol' : 'ul'}>`;
    case 'quote':    return `<blockquote>…</blockquote>`;
    case 'callout':  return `<aside data-tone="${block.tone}">…</aside>`;
    case 'code':     return `<pre><code>${block.code}</code></pre>`;
    case 'image':    return `<img src="${block.image.url}" alt="${block.image.alt}">`;
    case 'table':    return `<table>…</table>`;
    case 'divider':  return '<hr>';
    case 'embed':    return `<iframe src="${block.url}"></iframe>`;
    default:         return assertNever(block); // compile error if a case is missing
  }
}
```

### Optional runtime validation

Types vanish at runtime, so pair them with a schema when the data crosses a trust boundary:

```ts
import { z } from 'zod';

const moneySchema = z.object({
  amountMinor: z.number().int().nonnegative(),
  currency: z.string().length(3),
});

const productSchema = z.object({
  id: z.string(),
  name: z.string().min(1),
  price: moneySchema,
  // …
}) satisfies z.ZodType<Product>;
```

Below is a complete, type-safe model. The description uses a **structured rich-text document** (a discriminated union of blocks and inline nodes) rather than raw HTML — this keeps formatting explicit, renderable in React/JSX, and safe against XSS.

```ts
// ---------------------------------------------------------------------------
// Money
// ---------------------------------------------------------------------------

/**
 * Currency codes. Use the literal union for autocomplete, or `string & {}`
 * to allow any ISO-4217 code while preserving editor autocomplete.
 */
export type CurrencyCode =
  | "USD" | "EUR" | "GBP" | "JPY" | "CAD" | "AUD" | "CHF" | "SEK" | "NOK" | "DKK"
  | (string & {});

export interface Money {
  /** Amount in the currency's minor unit (e.g. 1999 = $19.99). Integer only. */
  amount: number;
  currency: CurrencyCode;
}

// ---------------------------------------------------------------------------
// Images
// ---------------------------------------------------------------------------

export type ImageRole = "primary" | "thumbnail" | "gallery" | "zoom";

export interface ProductImage {
  id: string;
  /** Absolute or root-relative URL to the image. */
  url: string;
  /** Required for accessibility — describe the image's content. */
  alt: string;
  width?: number;
  height?: number;
  /** Optional responsive source set, e.g. "/img/1-400.jpg 400w, /img/1-800.jpg 800w". */
  srcSet?: string;
  /** Optional CDN transformations, e.g. { w: 800, h: 800, fit: "cover" }. */
  transforms?: ImageTransform;
  role?: ImageRole;
}

export interface ImageTransform {
  width?: number;
  height?: number;
  fit?: "cover" | "contain" | "fill" | "scale-down";
  format?: "webp" | "avif" | "jpg" | "png";
}

// ---------------------------------------------------------------------------
// Rich text: inline nodes
// ---------------------------------------------------------------------------

export type Mark =
  | "bold"
  | "italic"
  | "underline"
  | "strikethrough"
  | "code"
  | "superscript"
  | "subscript"
  | "highlight";

export interface TextNode {
  type: "text";
  value: string;
  /** Formatting applied to this run of text. */
  marks?: Mark[];
}

export interface LinkNode {
  type: "link";
  href: string;
  /** Opens in a new tab / external link. */
  external?: boolean;
  title?: string;
  children: InlineNode[];
}

export interface LineBreakNode {
  type: "lineBreak";
}

export type InlineNode = TextNode | LinkNode | LineBreakNode;

// ---------------------------------------------------------------------------
// Rich text: block nodes
// ---------------------------------------------------------------------------

export interface ParagraphBlock {
  type: "paragraph";
  children: InlineNode[];
}

export interface HeadingBlock {
  type: "heading";
  /** Heading level, 1–6. */
  level: 1 | 2 | 3 | 4 | 5 | 6;
  children: InlineNode[];
}

export interface ListItem {
  children: InlineNode[];
  /** Optional nested list rendered inside this item. */
  childrenBlocks?: BlockNode[];
}

export interface ListBlock {
  type: "list";
  ordered: boolean;
  /** Starting number for ordered lists (defaults to 1). */
  start?: number;
  items: ListItem[];
}

export interface QuoteBlock {
  type: "quote";
  children: InlineNode[];
  /** Optional attribution, e.g. "— Jane Doe, Verified Buyer". */
  attribution?: string;
}

export interface CodeBlock {
  type: "code";
  value: string;
  language?: string;
  /** Renders the code with a filename caption. */
  filename?: string;
}

export interface ImageBlock {
  type: "image";
  image: ProductImage;
  caption?: InlineNode[];
}

export interface TableBlock {
  type: "table";
  header: InlineNode[][];
  rows: InlineNode[][][];
  /** Column alignments, left-to-right. */
  align?: ("left" | "center" | "right")[];
}

export interface DividerBlock {
  type: "divider";
}

export type BlockNode =
  | ParagraphBlock
  | HeadingBlock
  | ListBlock
  | QuoteBlock
  | CodeBlock
  | ImageBlock
  | TableBlock
  | DividerBlock;

/** The root document stored as the product's long description. */
export interface RichTextDocument {
  type: "doc";
  /** Schema version for migrations. */
  version: 1;
  content: BlockNode[];
}

// ---------------------------------------------------------------------------
// Product
// ---------------------------------------------------------------------------

export interface ProductRating {
  /** Average rating, 0–5. */
  average: number;
  /** Number of ratings. */
  count: number;
}

export interface Product {
  id: string;
  slug: string;
  name: string;
  /** Short marketing tagline shown under the title. */
  tagline?: string;
  price: Money;
  /** Original price when the product is discounted. */
  compareAtPrice?: Money;
  /** All product images; the first is typically the primary one. */
  images: ProductImage[];
  /** Long, formatted description. */
  description: RichTextDocument;
  /** Optional plain-text fallback for SEO meta descriptions and search indexes. */
  descriptionPlainText?: string;
  sku?: string;
  brand?: string;
  inStock?: boolean;
  rating?: ProductRating;
  /** ISO 8601 timestamp. */
  updatedAt?: string;
}

// ---------------------------------------------------------------------------
// Narrowing helpers
// ---------------------------------------------------------------------------

export const isText = (node: InlineNode): node is TextNode => node.type === "text";
export const isLink = (node: InlineNode): node is LinkNode => node.type === "link";

export const isHeading = (block: BlockNode): block is HeadingBlock =>
  block.type === "heading";

/** Extracts plain text from any rich-text document (useful for meta tags). */
export function toPlainText(doc: RichTextDocument): string {
  const inline = (nodes: InlineNode[]): string =>
    nodes
      .map((n) => {
        switch (n.type) {
          case "text":
            return n.value;
          case "link":
            return inline(n.children);
          case "lineBreak":
            return "\n";
        }
      })
      .join("");

  return doc.content
    .map((block) => {
      switch (block.type) {
        case "paragraph":
        case "heading":
        case "quote":
          return inline(block.children);
        case "list":
          return block.items.map((i) => inline(i.children)).join("\n");
        case "code":
          return block.value;
        case "image":
          return block.caption ? inline(block.caption) : "";
        case "table":
          return [...block.header, ...block.rows.flat()]
            .map((cell) => inline(cell))
            .join(" ");
        case "divider":
          return "";
      }
    })
    .filter(Boolean)
    .join("\n\n");
}
```

