/* ============================================================================
 * Primitives
 * ==========================================================================*/

/** Nominal typing helper: prevents accidentally passing a ProductId as a Sku. */
export type Brand<T, B extends string> = T & { readonly __brand: B };

export type ProductId = Brand<string, "ProductId">;
export type ImageId = Brand<string, "ImageId">;
export type Sku = Brand<string, "Sku">;

/**
 * ISO 4217 currency code. The trailing `(string & {})` keeps literal
 * autocomplete while still allowing currencies we didn't enumerate.
 */
export type CurrencyCode =
  | "USD" | "EUR" | "GBP" | "JPY" | "CAD" | "AUD" | "CHF" | "SEK" | "NOK"
  | "DKK" | "PLN" | "CZK" | "HUF" | "INR" | "BRL" | "MXN" | "ZAR" | "AED"
  | "SAR" | "SGD" | "HKD" | "KRW" | "CNY" | "TWD" | "THB" | "TRY"
  | (string & {});

/* ============================================================================
 * Pricing
 * ==========================================================================*/

/**
 * An amount of money. `amount` is expressed in the currency's minor unit
 * (e.g. 1999 = $19.99). Integers avoid floating-point rounding errors.
 */
export interface Money {
  readonly amount: number;
  readonly currency: CurrencyCode;
}

/** Price as displayed on the product page. */
export interface Price {
  /** The price the customer actually pays. */
  readonly current: Money;
  /** Original/list price, present only when the item is discounted. */
  readonly compareAt?: Money;
  /** Whether `current` includes tax. */
  readonly taxInclusive?: boolean;
  /** Price per unit, e.g. "$2.50 / 100g". */
  readonly unitPrice?: Money & { readonly unit: string };
  /** Optional price range for variable products (min/max across variants). */
  readonly range?: { readonly min: Money; readonly max: Money };
}

/* ============================================================================
 * Images
 * ==========================================================================*/

export type ImageRole = "hero" | "gallery" | "thumbnail" | "description";

/** A single candidate for a responsive image (srcset entry). */
export interface ImageSource {
  readonly url: string;
  readonly width: number;
  /** e.g. "2x" or a width descriptor "640w". */
  readonly descriptor?: string;
}

export interface ProductImage {
  readonly id: ImageId;
  /** Absolute or CDN-relative URL. */
  readonly url: string;
  /** Required for accessibility. Describe the image, don't stuff keywords. */
  readonly alt: string;
  readonly width: number;
  readonly height: number;
  readonly role: ImageRole;
  /** Responsive candidates, ordered smallest → largest. */
  readonly srcSet?: readonly ImageSource[];
  /** Tiny base64 preview for blur-up placeholders. */
  readonly blurDataUrl?: string;
  /** Average color, used as a placeholder background. */
  readonly dominantColor?: string;
  /** Position within the gallery. */
  readonly position?: number;
}

/* ============================================================================
 * Rich text — the long description
 * ==========================================================================*/

export type TextMark =
  | "bold"
  | "italic"
  | "underline"
  | "strikethrough"
  | "code"
  | "subscript"
  | "superscript"
  | "highlight";

