## `types/product.helpers.ts`

```ts
import type {
  Money, Price, Product, ProductImage, ImageRole,
  RichTextDocument, InlineContent,
} from "./product";

/** Number of minor units per major unit for a given currency (JPY = 0, KWD = 3). */
export function minorUnitScale(currency: string): number {
  const digits = new Intl.NumberFormat("en", {
    style: "currency",
    currency,
  }).resolvedOptions().maximumFractionDigits ?? 2;
  return 10 ** digits;
}

export function formatMoney(money: Money, locale = "en-US"): string {
  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency: money.currency,
  }).format(money.amount / minorUnitScale(money.currency));
}

/** Percentage off, rounded to the nearest whole number, or undefined. */
export function getDiscountPercent(price: Price): number | undefined {
  const { current, compareAt } = price;
  if (!compareAt || compareAt.amount <= current.amount) return undefined;
  if (compareAt.currency !== current.currency) return undefined;
  return Math.round((1 - current.amount / compareAt.amount) * 100);
}

export function getImagesByRole(
  product: Product,
  role: ImageRole,
): readonly ProductImage[] {
  return product.images.filter((img) => img.role === role);
}

/** The image used as the page's main visual. */
export function getPrimaryImage(product: Product): ProductImage | undefined {
  return (
    product.images.find((i) => i.role === "hero") ??
    product.images.find((i) => i.role === "gallery") ??
    product.images[0]
  );
}

/** Protocol allowlist — blocks `javascript:` and `data:` URLs. */
const SAFE_PROTOCOLS = new Set(["http:", "https:", "mailto:", "tel:"]);

export function isSafeHref(href: string): boolean {
  try {
    const url = new URL(href, "https://example.invalid");
    return SAFE_PROTOCOLS.has(url.protocol);
  } catch {
    return false;
  }
}

/** Flatten a rich-text document to plain text (previews, meta descriptions). */
export function richTextToPlainText(doc: RichTextDocument): string {
  const parts: string[] = [];

  const inline = (content: readonly InlineContent[]): string =>
    content
      .map((node) => {
        switch (node.type) {
          case "text":
            return node.text;
          case "link":
            return node.text;
          case "lineBreak":
            return "\n";
        }
      })
      .join("");

  const walk = (blocks: RichTextDocument["blocks"]): void => {
    for (const block of blocks) {
      switch (block.type) {
        case "paragraph":
        case "heading":
        case "quote":
          parts.push(inline(block.content));
          break;
        case "list":
          for (const item of block.items) walk(item.blocks);
          break;
        case "table":
          for (const cell of block.header) parts.push(inline(cell.content));
          for (const row of block.rows)
            for (const cell of row) parts.push(inline(cell.content));
          break;
        case "callout":
          walk(block.blocks);
          break;
        case "code":
          parts.push(block.code);
          break;
        case "image":
          if (block.caption) parts.push(inline(block.caption));
          break;
        case "video":
          if (block.caption) parts.push(block.caption);
          break;
        case "divider":
          break;
      }
    }
  };

  walk(doc.blocks);
  return parts.filter(Boolean).join("\n\n");
}
```

